from (values
(337809,37535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... Wahlplakate, als die Menge zur Kundgebung kam, und ehrlich: Respekt.'::text,'klebtest gerade'::text,'klebtest'::text,'hast geklebt'::text,'Du klebtest gerade Wahlplakate, als die Menge zur Kundgebung kam, und ehrlich: Respekt.'::text),
(337813,37535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... передвиборчі плакати, коли прийшов натовп на мітинг, і чесно, респект.'::text,'клеїла'::text,'наклеїла'::text,'наклеїла'::text,'Ти клеїла передвиборчі плакати, коли прийшов натовп на мітинг, і чесно, респект.'::text),
(337812,37535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... carteles electorales cuando llegó la multitud del mitin y, sinceramente, respeto.'::text,'Estabas pegando'::text,'Pegaste'::text,'Has pegado'::text,'Estabas pegando carteles electorales cuando llegó la multitud del mitin y, sinceramente, respeto.'::text),
(337811,37535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... des affiches de campagne quand la foule du meeting est arrivée, et franchement, respect.'::text,'collais'::text,'as collé'::text,'as collé'::text,'Tu collais des affiches de campagne quand la foule du meeting est arrivée, et franchement, respect.'::text),
(337814,37535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miting kalabalığı geldiğinde seçim afişleri ..., açıkçası helal olsun.'::text,'yapıştırıyordun'::text,'yapıştırdın'::text,'yapıştırdın'::text,'Miting kalabalığı geldiğinde seçim afişleri yapıştırıyordun, açıkçası helal olsun.'::text),
(337815,37535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... választási plakátokat, amikor megérkezett a gyűlés tömege, és őszintén, le a kalappal.'::text,'épp ragasztottál'::text,'ragasztottál'::text,'ragasztottál'::text,'Te épp ragasztottál választási plakátokat, amikor megérkezett a gyűlés tömege, és őszintén, le a kalappal.'::text),
(337827,37537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... sie dreihundert Plakate für den Wahlkampf geklebt. Ein leicht geschäftiger Morgen.'::text,'hat'::text,'hat'::text,'klebt'::text,'Bisher hat sie dreihundert Plakate für den Wahlkampf geklebt. Ein leicht geschäftiger Morgen.'::text),
(337831,37537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки що вона ... триста плакатів для кампанії. Трохи насичений ранок.'::text,'наклеїла'::text,'клеїла'::text,'клеїть'::text,'Поки що вона наклеїла триста плакатів для кампанії. Трохи насичений ранок.'::text),
(337830,37537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... trescientos carteles para la campaña. Una mañana ligeramente ajetreada.'::text,'ha pegado'::text,'ha estado pegando'::text,'está pegando'::text,'Hasta ahora ha pegado trescientos carteles para la campaña. Una mañana ligeramente ajetreada.'::text),
(337829,37537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pour l''instant, elle ... trois cents affiches pour la campagne. Une matinée légèrement chargée.'::text,'a collé'::text,'a collé'::text,'colle'::text,'Pour l''instant, elle a collé trois cents affiches pour la campagne. Une matinée légèrement chargée.'::text),
(337832,37537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar kampanya için üç yüz afiş ..., hafiften yoğun bir sabah.'::text,'yapıştırdı'::text,'yapıştırıyor'::text,'yapıştırıyor'::text,'Şimdiye kadar kampanya için üç yüz afiş yapıştırdı, hafiften yoğun bir sabah.'::text),
(337833,37537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig ... háromszáz plakátot a kampányhoz. Kicsit sűrű reggel.'::text,'kiragasztott'::text,'ragasztott'::text,'ragaszt'::text,'Eddig kiragasztott háromszáz plakátot a kampányhoz. Kicsit sűrű reggel.'::text),
(337836,37538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Debatte begann, ... der Wahlkampf jede Wand der Stadt bedeckt. Leicht enthusiastisch.'::text,'hatte'::text,'hat'::text,'bedeckt'::text,'Als die Debatte begann, hatte der Wahlkampf jede Wand der Stadt bedeckt. Leicht enthusiastisch.'::text),
(337840,37538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли почалися дебати, кампанія ... кожну стіну в місті. Ледь-ледь завзято.'::text,'вже вкрила'::text,'вкрила'::text,'вкриває'::text,'Коли почалися дебати, кампанія вже вкрила кожну стіну в місті. Ледь-ледь завзято.'::text),
(337839,37538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empezó el debate, la campaña ... todas las paredes de la ciudad. Ligeramente entusiasta.'::text,'había cubierto'::text,'ha cubierto'::text,'cubre'::text,'Cuando empezó el debate, la campaña había cubierto todas las paredes de la ciudad. Ligeramente entusiasta.'::text),
(337838,37538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le débat a commencé, la campagne ... tous les murs de la ville. Légèrement enthousiaste.'::text,'avait couvert'::text,'a couvert'::text,'couvre'::text,'Quand le débat a commencé, la campagne avait couvert tous les murs de la ville. Légèrement enthousiaste.'::text),
(337841,37538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tartışma başladığında kampanya şehirdeki her duvarı ...: hafiften hevesli.'::text,'kaplamıştı'::text,'kapladı'::text,'kaplıyor'::text,'Tartışma başladığında kampanya şehirdeki her duvarı kaplamıştı: hafiften hevesli.'::text),
(337842,37538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elkezdődött a vita, a kampány ... a város minden falát. Enyhén lelkes.'::text,'már beborította'::text,'beborította'::text,'beborítja'::text,'Mire elkezdődött a vita, a kampány már beborította a város minden falát. Enyhén lelkes.'::text),
(337845,37539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn die Menge weiter so jubelt, ... diese Kampagne das Ganze, ohne Witz.'::text,'gewinnt'::text,'würde gewinnen'::text,'gewann'::text,'Digga, wenn die Menge weiter so jubelt, gewinnt diese Kampagne das Ganze, ohne Witz.'::text),
(337849,37539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо натовп і далі так вітатиме, ця кампанія ... все, без жартів.'::text,'виграє'::text,'виграла б'::text,'виграла'::text,'Бро, якщо натовп і далі так вітатиме, ця кампанія виграє все, без жартів.'::text),
(337848,37539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si la gente sigue animando así, esta campaña ... todo, en serio.'::text,'ganará'::text,'ganaría'::text,'ganó'::text,'Bro, si la gente sigue animando así, esta campaña ganará todo, en serio.'::text),
(337847,37539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si la foule continue d''acclamer comme ça, cette campagne ... tout, sans mentir.'::text,'gagnera'::text,'gagnerait'::text,'a gagné'::text,'Frérot, si la foule continue d''acclamer comme ça, cette campagne gagnera tout, sans mentir.'::text),
(337850,37539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kalabalık böyle tezahürat yapmaya devam ederse bu kampanya her şeyi ..., yalan yok.'::text,'kazanacak'::text,'kazanırdı'::text,'kazandı'::text,'Kanka, kalabalık böyle tezahürat yapmaya devam ederse bu kampanya her şeyi kazanacak, yalan yok.'::text),
(337851,37539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha a tömeg így ujjong tovább, ez a kampány ... az egészet, nem kamu.'::text,'megnyeri'::text,'megnyerné'::text,'megnyerte'::text,'Tesó, ha a tömeg így ujjong tovább, ez a kampány megnyeri az egészet, nem kamu.'::text),
(337854,37540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, wenn ich einen Wahlkampf führen würde, ... ich auf jeder einzelnen Kundgebung Konfetti werfen, echt.'::text,'würde'::text,'werde'::text,'werfe'::text,'Ehrlich gesagt, wenn ich einen Wahlkampf führen würde, würde ich auf jeder einzelnen Kundgebung Konfetti werfen, echt.'::text),
(337858,37540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я вів кампанію, я ... конфетті на кожному мітингу, реально.'::text,'кидав би'::text,'кидатиму'::text,'кидаю'::text,'Чесно, якби я вів кампанію, я кидав би конфетті на кожному мітингу, реально.'::text),
(337857,37540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si yo llevara una campaña, ... confeti en cada mitin, en serio.'::text,'tiraría'::text,'tiraré'::text,'tiro'::text,'No voy a mentir, si yo llevara una campaña, tiraría confeti en cada mitin, en serio.'::text),
(337856,37540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas de mytho, si je menais une campagne, je ... des confettis à chaque meeting, sérieux.'::text,'lancerais'::text,'lancerai'::text,'lance'::text,'Pas de mytho, si je menais une campagne, je lancerais des confettis à chaque meeting, sérieux.'::text),
(337859,37540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bir kampanya yürütsem her mitingde konfeti ..., cidden.'::text,'atardım'::text,'atacağım'::text,'atarım'::text,'Yalan yok, bir kampanya yürütsem her mitingde konfeti atardım, cidden.'::text),
(337860,37540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, ha kampányt vezetnék, minden egyes gyűlésen konfettit ..., komolyan.'::text,'szórnék'::text,'fogok szórni'::text,'szórok'::text,'Nem kamu, ha kampányt vezetnék, minden egyes gyűlésen konfettit szórnék, komolyan.'::text),
(337863,37541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wahlplakate ... gestern mit einem breiten Pinsel an die Wand geklebt.'::text,'wurden'::text,'werden'::text,'klebten'::text,'Die Wahlplakate wurden gestern mit einem breiten Pinsel an die Wand geklebt.'::text),
(337867,37541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Передвиборчі плакати ... вчора на стіну широким пензлем.'::text,'були наклеєні'::text,'наклеюються'::text,'наклеїли'::text,'Передвиборчі плакати були наклеєні вчора на стіну широким пензлем.'::text),
(337866,37541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los carteles de campaña ... en la pared con una brocha ancha ayer.'::text,'fueron pegados'::text,'son pegados'::text,'pegaron'::text,'Los carteles de campaña fueron pegados en la pared con una brocha ancha ayer.'::text),
(337865,37541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les affiches de campagne ... au mur avec un large pinceau hier.'::text,'ont été collées'::text,'sont collées'::text,'ont collé'::text,'Les affiches de campagne ont été collées au mur avec un large pinceau hier.'::text),
(337868,37541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seçim afişleri dün geniş bir fırçayla duvara ...'::text,'yapıştırıldı'::text,'yapıştırılıyor'::text,'yapıştırdı'::text,'Seçim afişleri dün geniş bir fırçayla duvara yapıştırıldı.'::text),
(337869,37541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A választási plakátokat tegnap széles ecsettel ... a falra.'::text,'ragasztották fel'::text,'ragasztják fel'::text,'felragasztott'::text,'A választási plakátokat tegnap széles ecsettel ragasztották fel a falra.'::text),
(337872,37542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kandidat, ... Wahlplakate die Wand bedecken, stritt an jenem Abend auf der Bühne.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Kandidat, dessen Wahlplakate die Wand bedecken, stritt an jenem Abend auf der Bühne.'::text),
(337876,37542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кандидат, ... передвиборчі плакати вкривають стіну, сперечався того вечора на сцені.'::text,'чиї'::text,'який'::text,'котрий'::text,'Кандидат, чиї передвиборчі плакати вкривають стіну, сперечався того вечора на сцені.'::text),
(337875,37542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El candidato, ... carteles de campaña cubren la pared, discutió en el escenario esa noche.'::text,'cuyos'::text,'que'::text,'el cual'::text,'El candidato, cuyos carteles de campaña cubren la pared, discutió en el escenario esa noche.'::text),
(337874,37542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le candidat, ... les affiches de campagne couvrent le mur, a débattu sur scène ce soir-là.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le candidat, dont les affiches de campagne couvrent le mur, a débattu sur scène ce soir-là.'::text),
(337877,37542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seçim afişleri duvarı kaplayan ... aday, o gece sahnede tartıştı.'::text,''::text,NULL::text,NULL::text,'Seçim afişleri duvarı kaplayan aday, o gece sahnede tartıştı.'::text),
(337878,37542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelölt, ... választási plakátjai beborítják a falat, aznap este vitázott a színpadon.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A jelölt, akinek a választási plakátjai beborítják a falat, aznap este vitázott a színpadon.'::text),
(337881,37543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wahlkampfteam fuhr ... zur nächtlichen Kundgebung und verteilte Schilder.'::text,'mit dem Bus'::text,'mit dem Bus'::text,'mit einem Bus'::text,'Das Wahlkampfteam fuhr mit dem Bus zur nächtlichen Kundgebung und verteilte Schilder.'::text),
(337885,37543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда кампанії поїхала на нічний мітинг ... і роздавала плакати.'::text,'автобусом'::text,'автобусом'::text,'автобусом'::text,'Команда кампанії поїхала на нічний мітинг автобусом і роздавала плакати.'::text),
(337884,37543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo de campaña fue al mitin nocturno ... y repartió pancartas.'::text,'en autobús'::text,'en el autobús'::text,'en un autobús'::text,'El equipo de campaña fue al mitin nocturno en autobús y repartió pancartas.'::text),
(337883,37543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe de campagne est allée au meeting nocturne ... et a distribué des pancartes.'::text,'en bus'::text,'avec le bus'::text,'avec un bus'::text,'L''équipe de campagne est allée au meeting nocturne en bus et a distribué des pancartes.'::text),
(337886,37543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kampanya ekibi gece mitingine ... gitti ve pankart dağıttı.'::text,'otobüsle'::text,'otobüsle'::text,'bir otobüsle'::text,'Kampanya ekibi gece mitingine otobüsle gitti ve pankart dağıttı.'::text),
(337887,37543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kampánycsapat ... ment az esti gyűlésre, és táblákat osztogatott.'::text,'busszal'::text,'a busszal'::text,'egy busszal'::text,'A kampánycsapat busszal ment az esti gyűlésre, és táblákat osztogatott.'::text),
(337890,37544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der hitzigen Debatte endete der Wahlkampf mit Konfetti und Jubel.'::text,'Trotz'::text,'Obwohl'::text,'Im Falle'::text,'Trotz der hitzigen Debatte endete der Wahlkampf mit Konfetti und Jubel.'::text),
(337894,37544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... гарячі дебати, кампанія завершилася конфетті й оплесками.'::text,'Попри'::text,'Хоча'::text,'У разі'::text,'Попри гарячі дебати, кампанія завершилася конфетті й оплесками.'::text),
(337893,37544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el acalorado debate, la campaña terminó con confeti y vítores.'::text,'A pesar de'::text,'Aunque'::text,'En caso de'::text,'A pesar de el acalorado debate, la campaña terminó con confeti y vítores.'::text),
(337892,37544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le débat houleux, la campagne s''est terminée avec des confettis et des acclamations.'::text,'Malgré'::text,'Bien que'::text,'En cas de'::text,'Malgré le débat houleux, la campagne s''est terminée avec des confettis et des acclamations.'::text),
(337895,37544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hararetli tartışmaya ..., kampanya konfeti ve tezahüratla bitti.'::text,'rağmen'::text,'gerçi'::text,'durumunda'::text,'Hararetli tartışmaya rağmen, kampanya konfeti ve tezahüratla bitti.'::text),
(337896,37544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A heves vita ... a kampány konfettivel és ujjongással ért véget.'::text,'ellenére'::text,'habár'::text,'esetén'::text,'A heves vita ellenére a kampány konfettivel és ujjongással ért véget.'::text),
(374790,41644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, anscheinend ... sie nächste Woche um diese Zeit wieder Plastik aus dem Fluss ziehen.'::text,'wird'::text,'wird'::text,'zieht'::text,'Rate mal, anscheinend wird sie nächste Woche um diese Zeit wieder Plastik aus dem Fluss ziehen.'::text),
(374794,41644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви собі, кажуть, наступного тижня в цей час вона знову ... пластик із тієї річки.'::text,'витягатиме'::text,'витягне'::text,'витягає'::text,'Уяви собі, кажуть, наступного тижня в цей час вона знову витягатиме пластик із тієї річки.'::text),
(374793,41644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, al parecer la semana que viene a esta hora ella ... plástico de ese río otra vez.'::text,'estará sacando'::text,'sacará'::text,'saca'::text,'Adivina qué, al parecer la semana que viene a esta hora ella estará sacando plástico de ese río otra vez.'::text),
(374792,41644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment la semaine prochaine à cette heure-ci, elle ... encore du plastique de cette rivière.'::text,'sera en train de retirer'::text,'retirera'::text,'retire'::text,'Devine quoi, apparemment la semaine prochaine à cette heure-ci, elle sera en train de retirer encore du plastique de cette rivière.'::text),
(374795,41644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, galiba gelecek hafta bu saatlerde yine o nehirden plastik ...'::text,'çıkarıyor olacak'::text,'çıkaracak'::text,'çıkarıyor'::text,'Tahmin et ne oldu, galiba gelecek hafta bu saatlerde yine o nehirden plastik çıkarıyor olacak.'::text),
(374796,41644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag jövő héten ilyenkor megint ... a műanyagot abból a folyóból.'::text,'épp szedi ki'::text,'ki fogja szedni'::text,'kiszedi'::text,'Képzeld, állítólag jövő héten ilyenkor megint épp szedi ki a műanyagot abból a folyóból.'::text),
(374799,41645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir gesagt: Ich ... jede Plastikflasche aus diesem Fluss holen, versprochen.'::text,'werde'::text,'werde'::text,'hole'::text,'Hör zu, sie hat mir gesagt: Ich werde jede Plastikflasche aus diesem Fluss holen, versprochen.'::text),
(374803,41645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона мені сказала: Я ... кожну пластикову пляшку з цієї річки, обіцяю.'::text,'витягну'::text,'витягатиму'::text,'витягаю'::text,'Слухай, вона мені сказала: Я витягну кожну пластикову пляшку з цієї річки, обіцяю.'::text),
(374802,41645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo: Yo ... cada botella de plástico de este río, lo prometo.'::text,'sacaré'::text,'estaré sacando'::text,'saco'::text,'Escucha, me dijo: Yo sacaré cada botella de plástico de este río, lo prometo.'::text),
(374801,41645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit : Je ... chaque bouteille en plastique de cette rivière, promis.'::text,'retirerai'::text,'serai en train de retirer'::text,'retire'::text,'Écoute, elle m''a dit : Je retirerai chaque bouteille en plastique de cette rivière, promis.'::text),
(374804,41645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki: Bu nehirden her plastik şişeyi ..., söz veriyorum.'::text,'çıkaracağım'::text,'çıkarıyor olacağım'::text,'çıkarırım'::text,'Dinle, bana dedi ki: Bu nehirden her plastik şişeyi çıkaracağım, söz veriyorum.'::text),
(374805,41645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta nekem: Minden műanyag palackot ... ebből a folyóból, ígérem.'::text,'ki fogok szedni'::text,'szedni fogok'::text,'kiszedek'::text,'Figyelj, azt mondta nekem: Minden műanyag palackot ki fogok szedni ebből a folyóból, ígérem.'::text),
(374817,41647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, dieser Fluss ... vor dem ganzen Plastik sauber, echt.'::text,'war früher'::text,'war früher'::text,'war es gewohnt'::text,'Alter, dieser Fluss war früher vor dem ganzen Plastik sauber, echt.'::text),
(374821,41647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ця річка ... чистою до всього цього пластику, реально.'::text,'колись була'::text,'бувала'::text,'звикла бути'::text,'Чувак, ця річка колись була чистою до всього цього пластику, реально.'::text),
(374820,41647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, este río ... limpio antes de todo ese plástico, en serio.'::text,'solía estar'::text,'solía estar'::text,'estaba acostumbrado a estar'::text,'Tío, este río solía estar limpio antes de todo ese plástico, en serio.'::text),
(374819,41647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, cette rivière ... propre avant tout ce plastique, sérieux.'::text,'était'::text,'était'::text,'était habituée à être'::text,'Mec, cette rivière était propre avant tout ce plastique, sérieux.'::text),
(374822,41647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu nehir bütün o plastikten önce ... temizdi, cidden.'::text,'eskiden'::text,'eskiden'::text,'alışkındı'::text,'Kanka, bu nehir bütün o plastikten önce eskiden temizdi, cidden.'::text),
(374823,41647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a folyó ... tiszta volt az összes műanyag előtt, komolyan.'::text,'régen'::text,'régen'::text,'hozzászokott, hogy'::text,'Tesó, ez a folyó régen tiszta volt az összes műanyag előtt, komolyan.'::text),
(374826,41648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stakeholder erwarten von ihr, 500 Plastikflaschen aus dem Fluss ...'::text,'herauszuholen'::text,'herausholen'::text,'herausholen'::text,'Die Stakeholder erwarten von ihr, 500 Plastikflaschen aus dem Fluss herauszuholen.'::text),
(374830,41648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стейкхолдери очікують, що вона ... 500 пластикових пляшок із річки.'::text,'витягне'::text,'витягне'::text,'витягне'::text,'Стейкхолдери очікують, що вона витягне 500 пластикових пляшок із річки.'::text),
(374829,41648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los stakeholders esperan que ella ... 500 botellas de plástico del río.'::text,'saque'::text,'saque'::text,'saque'::text,'Los stakeholders esperan que ella saque 500 botellas de plástico del río.'::text),
(374828,41648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les stakeholders attendent qu''elle ... 500 bouteilles en plastique de la rivière.'::text,'retire'::text,'retire'::text,'retire'::text,'Les stakeholders attendent qu''elle retire 500 bouteilles en plastique de la rivière.'::text),
(374831,41648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paydaşlar onun nehirden 500 plastik şişe ... bekliyor.'::text,'çıkarmasını'::text,'çıkarmasını'::text,'çıkarmasını'::text,'Paydaşlar onun nehirden 500 plastik şişe çıkarmasını bekliyor.'::text),
(374832,41648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A stakeholderek elvárják tőle, hogy ... 500 műanyag palackot a folyóból.'::text,'kiszedjen'::text,'kiszedjen'::text,'kiszedjen'::text,'A stakeholderek elvárják tőle, hogy kiszedjen 500 műanyag palackot a folyóból.'::text),
(374835,41649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Plastikflasche kam aus der Fabrik, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Die Plastikflasche kam aus der Fabrik, oder?'::text),
(374839,41649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та пластикова пляшка припливла із заводу, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Та пластикова пляшка припливла із заводу, так?'::text),
(374838,41649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esa botella de plástico vino de la fábrica, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Esa botella de plástico vino de la fábrica, ¿verdad?'::text),
(374837,41649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette bouteille en plastique venait de l''usine, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Cette bouteille en plastique venait de l''usine, n''est-ce pas ?'::text),
(374840,41649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O plastik şişe fabrikadan geldi, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O plastik şişe fabrikadan geldi, değil mi?'::text),
(374841,41649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a műanyag palack a gyárból jött, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az a műanyag palack a gyárból jött, ugye?'::text),
(374844,41650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flasche ist aus Plastik, und die Becher, die an ihr vorbeitreiben, ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Die Flasche ist aus Plastik, und die Becher, die an ihr vorbeitreiben, auch.'::text),
(374848,41650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пляшка зроблена з пластику, і стаканчики, що пропливають повз неї, ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Пляшка зроблена з пластику, і стаканчики, що пропливають повз неї, теж.'::text),
(374847,41650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La botella es de plástico, y los vasos que flotan a su lado ...'::text,'también'::text,'también'::text,'tampoco'::text,'La botella es de plástico, y los vasos que flotan a su lado también.'::text),
(374846,41650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bouteille est en plastique, et les gobelets qui flottent près d''elle ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'La bouteille est en plastique, et les gobelets qui flottent près d''elle aussi.'::text),
(374849,41650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişe plastikten yapılmış, yanından süzülen bardaklar ...'::text,'da öyle'::text,'da öyle'::text,'da öyle değil'::text,'Şişe plastikten yapılmış, yanından süzülen bardaklar da öyle.'::text),
(374850,41650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A palack műanyagból van, és a mellette úszó poharak ...'::text,'is'::text,'is'::text,'sem'::text,'A palack műanyagból van, és a mellette úszó poharak is.'::text),
(374862,41652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Arbeit, Fabrik: Wenn du kein Plastik abgeladen hättest, ... sie nicht ins Wasser waten müssen.'::text,'hätte'::text,'wird'::text,'musste'::text,'Tolle Arbeit, Fabrik: Wenn du kein Plastik abgeladen hättest, hätte sie nicht ins Wasser waten müssen.'::text),
(374866,41652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, заводе: якби ти не скидав пластик, їй ... лізти у воду.'::text,'не довелося б'::text,'не доведеться'::text,'не довелося'::text,'Чудова робота, заводе: якби ти не скидав пластик, їй не довелося б лізти у воду.'::text),
(374865,41652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, fábrica: si no hubieras tirado plástico, ella ... meterse en el agua.'::text,'no habría necesitado'::text,'no necesitará'::text,'no necesitó'::text,'Buen trabajo, fábrica: si no hubieras tirado plástico, ella no habría necesitado meterse en el agua.'::text),
(374864,41652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, l''usine : si tu n''avais pas déversé de plastique, elle ... d''entrer dans l''eau.'::text,'n''aurait pas eu besoin'::text,'n''aura pas besoin'::text,'n''a pas eu besoin'::text,'Bravo, l''usine : si tu n''avais pas déversé de plastique, elle n''aurait pas eu besoin d''entrer dans l''eau.'::text),
(374867,41652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aferin fabrika: plastik dökmeseydin, kadının suya girmesine ...'::text,'gerek kalmazdı'::text,'gerek kalmayacak'::text,'gerek kalmadı'::text,'Aferin fabrika: plastik dökmeseydin, kadının suya girmesine gerek kalmazdı.'::text),
(374868,41652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, gyár: ha nem öntöttél volna bele műanyagot, neki ... begázolnia.'::text,'nem kellett volna'::text,'nem kell majd'::text,'nem kellett'::text,'Szép munka, gyár: ha nem öntöttél volna bele műanyagot, neki nem kellett volna begázolnia.'::text),
(374871,41653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fabrik bestritt, auch nur ein einziges Stück Plastik in den Fluss ...! Lügen! Katastrophe!'::text,'geworfen zu haben'::text,'zu werfen'::text,'warf'::text,'Die Fabrik bestritt, auch nur ein einziges Stück Plastik in den Fluss geworfen zu haben! Lügen! Katastrophe!'::text),
(374875,41653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завод заперечив, що ... в річку хоч шматочок пластику! Брехня! Катастрофа!'::text,'кидав'::text,'кинути'::text,'кинув'::text,'Завод заперечив, що кидав в річку хоч шматочок пластику! Брехня! Катастрофа!'::text),
(374874,41653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La fábrica negó ... ni un solo trozo de plástico al río! ¡Mentiras! ¡Desastre!'::text,'haber tirado'::text,'tirar'::text,'tiró'::text,'¡La fábrica negó haber tirado ni un solo trozo de plástico al río! ¡Mentiras! ¡Desastre!'::text),
(374873,41653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''usine a nié ... le moindre morceau de plastique dans la rivière ! Mensonges ! Catastrophe !'::text,'avoir jeté'::text,'jeter'::text,'a jeté'::text,'L''usine a nié avoir jeté le moindre morceau de plastique dans la rivière ! Mensonges ! Catastrophe !'::text),
(374876,41653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fabrika nehre tek bir plastik parçası bile ... inkâr etti! Yalan! Felaket!'::text,'attığını'::text,'atmayı'::text,'attı'::text,'Fabrika nehre tek bir plastik parçası bile attığını inkâr etti! Yalan! Felaket!'::text),
(374877,41653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyár tagadta, hogy ... akár egyetlen darab műanyagot is a folyóba! Hazugság! Katasztrófa!'::text,'beledobott'::text,'bedobni'::text,'bedobta'::text,'A gyár tagadta, hogy beledobott akár egyetlen darab műanyagot is a folyóba! Hazugság! Katasztrófa!'::text),
(374880,41654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plastik ... diesen Fluss seit Jahren, und jetzt ist er völlig zerstört!'::text,'verschmutzt'::text,'verschmutzt'::text,'verschmutzt'::text,'Plastik verschmutzt diesen Fluss seit Jahren, und jetzt ist er völlig zerstört!'::text),
(374884,41654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пластик ... цю річку роками, і тепер вона повністю знищена!'::text,'забруднює'::text,'забруднює'::text,'забруднює'::text,'Пластик забруднює цю річку роками, і тепер вона повністю знищена!'::text),
(374883,41654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El plástico ... este río durante años, y ahora está completamente destruido!'::text,'ha estado contaminando'::text,'está contaminando'::text,'contamina'::text,'¡El plástico ha estado contaminando este río durante años, y ahora está completamente destruido!'::text),
(374882,41654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le plastique ... cette rivière depuis des années, et maintenant elle est complètement détruite !'::text,'pollue'::text,'pollue'::text,'pollue'::text,'Le plastique pollue cette rivière depuis des années, et maintenant elle est complètement détruite !'::text),
(374885,41654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plastik yıllardır bu nehri ..., ve şimdi tamamen yok oldu!'::text,'kirletiyor'::text,'kirletiyor'::text,'kirletir'::text,'Plastik yıllardır bu nehri kirletiyor, ve şimdi tamamen yok oldu!'::text),
(374886,41654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A műanyag évek óta ... ezt a folyót, és most teljesen tönkrement!'::text,'szennyezi'::text,'szennyezi'::text,'szennyezi'::text,'A műanyag évek óta szennyezi ezt a folyót, és most teljesen tönkrement!'::text),
(396786,44088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese blauen Kacheln bedecken die ganze Wand, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Diese blauen Kacheln bedecken die ganze Wand, oder?'::text),
(396790,44088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця синя плитка вкриває всю стіну, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Ця синя плитка вкриває всю стіну, так?'::text),
(396789,44088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estos azulejos azules cubren toda la pared, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Estos azulejos azules cubren toda la pared, ¿verdad?'::text),
(396788,44088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces carreaux bleus couvrent tout le mur, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Ces carreaux bleus couvrent tout le mur, n''est-ce pas ?'::text),
(396791,44088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu mavi çiniler bütün duvarı kaplıyor, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Bu mavi çiniler bütün duvarı kaplıyor, değil mi?'::text),
(396792,44088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek a kék csempék az egész falat borítják, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Ezek a kék csempék az egész falat borítják, ugye?'::text),
(396804,44090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Spaziergangs ... das Subjekt die bemalten Kacheln berührt haben, wie es Touristen typischerweise tun.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis zum Ende des Spaziergangs wird das Subjekt die bemalten Kacheln berührt haben, wie es Touristen typischerweise tun.'::text),
(396808,44090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця прогулянки суб''єкт ... розписаної плитки, як зазвичай роблять туристи.'::text,'вже торкнеться'::text,'торкнеться'::text,'торкатиметься'::text,'До кінця прогулянки суб''єкт вже торкнеться розписаної плитки, як зазвичай роблять туристи.'::text),
(396807,44090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del paseo, el sujeto ... los azulejos pintados, como suelen hacer los turistas.'::text,'habrá tocado'::text,'tocará'::text,'estará tocando'::text,'Al final del paseo, el sujeto habrá tocado los azulejos pintados, como suelen hacer los turistas.'::text),
(396806,44090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la promenade, le sujet ... les carreaux peints, comme le font typiquement les touristes.'::text,'aura touché'::text,'touchera'::text,'sera en train de toucher'::text,'D''ici la fin de la promenade, le sujet aura touché les carreaux peints, comme le font typiquement les touristes.'::text),
(396809,44090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşün sonunda denek, turistlerin tipik olarak yaptığı gibi, boyalı çinilere ...'::text,'dokunmuş olacak'::text,'dokunacak'::text,'dokunuyor olacak'::text,'Yürüyüşün sonunda denek, turistlerin tipik olarak yaptığı gibi, boyalı çinilere dokunmuş olacak.'::text),
(396810,44090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A séta végére az alany ... a festett csempéket, ahogy a turisták jellemzően teszik.'::text,'már meg fogja érinteni'::text,'meg fogja érinteni'::text,'érinteni fogja'::text,'A séta végére az alany már meg fogja érinteni a festett csempéket, ahogy a turisták jellemzően teszik.'::text),
(396813,44091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er nicht an den Kacheln vorbeigegangen wäre, ... er sein Lieblingsfoto der Reise nicht gemacht.'::text,'hätte'::text,'wird'::text,'machte'::text,'Wenn er nicht an den Kacheln vorbeigegangen wäre, hätte er sein Lieblingsfoto der Reise nicht gemacht.'::text),
(396817,44091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не пройшов повз плитку, він ... свого улюбленого фото з поїздки.'::text,'не зробив би'::text,'не зробить'::text,'не зробив'::text,'Якби він не пройшов повз плитку, він не зробив би свого улюбленого фото з поїздки.'::text),
(396816,44091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera pasado junto a los azulejos, ... su foto favorita del viaje.'::text,'no habría hecho'::text,'no hará'::text,'no hizo'::text,'Si no hubiera pasado junto a los azulejos, no habría hecho su foto favorita del viaje.'::text),
(396815,44091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''était pas passé devant les carreaux, il ... sa photo préférée du voyage.'::text,'n''aurait pas pris'::text,'ne prendra pas'::text,'n''a pas pris'::text,'S''il n''était pas passé devant les carreaux, il n''aurait pas pris sa photo préférée du voyage.'::text),
(396818,44091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çinilerin önünden geçmeseydi, gezinin en sevdiği fotoğrafını ...'::text,'çekmezdi'::text,'çekmeyecek'::text,'çekmedi'::text,'Çinilerin önünden geçmeseydi, gezinin en sevdiği fotoğrafını çekmezdi.'::text),
(396819,44091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem ment volna el a csempék mellett, ... az utazás kedvenc fotóját.'::text,'nem készítette volna el'::text,'nem készíti el'::text,'nem készítette el'::text,'Ha nem ment volna el a csempék mellett, nem készítette volna el az utazás kedvenc fotóját.'::text),
(396822,44092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Später gab er zu, die alten Kacheln mit bloßer Hand ...'::text,'berührt zu haben'::text,'zu berühren'::text,'berührte'::text,'Später gab er zu, die alten Kacheln mit bloßer Hand berührt zu haben.'::text),
(396826,44092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пізніше він визнав, що ... старої плитки голою рукою.'::text,'торкався'::text,'торкатися'::text,'торкнувся'::text,'Пізніше він визнав, що торкався старої плитки голою рукою.'::text),
(396825,44092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Más tarde admitió ... los viejos azulejos con la mano desnuda.'::text,'haber tocado'::text,'tocar'::text,'tocó'::text,'Más tarde admitió haber tocado los viejos azulejos con la mano desnuda.'::text),
(396824,44092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus tard, il a admis ... les vieux carreaux à main nue.'::text,'avoir touché'::text,'toucher'::text,'a touché'::text,'Plus tard, il a admis avoir touché les vieux carreaux à main nue.'::text),
(396827,44092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonra eski çinilere çıplak eliyle ... itiraf etti.'::text,'dokunduğunu'::text,'dokunmayı'::text,'dokundu'::text,'Sonra eski çinilere çıplak eliyle dokunduğunu itiraf etti.'::text),
(396828,44092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Később bevallotta, hogy ... a régi csempéket a puszta kezével.'::text,'megérintette'::text,'megérinteni'::text,'megérintette'::text,'Később bevallotta, hogy megérintette a régi csempéket a puszta kezével.'::text),
(396831,44093,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kacheln fühlten sich kühl an, also ... die Wand den ganzen Nachmittag im Schatten gewesen sein.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Die Kacheln fühlten sich kühl an, also muss die Wand den ganzen Nachmittag im Schatten gewesen sein.'::text),
(396835,44093,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Плитка була прохолодною на дотик, тож стіна ... в тіні весь день.'::text,'напевно, була'::text,'мала бути'::text,'не могла бути'::text,'Плитка була прохолодною на дотик, тож стіна напевно, була в тіні весь день.'::text),
(396834,44093,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los azulejos estaban frescos, así que la pared ... a la sombra toda la tarde.'::text,'debió de estar'::text,'debería haber estado'::text,'no pudo haber estado'::text,'Los azulejos estaban frescos, así que la pared debió de estar a la sombra toda la tarde.'::text),
(396833,44093,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les carreaux étaient frais, donc le mur ... à l''ombre tout l''après-midi.'::text,'a dû être'::text,'aurait dû être'::text,'n''a pas pu être'::text,'Les carreaux étaient frais, donc le mur a dû être à l''ombre tout l''après-midi.'::text),
(396836,44093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiniler serindi, yani duvar bütün öğleden sonra gölgede ...'::text,'kalmış olmalı'::text,'kalmalıydı'::text,'kalmış olamaz'::text,'Çiniler serindi, yani duvar bütün öğleden sonra gölgede kalmış olmalı.'::text),
(396837,44093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csempék hűvösek voltak, tehát a fal egész délután árnyékban ...'::text,'lehetett'::text,'kellett volna lennie'::text,'nem lehetett'::text,'A csempék hűvösek voltak, tehát a fal egész délután árnyékban lehetett.'::text),
(396840,44094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer ließ einen Künstler jede Kachel von Hand ..., ein Albtraumjob!'::text,'bemalen'::text,'bemalen'::text,'bemalen'::text,'Der Besitzer ließ einen Künstler jede Kachel von Hand bemalen, ein Albtraumjob!'::text),
(396844,44094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник доручив митцю ... кожну плитку вручну, робота-жах!'::text,'розписати'::text,'розписати'::text,'розпис'::text,'Власник доручив митцю розписати кожну плитку вручну, робота-жах!'::text),
(396843,44094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El dueño consiguió que un artista ... cada azulejo a mano, un trabajo de pesadilla!'::text,'pintara'::text,'pintara'::text,'pintando'::text,'¡El dueño consiguió que un artista pintara cada azulejo a mano, un trabajo de pesadilla!'::text),
(396842,44094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire a fait ... chaque carreau à la main par un artiste, un boulot cauchemardesque !'::text,'peindre'::text,'peindre'::text,'peindre'::text,'Le propriétaire a fait peindre chaque carreau à la main par un artiste, un boulot cauchemardesque !'::text),
(396845,44094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi her çiniyi bir sanatçıya elle ..., kâbus gibi bir iş!'::text,'boyattı'::text,'boyattı'::text,'boyama'::text,'Sahibi her çiniyi bir sanatçıya elle boyattı, kâbus gibi bir iş!'::text),
(396846,44094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tulajdonos egy művésszel ... meg minden csempét kézzel, rémálom meló!'::text,'festette'::text,'festette'::text,'festés'::text,'A tulajdonos egy művésszel festette meg minden csempét kézzel, rémálom meló!'::text),
(396849,44095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, er hat mir erzählt, er wünschte, seine Wohnung ... blaue Kacheln wie diese Wand.'::text,'hätte'::text,'hat'::text,'würde haben'::text,'Süße, er hat mir erzählt, er wünschte, seine Wohnung hätte blaue Kacheln wie diese Wand.'::text),
(396853,44095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він мені сказав, що хотів би, щоб його квартира ... синю плитку, як та стіна.'::text,'мала'::text,'має'::text,'мала б'::text,'Подруго, він мені сказав, що хотів би, щоб його квартира мала синю плитку, як та стіна.'::text),
(396852,44095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que desearía que su piso ... azulejos azules como esa pared.'::text,'tuviera'::text,'tiene'::text,'tendría'::text,'Amiga, me dijo que desearía que su piso tuviera azulejos azules como esa pared.'::text),
(396851,44095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il aimerait que son appart ... des carreaux bleus comme ce mur.'::text,'ait'::text,'a'::text,'aurait'::text,'Meuf, il m''a dit qu''il aimerait que son appart ait des carreaux bleus comme ce mur.'::text),
(396854,44095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dedi ki keşke evinde de o duvar gibi mavi çiniler ...'::text,'olsa'::text,'var'::text,'olurdu'::text,'Kızım, bana dedi ki keşke evinde de o duvar gibi mavi çiniler olsa.'::text),
(396855,44095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak a lakásában ... olyan kék csempék, mint azon a falon.'::text,'lennének'::text,'vannak'::text,'lennének majd'::text,'Csajszi, azt mondta, bárcsak a lakásában lennének olyan kék csempék, mint azon a falon.'::text),
(396858,44096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, das Haus, ... Kacheln er berührt hat, ist angeblich dreihundert Jahre alt.'::text,'dessen'::text,'welches'::text,'das'::text,'Hör zu, das Haus, dessen Kacheln er berührt hat, ist angeblich dreihundert Jahre alt.'::text),
(396862,44096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, будинок, ... плитки він торкався, має триста років.'::text,'чиєї'::text,'який'::text,'що'::text,'Слухай, кажуть, будинок, чиєї плитки він торкався, має триста років.'::text),
(396861,44096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer la casa ... azulejos tocó tiene trescientos años.'::text,'cuyos'::text,'que'::text,'la cual'::text,'Escucha, al parecer la casa cuyos azulejos tocó tiene trescientos años.'::text),
(396860,44096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la maison ... il a touché les carreaux a trois cents ans.'::text,'dont'::text,'qui'::text,'que'::text,'Écoute, apparemment la maison dont il a touché les carreaux a trois cents ans.'::text),
(396863,44096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, galiba çinilerine dokunduğu ... ev üç yüz yaşında.'::text,''::text,NULL::text,NULL::text,'Dinle, galiba çinilerine dokunduğu ev üç yüz yaşında.'::text),
(396864,44096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a ház, ... csempéit megérintette, háromszáz éves.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'Figyelj, állítólag a ház, amelynek a csempéit megérintette, háromszáz éves.'::text),
(396876,44098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der bemalten Kacheln sieht die ganze Straße aus wie eine Galerie.'::text,'Dank'::text,'Trotz'::text,'Obwohl'::text,'Dank der bemalten Kacheln sieht die ganze Straße aus wie eine Galerie.'::text),
(396880,44098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... розписаній плитці вся вулиця схожа на галерею.'::text,'Завдяки'::text,'Попри'::text,'Хоча'::text,'Завдяки розписаній плитці вся вулиця схожа на галерею.'::text),
(396879,44098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los azulejos pintados, toda la calle parece una galería.'::text,'Gracias a'::text,'A pesar de'::text,'Aunque'::text,'Gracias a los azulejos pintados, toda la calle parece una galería.'::text),
(396878,44098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... aux carreaux peints, toute la rue ressemble à une galerie.'::text,'Grâce'::text,'Malgré'::text,'Bien que'::text,'Grâce aux carreaux peints, toute la rue ressemble à une galerie.'::text),
(396881,44098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boyalı çiniler ..., bütün sokak bir galeriye benziyor.'::text,'sayesinde'::text,'rağmen'::text,'gerçi'::text,'Boyalı çiniler sayesinde, bütün sokak bir galeriye benziyor.'::text),
(396882,44098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A festett csempéknek ... az egész utca úgy néz ki, mint egy galéria.'::text,'köszönhetően'::text,'ellenére'::text,'habár'::text,'A festett csempéknek köszönhetően az egész utca úgy néz ki, mint egy galéria.'::text),
(367194,40800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... die Postkarte im Café, als du beschlossen hast, sie sofort abzuschicken. Smooth.'::text,'schriebst gerade'::text,'schriebst'::text,'hast geschrieben'::text,'Du schriebst gerade die Postkarte im Café, als du beschlossen hast, sie sofort abzuschicken. Smooth.'::text),
(367198,40800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... листівку в кафе, коли вирішив одразу надіслати її поштою. Елегантно.'::text,'писав'::text,'написав'::text,'написав'::text,'Ти писав листівку в кафе, коли вирішив одразу надіслати її поштою. Елегантно.'::text),
(367197,40800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la postal en el café cuando decidiste enviarla por correo enseguida. Qué fino.'::text,'Estabas escribiendo'::text,'Escribiste'::text,'Has escrito'::text,'Estabas escribiendo la postal en el café cuando decidiste enviarla por correo enseguida. Qué fino.'::text),
(367196,40800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la carte postale au café quand tu as décidé de la poster tout de suite. Classe.'::text,'écrivais'::text,'as écrit'::text,'as écrit'::text,'Tu écrivais la carte postale au café quand tu as décidé de la poster tout de suite. Classe.'::text),
(367199,40800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemen postalamaya karar verdiğinde kafede kartpostalı ..., şık hareket.'::text,'yazıyordun'::text,'yazdın'::text,'yazdın'::text,'Hemen postalamaya karar verdiğinde kafede kartpostalı yazıyordun, şık hareket.'::text),
(367200,40800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te épp ... a képeslapot a kávézóban, amikor úgy döntöttél, hogy rögtön feladod. Elegáns.'::text,'írtad'::text,'megírtad'::text,'megírtad'::text,'Te épp írtad a képeslapot a kávézóban, amikor úgy döntöttél, hogy rögtön feladod. Elegáns.'::text),
(367203,40801,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon den ganzen Vormittag Postkarten, und jetzt ist er bereit, eine abzuschicken.'::text,'schreibt'::text,'schreibt'::text,'schreibt'::text,'Er schreibt schon den ganzen Vormittag Postkarten, und jetzt ist er bereit, eine abzuschicken.'::text),
(367207,40801,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... листівки весь ранок, і тепер готовий надіслати одну.'::text,'пише'::text,'пише'::text,'пише'::text,'Він пише листівки весь ранок, і тепер готовий надіслати одну.'::text),
(367206,40801,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... postales toda la mañana y ahora está listo para enviar una.'::text,'Ha estado escribiendo'::text,'Está escribiendo'::text,'Escribe'::text,'Ha estado escribiendo postales toda la mañana y ahora está listo para enviar una.'::text),
(367205,40801,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des cartes postales toute la matinée, et maintenant il est prêt à en poster une.'::text,'écrit'::text,'écrit'::text,'écrit'::text,'Il écrit des cartes postales toute la matinée, et maintenant il est prêt à en poster une.'::text),
(367208,40801,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sabah kartpostal ..., ve şimdi birini postalamaya hazır.'::text,'yazıyor'::text,'yazıyor'::text,'yazar'::text,'Bütün sabah kartpostal yazıyor, ve şimdi birini postalamaya hazır.'::text),
(367209,40801,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délelőtt képeslapokat ..., és most kész feladni egyet.'::text,'ír'::text,'ír'::text,'ír'::text,'Egész délelőtt képeslapokat ír, és most kész feladni egyet.'::text),
(367212,40802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Postkarte in dem Moment, als er den gelben Briefkasten erreichte.'::text,'verschickte'::text,'verschickte gerade'::text,'hat verschickt'::text,'Er verschickte die Postkarte in dem Moment, als er den gelben Briefkasten erreichte.'::text),
(367216,40802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... листівку тієї миті, коли дійшов до жовтої поштової скриньки.'::text,'надіслав'::text,'надсилав'::text,'надіслав'::text,'Він надіслав листівку тієї миті, коли дійшов до жовтої поштової скриньки.'::text),
(367215,40802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la postal en el momento en que llegó al buzón amarillo.'::text,'Envió'::text,'Estaba enviando'::text,'Ha enviado'::text,'Envió la postal en el momento en que llegó al buzón amarillo.'::text),
(367214,40802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la carte postale au moment où il a atteint la boîte aux lettres jaune.'::text,'a posté'::text,'postait'::text,'a posté'::text,'Il a posté la carte postale au moment où il a atteint la boîte aux lettres jaune.'::text),
(367217,40802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı posta kutusuna vardığı anda kartpostalı ...'::text,'postaladı'::text,'postalıyordu'::text,'postaladı'::text,'Sarı posta kutusuna vardığı anda kartpostalı postaladı.'::text),
(367218,40802,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a pillanatban ... a képeslapot, amikor odaért a sárga postaládához.'::text,'feladta'::text,'épp adta fel'::text,'feladta'::text,'Abban a pillanatban feladta a képeslapot, amikor odaért a sárga postaládához.'::text),
(367221,40803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seiner Familie diese Woche bisher drei Postkarten geschickt.'::text,'hat'::text,'hat'::text,'schickt'::text,'Er hat seiner Familie diese Woche bisher drei Postkarten geschickt.'::text),
(367225,40803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього тижня він уже ... родині три листівки.'::text,'надіслав'::text,'надсилав'::text,'надсилає'::text,'Цього тижня він уже надіслав родині три листівки.'::text),
(367224,40803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta semana ya le ... tres postales a su familia.'::text,'ha enviado'::text,'ha estado enviando'::text,'envía'::text,'Esta semana ya le ha enviado tres postales a su familia.'::text),
(367223,40803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... trois cartes postales à sa famille jusqu''ici cette semaine.'::text,'a envoyé'::text,'a envoyé'::text,'envoie'::text,'Il a envoyé trois cartes postales à sa famille jusqu''ici cette semaine.'::text),
(367226,40803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu hafta şimdiye kadar ailesine üç kartpostal ...'::text,'postaladı'::text,'postalıyor'::text,'postalar'::text,'Bu hafta şimdiye kadar ailesine üç kartpostal postaladı.'::text),
(367227,40803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen a héten eddig három képeslapot ... a családjának.'::text,'küldött'::text,'küldözgetett'::text,'küld'::text,'Ezen a héten eddig három képeslapot küldött a családjának.'::text),
(367239,40805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... sie früher abschicken sollen, der Trip ist lowkey schon vorbei.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Bro, er hätte sie früher abschicken sollen, der Trip ist lowkey schon vorbei.'::text),
(367243,40805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... надіслати її раніше, поїздка вже, по ходу, закінчується.'::text,'мав'::text,'мусив'::text,'не міг'::text,'Бро, він мав надіслати її раніше, поїздка вже, по ходу, закінчується.'::text),
(367242,40805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... enviado antes, el viaje ya casi se acabó, la verdad.'::text,'debería haberla'::text,'debe de haberla'::text,'no puede haberla'::text,'Bro, él debería haberla enviado antes, el viaje ya casi se acabó, la verdad.'::text),
(367241,40805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... l''envoyer plus tôt, le voyage est carrément déjà fini.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Frère, il aurait dû l''envoyer plus tôt, le voyage est carrément déjà fini.'::text),
(367244,40805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onu daha önce ..., gezi resmen bitti bile.'::text,'postalamalıydı'::text,'postalamış olmalı'::text,'postalamış olamaz'::text,'Kanka, onu daha önce postalamalıydı, gezi resmen bitti bile.'::text),
(367245,40805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, korábban ... feladnia, az út lowkey már véget is ért.'::text,'kellett volna'::text,'biztosan kellett'::text,'nem kellett'::text,'Tesó, korábban kellett volna feladnia, az út lowkey már véget is ért.'::text),
(367257,40807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er ... die Postkarte vor der Leerung um 17 Uhr abgeschickt.'::text,'hätte'::text,'hätte'::text,'würde'::text,'Er wünschte, er hätte die Postkarte vor der Leerung um 17 Uhr abgeschickt.'::text),
(367261,40807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб ... листівку ще до виїмки о 17:00.'::text,'встиг надіслати'::text,'надіслав'::text,'надіслав би'::text,'Він хотів би, щоб встиг надіслати листівку ще до виїмки о 17:00.'::text),
(367260,40807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gustaría ... la postal antes de la recogida de las 17:00.'::text,'haber enviado'::text,'enviar'::text,'enviar'::text,'Le gustaría haber enviado la postal antes de la recogida de las 17:00.'::text),
(367259,40807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... la carte postale avant la levée de 17 h.'::text,'avoir posté'::text,'poster'::text,'poster'::text,'Il aimerait avoir posté la carte postale avant la levée de 17 h.'::text),
(367262,40807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke kartpostalı saat 17:00''deki toplama saatinden önce ... diye düşünüyor.'::text,'postalasaydım'::text,'postalasam'::text,'postalayacak olsam'::text,'Keşke kartpostalı saat 17:00''deki toplama saatinden önce postalasaydım diye düşünüyor.'::text),
(367263,40807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... a képeslapot a 17 órai ürítési határidő előtt.'::text,'feladta volna'::text,'feladta'::text,'feladná'::text,'Azt kívánja, bárcsak feladta volna a képeslapot a 17 órai ürítési határidő előtt.'::text),
(367266,40808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Postkarte, ... er aus dem gelben Kasten verschickt, hat ein Bild vom Meer.'::text,'die'::text,'die'::text,'wer'::text,'Die Postkarte, die er aus dem gelben Kasten verschickt, hat ein Bild vom Meer.'::text),
(367270,40808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Листівка, ... він надсилає з жовтої скриньки, має зображення моря.'::text,'яку'::text,'котру'::text,'хто'::text,'Листівка, яку він надсилає з жовтої скриньки, має зображення моря.'::text),
(367269,40808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La postal, ... envía desde el buzón amarillo, tiene una foto del mar.'::text,'que'::text,'que'::text,'quien'::text,'La postal, que envía desde el buzón amarillo, tiene una foto del mar.'::text),
(367268,40808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carte postale, ... poste depuis la boîte jaune, montre une image de la mer.'::text,'qu''il'::text,'qu''il'::text,'qui'::text,'La carte postale, qu''il poste depuis la boîte jaune, montre une image de la mer.'::text),
(367271,40808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı kutudan postaladığı ... kartpostalda denizin resmi var.'::text,''::text,NULL::text,NULL::text,'Sarı kutudan postaladığı kartpostalda denizin resmi var.'::text),
(367272,40808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A képeslap, ... a sárga ládából ad fel, a tengert ábrázolja.'::text,'amelyet'::text,'amit'::text,'aki'::text,'A képeslap, amelyet a sárga ládából ad fel, a tengert ábrázolja.'::text),
(367275,40809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Postkarte kann verschickt werden, ... sie eine Briefmarke trägt, wie es der Prozess verlangt.'::text,'vorausgesetzt, dass'::text,'im Falle'::text,'aufgrund'::text,'Die Postkarte kann verschickt werden, vorausgesetzt, dass sie eine Briefmarke trägt, wie es der Prozess verlangt.'::text),
(367279,40809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Листівку можна надіслати, ... на ній є марка, як вимагає процес.'::text,'за умови, що'::text,'у разі'::text,'через'::text,'Листівку можна надіслати, за умови, що на ній є марка, як вимагає процес.'::text),
(367278,40809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La postal puede enviarse ... lleve un sello, como exige el proceso.'::text,'siempre que'::text,'en caso de'::text,'debido a'::text,'La postal puede enviarse siempre que lleve un sello, como exige el proceso.'::text),
(367277,40809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carte postale peut être envoyée ... porte un timbre, comme l''exige le processus.'::text,'à condition qu''elle'::text,'en cas de'::text,'en raison de'::text,'La carte postale peut être envoyée à condition qu''elle porte un timbre, comme l''exige le processus.'::text),
(367280,40809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kartpostal, sürecin gerektirdiği gibi, üzerinde pul ... postalanabilir.'::text,'olması şartıyla'::text,'olması durumunda'::text,'olması nedeniyle'::text,'Kartpostal, sürecin gerektirdiği gibi, üzerinde pul olması şartıyla postalanabilir.'::text),
(367281,40809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A képeslap feladható, ... bélyeg van rajta, ahogy a folyamat megköveteli.'::text,'feltéve, hogy'::text,'abban az esetben'::text,'amiatt'::text,'A képeslap feladható, feltéve, hogy bélyeg van rajta, ahogy a folyamat megköveteli.'::text),
(367284,40810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag ... deine Familie die Postkarte, die du heute abgeschickt hast, bekommen haben, ganz ehrlich.'::text,'wird'::text,'wird'::text,'bekommt'::text,'Bis Freitag wird deine Familie die Postkarte, die du heute abgeschickt hast, bekommen haben, ganz ehrlich.'::text),
(367288,40810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці твоя родина ... листівку, яку ти сьогодні надіслав, чесно.'::text,'вже отримає'::text,'отримає'::text,'отримує'::text,'До п''ятниці твоя родина вже отримає листівку, яку ти сьогодні надіслав, чесно.'::text),
(367287,40810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes tu familia ... la postal que enviaste hoy, no voy a mentir.'::text,'habrá recibido'::text,'recibirá'::text,'recibe'::text,'Para el viernes tu familia habrá recibido la postal que enviaste hoy, no voy a mentir.'::text),
(367286,40810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, ta famille ... la carte que tu as postée aujourd''hui, sans mentir.'::text,'aura reçu'::text,'recevra'::text,'reçoit'::text,'D''ici vendredi, ta famille aura reçu la carte que tu as postée aujourd''hui, sans mentir.'::text),
(367289,40810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar ailen bugün postaladığın kartpostalı ..., yalan yok.'::text,'almış olacak'::text,'alacak'::text,'alıyor'::text,'Cumaya kadar ailen bugün postaladığın kartpostalı almış olacak, yalan yok.'::text),
(367290,40810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre a családod ... a képeslapot, amit ma adtál fel, nem hazudok.'::text,'már megkapja'::text,'meg fogja kapni'::text,'megkapja'::text,'Péntekre a családod már megkapja a képeslapot, amit ma adtál fel, nem hazudok.'::text),
(372000,41334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Paket noch größer wäre, ... der Postbote es nicht über die Gartenmauer reichen.'::text,'könnte'::text,'kann'::text,'hätte'::text,'Wenn das Paket noch größer wäre, könnte der Postbote es nicht über die Gartenmauer reichen.'::text),
(372004,41334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби посилка була ще більшою, листоноша ... її через садову стіну.'::text,'не зміг би передати'::text,'не може передати'::text,'не зміг би передати'::text,'Якби посилка була ще більшою, листоноша не зміг би передати її через садову стіну.'::text),
(372003,41334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el paquete fuera más grande, el cartero ... por encima del muro del jardín.'::text,'no podría pasarlo'::text,'no puede pasarlo'::text,'no habría podido pasarlo'::text,'Si el paquete fuera más grande, el cartero no podría pasarlo por encima del muro del jardín.'::text),
(372002,41334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le colis était encore plus gros, le facteur ... par-dessus le mur du jardin.'::text,'ne pourrait pas le passer'::text,'ne peut pas le passer'::text,'n''aurait pas pu le passer'::text,'Si le colis était encore plus gros, le facteur ne pourrait pas le passer par-dessus le mur du jardin.'::text),
(372005,41334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paket biraz daha büyük olsaydı, postacı onu bahçe duvarının üstünden ...'::text,'uzatamazdı'::text,'uzatamaz'::text,'uzatamazdı'::text,'Paket biraz daha büyük olsaydı, postacı onu bahçe duvarının üstünden uzatamazdı.'::text),
(372006,41334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a csomag még nagyobb lenne, a postás ... a kerti falon át.'::text,'nem tudná átadni'::text,'nem tudja átadni'::text,'nem tudta volna átadni'::text,'Ha a csomag még nagyobb lenne, a postás nem tudná átadni a kerti falon át.'::text),
(372009,41335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das eingepackte Geburtstagspaket ... heute Morgen über die Gartenmauer gereicht.'::text,'wurde'::text,'wird'::text,'reichte'::text,'Das eingepackte Geburtstagspaket wurde heute Morgen über die Gartenmauer gereicht.'::text),
(372013,41335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Запакована посилка на день народження ... сьогодні вранці через садову стіну.'::text,'була передана'::text,'передається'::text,'передала'::text,'Запакована посилка на день народження була передана сьогодні вранці через садову стіну.'::text),
(372012,41335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El paquete de cumpleaños envuelto ... por encima del muro del jardín esta mañana.'::text,'fue entregado'::text,'es entregado'::text,'entregó'::text,'El paquete de cumpleaños envuelto fue entregado por encima del muro del jardín esta mañana.'::text),
(372011,41335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le colis d''anniversaire emballé ... par-dessus le mur du jardin ce matin.'::text,'a été passé'::text,'est passé'::text,'a passé'::text,'Le colis d''anniversaire emballé a été passé par-dessus le mur du jardin ce matin.'::text),
(372014,41335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paketlenmiş doğum günü paketi bu sabah bahçe duvarının üstünden ...'::text,'uzatıldı'::text,'uzatılıyor'::text,'uzattı'::text,'Paketlenmiş doğum günü paketi bu sabah bahçe duvarının üstünden uzatıldı.'::text),
(372015,41335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A becsomagolt születésnapi csomagot ma reggel ... át a kerti falon.'::text,'adták'::text,'adják'::text,'adta'::text,'A becsomagolt születésnapi csomagot ma reggel adták át a kerti falon.'::text),
(372018,41336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor einer Stunde ... der Postbote das Geburtstagspaket einem Nachbarn über die Backsteinmauer.'::text,'reichte'::text,'wurde gereicht'::text,'reichend'::text,'Vor einer Stunde reichte der Postbote das Geburtstagspaket einem Nachbarn über die Backsteinmauer.'::text),
(372022,41336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Годину тому листоноша ... посилку на день народження сусідові через цегляну стіну.'::text,'передав'::text,'був переданий'::text,'передаючи'::text,'Годину тому листоноша передав посилку на день народження сусідові через цегляну стіну.'::text),
(372021,41336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace una hora, el cartero ... el paquete de cumpleaños a un vecino por encima del muro de ladrillo.'::text,'entregó'::text,'fue entregado'::text,'entregando'::text,'Hace una hora, el cartero entregó el paquete de cumpleaños a un vecino por encima del muro de ladrillo.'::text),
(372020,41336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a une heure, le facteur ... le colis d''anniversaire à un voisin par-dessus le mur de briques.'::text,'a passé'::text,'a été passé'::text,'passant'::text,'Il y a une heure, le facteur a passé le colis d''anniversaire à un voisin par-dessus le mur de briques.'::text),
(372023,41336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saat önce postacı doğum günü paketini tuğla duvarın üstünden bir komşuya ...'::text,'uzattı'::text,'uzatıldı'::text,'uzatarak'::text,'Bir saat önce postacı doğum günü paketini tuğla duvarın üstünden bir komşuya uzattı.'::text),
(372024,41336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órája a postás ... a születésnapi csomagot egy szomszédnak a téglafalon át.'::text,'átadta'::text,'át lett adva'::text,'átadva'::text,'Egy órája a postás átadta a születésnapi csomagot egy szomszédnak a téglafalon át.'::text),
(372027,41337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, das Paket ... ein Geburtstagsgeschenk sein, da ist überall Geburtstagspapier drauf, ohne Witz.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Digga, das Paket muss ein Geburtstagsgeschenk sein, da ist überall Geburtstagspapier drauf, ohne Witz.'::text),
(372031,41337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця посилка ... бути подарунком на день народження, вона вся в святковому папері, без жартів.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Бро, ця посилка мусить бути подарунком на день народження, вона вся в святковому папері, без жартів.'::text),
(372030,41337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese paquete ... ser un regalo de cumpleaños, está todo envuelto en papel de cumpleaños, en serio.'::text,'tiene que'::text,'no puede'::text,'no debe'::text,'Bro, ese paquete tiene que ser un regalo de cumpleaños, está todo envuelto en papel de cumpleaños, en serio.'::text),
(372029,41337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce colis ... être un cadeau d''anniversaire, il est couvert de papier d''anniversaire, sans mentir.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Frère, ce colis doit être un cadeau d''anniversaire, il est couvert de papier d''anniversaire, sans mentir.'::text),
(372032,41337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o paket doğum günü hediyesi ..., üstü baştan aşağı doğum günü kâğıdı, yalan yok.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Kanka, o paket doğum günü hediyesi olmalı, üstü baştan aşağı doğum günü kâğıdı, yalan yok.'::text),
(372033,41337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a csomag ... születésnapi ajándék, tele van szülinapi papírral, nem kamu.'::text,'biztos'::text,'nem lehet'::text,'nem szabad'::text,'Tesó, az a csomag biztos születésnapi ajándék, tele van szülinapi papírral, nem kamu.'::text),
(372036,41338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Geburtstagspaket, ... er um 9 Uhr übergab, erfüllte das tägliche Lieferziel.'::text,'das'::text,'wer'::text,'wo'::text,'Das Geburtstagspaket, das er um 9 Uhr übergab, erfüllte das tägliche Lieferziel.'::text),
(372040,41338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Посилка на день народження, ... він передав о 9:00, виконала денний план доставки.'::text,'яку'::text,'хто'::text,'де'::text,'Посилка на день народження, яку він передав о 9:00, виконала денний план доставки.'::text),
(372039,41338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El paquete de cumpleaños ... entregó a las 9:00 cumplió el objetivo diario de entregas.'::text,'que'::text,'quien'::text,'donde'::text,'El paquete de cumpleaños que entregó a las 9:00 cumplió el objetivo diario de entregas.'::text),
(372038,41338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le colis d''anniversaire ... il a remis à 9 h a atteint l''objectif quotidien de livraison.'::text,'que'::text,'qui'::text,'où'::text,'Le colis d''anniversaire que il a remis à 9 h a atteint l''objectif quotidien de livraison.'::text),
(372041,41338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9''da teslim ettiği ... doğum günü paketi günlük teslimat hedefini tuttu.'::text,''::text,NULL::text,NULL::text,'Saat 9''da teslim ettiği doğum günü paketi günlük teslimat hedefini tuttu.'::text),
(372042,41338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A születésnapi csomag, ... reggel 9-kor átadott, teljesítette a napi kézbesítési célt.'::text,'amelyet'::text,'aki'::text,'ahol'::text,'A születésnapi csomag, amelyet reggel 9-kor átadott, teljesítette a napi kézbesítési célt.'::text),
(372045,41339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Postbote sagte, er ... das Paket über die Mauer gereicht, weil die Mauer zwischen ihnen war.'::text,'habe'::text,'habe'::text,'reiche'::text,'Der Postbote sagte, er habe das Paket über die Mauer gereicht, weil die Mauer zwischen ihnen war.'::text),
(372049,41339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Листоноша сказав, що ... посилку через стіну, бо стіна була між ними.'::text,'передав'::text,'передав'::text,'передає'::text,'Листоноша сказав, що передав посилку через стіну, бо стіна була між ними.'::text),
(372048,41339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cartero dijo que ... el paquete por encima del muro porque el muro estaba entre ellos.'::text,'había pasado'::text,'ha pasado'::text,'pasa'::text,'El cartero dijo que había pasado el paquete por encima del muro porque el muro estaba entre ellos.'::text),
(372047,41339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le facteur a dit qu''il ... le colis par-dessus le mur parce que le mur était entre eux.'::text,'avait passé'::text,'a passé'::text,'passe'::text,'Le facteur a dit qu''il avait passé le colis par-dessus le mur parce que le mur était entre eux.'::text),
(372050,41339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Postacı, duvar aralarında olduğu için paketi duvarın üstünden ... söyledi.'::text,'uzattığını'::text,'uzattığını'::text,'uzattığını'::text,'Postacı, duvar aralarında olduğu için paketi duvarın üstünden uzattığını söyledi.'::text),
(372051,41339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A postás azt mondta, hogy ... a csomagot a falon, mert a fal köztük volt.'::text,'átadta'::text,'átadta'::text,'átadja'::text,'A postás azt mondta, hogy átadta a csomagot a falon, mert a fal köztük volt.'::text),
(372054,41340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Postboten ... typischerweise zu Fuß ihre Runden; dieser liefert das Paket mit dem Fahrrad.'::text,'liefen früher'::text,'waren es gewohnt zu laufen'::text,'liefen früher'::text,'Postboten liefen früher typischerweise zu Fuß ihre Runden; dieser liefert das Paket mit dem Fahrrad.'::text),
(372058,41340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Листоноші зазвичай ... свої маршрути пішки; цей доставляє посилку на велосипеді.'::text,'колись проходили'::text,'звикли проходити'::text,'колись проходили'::text,'Листоноші зазвичай колись проходили свої маршрути пішки; цей доставляє посилку на велосипеді.'::text),
(372057,41340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los carteros normalmente ... sus rutas a pie; este entrega el paquete en bicicleta.'::text,'solían recorrer'::text,'estaban acostumbrados a recorrer'::text,'solían recorrer'::text,'Los carteros normalmente solían recorrer sus rutas a pie; este entrega el paquete en bicicleta.'::text),
(372056,41340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les facteurs ... typiquement leurs tournées à pied ; celui-ci livre le colis à vélo.'::text,'faisaient autrefois'::text,'avaient l''habitude de faire'::text,'faisaient autrefois'::text,'Les facteurs faisaient autrefois typiquement leurs tournées à pied ; celui-ci livre le colis à vélo.'::text),
(372059,41340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Postacılar genellikle rotalarını yürüyerek ...; bu ise paketi bisikletle teslim ediyor.'::text,'dolaşırdı'::text,'dolaşmaya alışkındı'::text,'dolaşırdı'::text,'Postacılar genellikle rotalarını yürüyerek dolaşırdı; bu ise paketi bisikletle teslim ediyor.'::text),
(372060,41340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A postások jellemzően gyalog ... végig a körzetüket; ez itt biciklivel viszi ki a csomagot.'::text,'járták régen'::text,'hozzá voltak szokva, hogy járják'::text,'járták régen'::text,'A postások jellemzően gyalog járták régen végig a körzetüket; ez itt biciklivel viszi ki a csomagot.'::text),
(372063,41341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er besteht absolut darauf, jedes Paket persönlich ..., sogar über eine Backsteinmauer!'::text,'zuzustellen'::text,'zustellen'::text,'zustellen'::text,'Er besteht absolut darauf, jedes Paket persönlich zuzustellen, sogar über eine Backsteinmauer!'::text),
(372067,41341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він категорично наполягає на ... кожної посилки особисто, навіть через цегляну стіну!'::text,'доставці'::text,'доставити'::text,'доставити'::text,'Він категорично наполягає на доставці кожної посилки особисто, навіть через цегляну стіну!'::text),
(372066,41341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Insiste absolutamente en ... cada paquete en mano, incluso por encima de un muro de ladrillo!'::text,'entregar'::text,'entregar'::text,'entregar'::text,'¡Insiste absolutamente en entregar cada paquete en mano, incluso por encima de un muro de ladrillo!'::text),
(372065,41341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il tient absolument à ... chaque colis en main propre, même par-dessus un mur de briques !'::text,'livrer'::text,'livrer'::text,'livrer'::text,'Il tient absolument à livrer chaque colis en main propre, même par-dessus un mur de briques !'::text),
(372068,41341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her paketi elden ... kesinlikle ısrar ediyor, tuğla duvarın üstünden bile olsa!'::text,'teslim etmekte'::text,'teslim etmeye'::text,'teslim etmek'::text,'Her paketi elden teslim etmekte kesinlikle ısrar ediyor, tuğla duvarın üstünden bile olsa!'::text),
(372069,41341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abszolút ragaszkodik ahhoz, hogy minden csomagot személyesen ..., még egy téglafalon át is!'::text,'kézbesítsen'::text,'kézbesíteni'::text,'kézbesít'::text,'Abszolút ragaszkodik ahhoz, hogy minden csomagot személyesen kézbesítsen, még egy téglafalon át is!'::text),
(372072,41342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eines Postboten ist ein totaler Albtraum, ein Geburtstagspaket nach dem anderen!'::text,'Das Leben'::text,'Ein Leben'::text,'Leben'::text,'Das Leben eines Postboten ist ein totaler Albtraum, ein Geburtstagspaket nach dem anderen!'::text),
(372076,41342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... листоноші — це повний жах, одна посилка на день народження за іншою!'::text,'Життя'::text,'Життя'::text,'Життя'::text,'Життя листоноші — це повний жах, одна посилка на день народження за іншою!'::text),
(372075,41342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... de un cartero es una pesadilla total, un paquete de cumpleaños tras otro!'::text,'La vida'::text,'Una vida'::text,'Vida'::text,'¡La vida de un cartero es una pesadilla total, un paquete de cumpleaños tras otro!'::text),
(372074,41342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... d''un facteur est un vrai cauchemar, un colis d''anniversaire après l''autre !'::text,'La vie'::text,'Une vie'::text,'Vie'::text,'La vie d''un facteur est un vrai cauchemar, un colis d''anniversaire après l''autre !'::text),
(372077,41342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir postacının ... tam bir kâbus, arka arkaya doğum günü paketleri!'::text,'hayatı'::text,'bir hayatı'::text,'hayatı'::text,'Bir postacının hayatı tam bir kâbus, arka arkaya doğum günü paketleri!'::text),
(372078,41342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy postás ... totális rémálom, egyik szülinapi csomag a másik után!'::text,'élete'::text,'egy élete'::text,'élete'::text,'Egy postás élete totális rémálom, egyik szülinapi csomag a másik után!'::text),
(333615,37069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... auf den Teig, als plötzlich neben seinen Händen ein Holzhammer niedersauste.'::text,'haute gerade'::text,'haute'::text,'hat gehauen'::text,'Er haute gerade auf den Teig, als plötzlich neben seinen Händen ein Holzhammer niedersauste.'::text),
(333619,37069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... по тісту, коли раптом поруч із його руками опустився молоток.'::text,'гупав'::text,'гупнув'::text,'гупнув'::text,'Він гупав по тісту, коли раптом поруч із його руками опустився молоток.'::text),
(333618,37069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la masa cuando de repente un mazo cayó junto a sus manos.'::text,'Estaba golpeando'::text,'Golpeó'::text,'Ha golpeado'::text,'Estaba golpeando la masa cuando de repente un mazo cayó junto a sus manos.'::text),
(333617,37069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur la pâte quand un maillet s''est soudain abattu à côté de ses mains.'::text,'tapait'::text,'a tapé'::text,'a tapé'::text,'Il tapait sur la pâte quand un maillet s''est soudain abattu à côté de ses mains.'::text),
(333620,37069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellerinin yanına aniden bir tokmak indiğinde o hamura ...'::text,'vuruyordu'::text,'vurdu'::text,'vurdu'::text,'Ellerinin yanına aniden bir tokmak indiğinde o hamura vuruyordu.'::text),
(333621,37069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a tésztát, amikor hirtelen egy fakalapács csapódott le a keze mellett.'::text,'püfölte'::text,'megpüfölte'::text,'megpüfölte'::text,'Épp püfölte a tésztát, amikor hirtelen egy fakalapács csapódott le a keze mellett.'::text),
(333624,37070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küchenteam ... seit 45 Minuten Teig, deutlich vor dem Produktionsziel.'::text,'schlägt'::text,'schlägt'::text,'schlägt'::text,'Das Küchenteam schlägt seit 45 Minuten Teig, deutlich vor dem Produktionsziel.'::text),
(333628,37070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухонна команда ... тісто вже 45 хвилин, значно випереджаючи виробничий план.'::text,'б''є'::text,'б''є'::text,'б''є'::text,'Кухонна команда б''є тісто вже 45 хвилин, значно випереджаючи виробничий план.'::text),
(333627,37070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo de cocina ... masa durante 45 minutos, muy por delante del objetivo de producción.'::text,'ha estado golpeando'::text,'está golpeando'::text,'golpea'::text,'El equipo de cocina ha estado golpeando masa durante 45 minutos, muy por delante del objetivo de producción.'::text),
(333626,37070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe de cuisine ... la pâte depuis 45 minutes, bien en avance sur l''objectif de production.'::text,'frappe'::text,'frappe'::text,'frappe'::text,'L''équipe de cuisine frappe la pâte depuis 45 minutes, bien en avance sur l''objectif de production.'::text),
(333629,37070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfak ekibi 45 dakikadır hamura ..., üretim hedefinin çok önünde.'::text,'vuruyor'::text,'vuruyor'::text,'vurur'::text,'Mutfak ekibi 45 dakikadır hamura vuruyor, üretim hedefinin çok önünde.'::text),
(333630,37070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A konyhai csapat 45 perce ... a tésztát, jóval a termelési cél előtt.'::text,'püföli'::text,'püföli'::text,'püföli'::text,'A konyhai csapat 45 perce püföli a tésztát, jóval a termelési cél előtt.'::text),
(333633,37071,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie die Trommel ..., war es laut, denn eine geschlagene Trommel ist laut.'::text,'schlug'::text,'schlug'::text,'hat geschlagen'::text,'Während sie die Trommel schlug, war es laut, denn eine geschlagene Trommel ist laut.'::text),
(333637,37071,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... в барабан, було гучно, бо барабан, у який гупають, гучний.'::text,'гупала'::text,'гупнула'::text,'гупнула'::text,'Поки вона гупала в барабан, було гучно, бо барабан, у який гупають, гучний.'::text),
(333636,37071,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... el tambor, había mucho ruido, porque un tambor golpeado hace ruido.'::text,'golpeaba'::text,'golpeó'::text,'ha golpeado'::text,'Mientras golpeaba el tambor, había mucho ruido, porque un tambor golpeado hace ruido.'::text),
(333635,37071,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... sur le tambour, c''était fort, parce qu''un tambour qu''on frappe, c''est fort.'::text,'tapait'::text,'a tapé'::text,'a tapé'::text,'Pendant qu''elle tapait sur le tambour, c''était fort, parce qu''un tambour qu''on frappe, c''est fort.'::text),
(333638,37071,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O davula ... ses yüksekti, çünkü vurulan davul yüksek ses çıkarır.'::text,'vururken'::text,'vurdu'::text,'vurmuşken'::text,'O davula vururken ses yüksekti, çünkü vurulan davul yüksek ses çıkarır.'::text),
(333639,37071,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg ... a dobot, hangos volt, mert a püfölt dob hangos.'::text,'püfölte'::text,'megpüfölte'::text,'megpüfölte'::text,'Amíg püfölte a dobot, hangos volt, mert a püfölt dob hangos.'::text),
(333651,37073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er haut den Stößel so hart runter, dass die Pfefferkörner inzwischen völlig zerstört sein ...!'::text,'müssen'::text,'können nicht'::text,'sollten nicht'::text,'Er haut den Stößel so hart runter, dass die Pfefferkörner inzwischen völlig zerstört sein müssen!'::text),
(333655,37073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він так сильно гупає товкачиком, що перчинки вже ... бути повністю знищені!'::text,'мають'::text,'не можуть'::text,'не повинні'::text,'Він так сильно гупає товкачиком, що перчинки вже мають бути повністю знищені!'::text),
(333654,37073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Golpea con la mano del mortero tan fuerte que los granos de pimienta ... estar completamente destrozados a estas alturas!'::text,'deben de'::text,'no pueden'::text,'no deberían'::text,'¡Golpea con la mano del mortero tan fuerte que los granos de pimienta deben de estar completamente destrozados a estas alturas!'::text),
(333653,37073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il abat le pilon si fort que les grains de poivre ... être complètement détruits maintenant !'::text,'doivent'::text,'ne peuvent pas'::text,'ne devraient pas'::text,'Il abat le pilon si fort que les grains de poivre doivent être complètement détruits maintenant !'::text),
(333656,37073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havaneli o kadar sert vuruyor ki karabiberler şimdiye tamamen yok olmuş ...!'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Havaneli o kadar sert vuruyor ki karabiberler şimdiye tamamen yok olmuş olmalı!'::text),
(333657,37073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan erősen csapja le a mozsártörőt, hogy a borsszemek mostanra ... teljesen szét vannak zúzva!'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kellene, hogy'::text,'Olyan erősen csapja le a mozsártörőt, hogy a borsszemek mostanra biztosan teljesen szét vannak zúzva!'::text),
(333660,37074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... mit dem Holzhammer auf den Teig gehauen hat, hat das Frühstück für immer ruiniert!'::text,'der'::text,'welches'::text,'dessen'::text,'Der Mann, der mit dem Holzhammer auf den Teig gehauen hat, hat das Frühstück für immer ruiniert!'::text),
(333664,37074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... гупнув молотком по тісту, назавжди зіпсував сніданок!'::text,'який'::text,'що'::text,'чий'::text,'Чоловік, який гупнув молотком по тісту, назавжди зіпсував сніданок!'::text),
(333663,37074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El hombre ... golpeó el mazo contra la masa ha arruinado el desayuno para siempre!'::text,'que'::text,'el cual'::text,'cuyo'::text,'¡El hombre que golpeó el mazo contra la masa ha arruinado el desayuno para siempre!'::text),
(333662,37074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... a tapé le maillet sur la pâte a ruiné le petit-déjeuner pour toujours !'::text,'qui'::text,'lequel'::text,'dont'::text,'L''homme qui a tapé le maillet sur la pâte a ruiné le petit-déjeuner pour toujours !'::text),
(333665,37074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tokmağı hamura vuran ... adam kahvaltıyı sonsuza dek mahvetti!'::text,''::text,NULL::text,NULL::text,'Tokmağı hamura vuran adam kahvaltıyı sonsuza dek mahvetti!'::text),
(333666,37074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... rácsapott a fakalapáccsal a tésztára, örökre tönkretette a reggelit!'::text,'aki'::text,'amely'::text,'akinek'::text,'A férfi, aki rácsapott a fakalapáccsal a tésztára, örökre tönkretette a reggelit!'::text),
(333669,37075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bäcker schrie, jemand ... mit einem Holzhammer auf seinen Teig gehauen!'::text,'habe'::text,'habe'::text,'haue'::text,'Der Bäcker schrie, jemand habe mit einem Holzhammer auf seinen Teig gehauen!'::text),
(333673,37075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пекар кричав, що хтось ... по його тісту молотком!'::text,'гупнув'::text,'гупнув'::text,'гупає'::text,'Пекар кричав, що хтось гупнув по його тісту молотком!'::text),
(333672,37075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El panadero gritó que alguien ... su masa con un mazo!'::text,'había golpeado'::text,'ha golpeado'::text,'golpea'::text,'¡El panadero gritó que alguien había golpeado su masa con un mazo!'::text),
(333671,37075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le boulanger a hurlé que quelqu''un ... sur sa pâte avec un maillet !'::text,'avait tapé'::text,'a tapé'::text,'tape'::text,'Le boulanger a hurlé que quelqu''un avait tapé sur sa pâte avec un maillet !'::text),
(333674,37075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırıncı, birinin hamuruna tokmakla ... bağırdı!'::text,'vurduğunu'::text,'vurduğunu'::text,'vurduğunu'::text,'Fırıncı, birinin hamuruna tokmakla vurduğunu bağırdı!'::text),
(333675,37075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pék azt üvöltötte, hogy valaki ... a tésztájára egy fakalapáccsal!'::text,'rácsapott'::text,'rácsapott'::text,'rácsap'::text,'A pék azt üvöltötte, hogy valaki rácsapott a tésztájára egy fakalapáccsal!'::text),
(333678,37076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, sie ... angeblich auf jeder Party in der Schulzeit diese Trommel.'::text,'schlug früher'::text,'schlug früher'::text,'war es gewohnt zu schlagen'::text,'Süße, sie schlug früher angeblich auf jeder Party in der Schulzeit diese Trommel.'::text),
(333682,37076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... в той барабан на кожній вечірці ще в школі.'::text,'колись гупала'::text,'колись гупала'::text,'звикла гупати'::text,'Подруго, кажуть, вона колись гупала в той барабан на кожній вечірці ще в школі.'::text),
(333681,37076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ella ... golpear ese tambor en cada fiesta en el instituto.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Amiga, al parecer ella solía golpear ese tambor en cada fiesta en el instituto.'::text),
(333680,37076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... sur ce tambour à chaque soirée au lycée.'::text,'tapait'::text,'tapait'::text,'avait l''habitude de taper'::text,'Meuf, apparemment elle tapait sur ce tambour à chaque soirée au lycée.'::text),
(333683,37076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, galiba okuldayken her partide o davula ...'::text,'vururdu'::text,'vururdu'::text,'vurmaya alışkındı'::text,'Kızım, galiba okuldayken her partide o davula vururdu.'::text),
(333684,37076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a suliban minden buliban ... azt a dobot.'::text,'régen püfölte'::text,'régen püfölte'::text,'hozzászokott, hogy püfölje'::text,'Csajszi, állítólag a suliban minden buliban régen püfölte azt a dobot.'::text),
(333687,37077,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, dass es ihm einfach Spaß macht, mit dem Holzhammer auf Teig zu ...'::text,'hauen'::text,'hauen'::text,'hauen'::text,'Bestie, er hat mir erzählt, dass es ihm einfach Spaß macht, mit dem Holzhammer auf Teig zu hauen.'::text),
(333691,37077,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, він мені сказав, що йому просто подобається ... по тісту тим молотком.'::text,'гупати'::text,'гупати'::text,'гупати'::text,'Бесті, він мені сказав, що йому просто подобається гупати по тісту тим молотком.'::text),
(333690,37077,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, me dijo que simplemente le encanta ... la masa con ese mazo.'::text,'golpear'::text,'golpear'::text,'golpear'::text,'Bestie, me dijo que simplemente le encanta golpear la masa con ese mazo.'::text),
(333689,37077,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, il m''a dit qu''il aime juste ... sur la pâte avec ce maillet.'::text,'taper'::text,'taper'::text,'taper'::text,'Ma bestie, il m''a dit qu''il aime juste taper sur la pâte avec ce maillet.'::text),
(333692,37077,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana dedi ki o tokmakla hamura ... düpedüz seviyormuş.'::text,'vurmayı'::text,'vurmayı'::text,'vurmayı'::text,'Kanka, bana dedi ki o tokmakla hamura vurmayı düpedüz seviyormuş.'::text),
(333693,37077,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt mondta, egyszerűen élvezi ... a tésztát azzal a fakalapáccsal.'::text,'püfölni'::text,'püfölni'::text,'püfölni'::text,'Bestie, azt mondta, egyszerűen élvezi püfölni a tésztát azzal a fakalapáccsal.'::text),
(333705,37079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Trommel losging, ... er den Teig schon zweimal platt gehauen.'::text,'hatte'::text,'haute'::text,'hat'::text,'Als die Trommel losging, hatte er den Teig schon zweimal platt gehauen.'::text),
(333709,37079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли почав бити барабан, він уже двічі ... тісто.'::text,'розплющив'::text,'плющив'::text,'розплющив'::text,'Коли почав бити барабан, він уже двічі розплющив тісто.'::text),
(333708,37079,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empezó el tambor, él ya ... la masa hasta aplanarla dos veces.'::text,'había golpeado'::text,'estaba golpeando'::text,'ha golpeado'::text,'Cuando empezó el tambor, él ya había golpeado la masa hasta aplanarla dos veces.'::text),
(333707,37079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le tambour a commencé, il ... la pâte à plat deux fois.'::text,'avait tapé'::text,'tapait'::text,'a tapé'::text,'Quand le tambour a commencé, il avait tapé la pâte à plat deux fois.'::text),
(333710,37079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Davul başladığında o, hamuru iki kez vurarak ...'::text,'yassıltmıştı'::text,'yassıltıyordu'::text,'yassılttı'::text,'Davul başladığında o, hamuru iki kez vurarak yassıltmıştı.'::text),
(333711,37079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a dob megszólalt, ő már kétszer ... laposra a tésztát.'::text,'verte'::text,'verte épp'::text,'verte'::text,'Mire a dob megszólalt, ő már kétszer verte laposra a tésztát.'::text),
(339816,37758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit einer Stunde Saft, und sie ist immer noch total fröhlich!'::text,'gießt'::text,'hat gegossen'::text,'gießt'::text,'Sie gießt seit einer Stunde Saft, und sie ist immer noch total fröhlich!'::text),
(339820,37758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... сік уже годину, і досі абсолютно весела!'::text,'наливає'::text,'налила'::text,'наливає'::text,'Вона наливає сік уже годину, і досі абсолютно весела!'::text),
(339819,37758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... zumo durante una hora y sigue totalmente alegre!'::text,'Ha estado sirviendo'::text,'Ha servido'::text,'Está sirviendo'::text,'¡Ha estado sirviendo zumo durante una hora y sigue totalmente alegre!'::text),
(339818,37758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... du jus depuis une heure, et elle est toujours super joyeuse !'::text,'sert'::text,'a servi'::text,'sert'::text,'Elle sert du jus depuis une heure, et elle est toujours super joyeuse !'::text),
(339821,37758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saattir meyve suyu ... ve hâlâ son derece neşeli!'::text,'dolduruyor'::text,'doldurdu'::text,'dolduruyor'::text,'Bir saattir meyve suyu dolduruyor ve hâlâ son derece neşeli!'::text),
(339822,37758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órája ... a gyümölcslevet, és még mindig teljesen vidám!'::text,'tölti'::text,'töltötte'::text,'tölti'::text,'Egy órája tölti a gyümölcslevet, és még mindig teljesen vidám!'::text),
(339825,37759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verwandten ... sie vor jener Nacht noch nie so fröhlich gesehen. Der ganze Tisch schrie!'::text,'hatten'::text,'haben'::text,'sahen'::text,'Die Verwandten hatten sie vor jener Nacht noch nie so fröhlich gesehen. Der ganze Tisch schrie!'::text),
(339829,37759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родичі ... її такою веселою до того вечора. Весь стіл кричав!'::text,'ніколи не бачили'::text,'ніколи не бачили'::text,'ніколи не бачили'::text,'Родичі ніколи не бачили її такою веселою до того вечора. Весь стіл кричав!'::text),
(339828,37759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los parientes ... tan alegre antes de esa noche. ¡Toda la mesa gritó!'::text,'nunca la habían visto'::text,'nunca la han visto'::text,'nunca la estaban viendo'::text,'Los parientes nunca la habían visto tan alegre antes de esa noche. ¡Toda la mesa gritó!'::text),
(339827,37759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les proches ... aussi joyeuse avant ce soir-là. Toute la table a crié !'::text,'ne l''avaient jamais vue'::text,'ne l''ont jamais vue'::text,'ne la voyaient jamais'::text,'Les proches ne l''avaient jamais vue aussi joyeuse avant ce soir-là. Toute la table a crié !'::text),
(339830,37759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akrabalar onu o geceden önce hiç bu kadar neşeli ...: bütün masa çığlık attı!'::text,'görmemişlerdi'::text,'görmediler'::text,'görmüyorlardı'::text,'Akrabalar onu o geceden önce hiç bu kadar neşeli görmemişlerdi: bütün masa çığlık attı!'::text),
(339831,37759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rokonok aznap estig ... őt ilyen vidámnak. Az egész asztal sikított!'::text,'még sosem látták'::text,'sosem látták'::text,'sosem látták'::text,'A rokonok aznap estig még sosem látták őt ilyen vidámnak. Az egész asztal sikított!'::text),
(339834,37760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder Saft gießen, für immer fröhlich, und niemand kann sie aufhalten!'::text,'wird'::text,'wird'::text,'gießt'::text,'Morgen um diese Zeit wird sie wieder Saft gießen, für immer fröhlich, und niemand kann sie aufhalten!'::text),
(339838,37760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... сік, вічно весела, і ніхто її не зупинить!'::text,'наливатиме'::text,'наллє'::text,'наливає'::text,'Завтра в цей час вона знову наливатиме сік, вічно весела, і ніхто її не зупинить!'::text),
(339837,37760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... zumo otra vez, alegre para siempre, y nadie podrá pararla!'::text,'estará sirviendo'::text,'servirá'::text,'sirve'::text,'¡Mañana a esta hora estará sirviendo zumo otra vez, alegre para siempre, y nadie podrá pararla!'::text),
(339836,37760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore du jus, joyeuse pour toujours, et personne ne peut l''arrêter !'::text,'sera en train de servir'::text,'servira'::text,'sert'::text,'Demain à la même heure, elle sera en train de servir encore du jus, joyeuse pour toujours, et personne ne peut l''arrêter !'::text),
(339839,37760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine meyve suyu ..., sonsuza dek neşeli, ve kimse onu durduramaz!'::text,'dolduruyor olacak'::text,'dolduracak'::text,'dolduruyor'::text,'Yarın bu saatlerde yine meyve suyu dolduruyor olacak, sonsuza dek neşeli, ve kimse onu durduramaz!'::text),
(339840,37760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a gyümölcslevet, örökké vidáman, és senki sem állíthatja meg!'::text,'tölteni fogja'::text,'tölteni fogja'::text,'tölti'::text,'Holnap ilyenkor megint tölteni fogja a gyümölcslevet, örökké vidáman, és senki sem állíthatja meg!'::text),
(339843,37761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie schwört, dass sie auch beim nächsten Abendessen jedem das Glas ..., fröhlich wie immer.'::text,'füllen wird'::text,'füllen wird'::text,'füllt'::text,'Hör zu, sie schwört, dass sie auch beim nächsten Abendessen jedem das Glas füllen wird, fröhlich wie immer.'::text),
(339847,37761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона клянеться, що й на наступній вечері ... кожному келих, весела як завжди.'::text,'наповнить'::text,'наповнюватиме'::text,'наповнює'::text,'Слухай, вона клянеться, що й на наступній вечері наповнить кожному келих, весела як завжди.'::text),
(339846,37761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, jura que en la próxima cena también ... el vaso de todos, alegre como siempre.'::text,'llenará'::text,'estará llenando'::text,'llena'::text,'Escucha, jura que en la próxima cena también llenará el vaso de todos, alegre como siempre.'::text),
(339845,37761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle jure qu''elle ... aussi le verre de tout le monde au prochain dîner, joyeuse comme toujours.'::text,'remplira'::text,'sera en train de remplir'::text,'remplit'::text,'Écoute, elle jure qu''elle remplira aussi le verre de tout le monde au prochain dîner, joyeuse comme toujours.'::text),
(339848,37761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bir sonraki akşam yemeğinde de herkesin bardağını ... yemin ediyor, her zamanki gibi neşeli.'::text,'dolduracağına'::text,'dolduruyor olacağına'::text,'doldurduğuna'::text,'Dinle, bir sonraki akşam yemeğinde de herkesin bardağını dolduracağına yemin ediyor, her zamanki gibi neşeli.'::text),
(339849,37761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy a következő vacsorán is ... mindenki poharát, vidáman, mint mindig.'::text,'megtölti'::text,'tölteni fogja'::text,'tölti'::text,'Figyelj, esküszik, hogy a következő vacsorán is megtölti mindenki poharát, vidáman, mint mindig.'::text),
(339852,37762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Krug hoch ..., werden die Verwandten immer fröhlich.'::text,'hebt'::text,'hob'::text,'heben wird'::text,'Wenn sie den Krug hoch hebt, werden die Verwandten immer fröhlich.'::text),
(339856,37762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона ... глечик високо, родичі завжди стають веселими.'::text,'піднімає'::text,'підняла'::text,'підніме'::text,'Коли вона піднімає глечик високо, родичі завжди стають веселими.'::text),
(339855,37762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella ... la jarra en alto, los parientes siempre se ponen alegres.'::text,'levanta'::text,'levantó'::text,'levantará'::text,'Si ella levanta la jarra en alto, los parientes siempre se ponen alegres.'::text),
(339854,37762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ... la carafe bien haut, les proches deviennent toujours joyeux.'::text,'lève'::text,'levait'::text,'lèvera'::text,'Si elle lève la carafe bien haut, les proches deviennent toujours joyeux.'::text),
(339857,37762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürahiyi yukarı ..., akrabalar hep neşeleniyor.'::text,'kaldırırsa'::text,'kaldırsaydı'::text,'kaldıracaksa'::text,'Sürahiyi yukarı kaldırırsa, akrabalar hep neşeleniyor.'::text),
(339858,37762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... magasra a kancsót, a rokonok mindig felvidulnak.'::text,'felemeli'::text,'felemelte'::text,'fel fogja emelni'::text,'Ha felemeli magasra a kancsót, a rokonok mindig felvidulnak.'::text),
(339870,37764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich deine fröhliche Energie hätte, ... ich auch Saft aus der Höhe gießen, ehrlich.'::text,'würde'::text,'werde'::text,'goss'::text,'Wenn ich deine fröhliche Energie hätte, würde ich auch Saft aus der Höhe gießen, ehrlich.'::text),
(339874,37764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я мав твою веселу енергію, я теж ... сік з такої висоти, чесно.'::text,'наливав би'::text,'наливатиму'::text,'наливав'::text,'Якби я мав твою веселу енергію, я теж наливав би сік з такої висоти, чесно.'::text),
(339873,37764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si yo tuviera tu energía alegre, también ... zumo desde tan alto, la verdad.'::text,'serviría'::text,'serviré'::text,'serví'::text,'Si yo tuviera tu energía alegre, también serviría zumo desde tan alto, la verdad.'::text),
(339872,37764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si j''avais ton énergie joyeuse, je ... aussi du jus d''aussi haut, franchement.'::text,'verserais'::text,'verserai'::text,'versais'::text,'Si j''avais ton énergie joyeuse, je verserais aussi du jus d''aussi haut, franchement.'::text),
(339875,37764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin neşeli enerjin bende olsa, ben de o yükseklikten meyve suyu ..., açıkçası.'::text,'doldururdum'::text,'dolduracağım'::text,'doldurdum'::text,'Senin neşeli enerjin bende olsa, ben de o yükseklikten meyve suyu doldururdum, açıkçası.'::text),
(339876,37764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nekem is ilyen vidám energiám lenne, én is ... a gyümölcslevet ilyen magasról, őszintén.'::text,'tölteném'::text,'tölteni fogom'::text,'töltöttem'::text,'Ha nekem is ilyen vidám energiám lenne, én is tölteném a gyümölcslevet ilyen magasról, őszintén.'::text),
(339879,37765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... jedes Glas von der fröhlichen Frau im gemusterten Kleid gefüllt.'::text,'wurde'::text,'wird'::text,'füllte'::text,'Gestern Abend wurde jedes Glas von der fröhlichen Frau im gemusterten Kleid gefüllt.'::text),
(339883,37765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері кожен келих ... веселою жінкою у візерунчастій сукні.'::text,'був наповнений'::text,'наповнюється'::text,'наповнила'::text,'Учора ввечері кожен келих був наповнений веселою жінкою у візерунчастій сукні.'::text),
(339882,37765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche cada vaso ... por la mujer alegre del vestido estampado.'::text,'fue llenado'::text,'es llenado'::text,'llenó'::text,'Anoche cada vaso fue llenado por la mujer alegre del vestido estampado.'::text),
(339881,37765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, chaque verre ... par la femme joyeuse à la robe à motifs.'::text,'a été rempli'::text,'est rempli'::text,'a rempli'::text,'Hier soir, chaque verre a été rempli par la femme joyeuse à la robe à motifs.'::text),
(339884,37765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam her bardak desenli elbiseli neşeli kadın tarafından ...'::text,'dolduruldu'::text,'dolduruluyor'::text,'doldurdu'::text,'Dün akşam her bardak desenli elbiseli neşeli kadın tarafından dolduruldu.'::text),
(339885,37765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este minden pohár ... a mintás ruhás vidám nő által.'::text,'meg lett töltve'::text,'meg van töltve'::text,'megtöltött'::text,'Tegnap este minden pohár meg lett töltve a mintás ruhás vidám nő által.'::text),
(339888,37766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Abenddämmerung ... die fröhliche Frau Orangensaft in hohe Gläser.'::text,'goss'::text,'wurde gegossen'::text,'gießend'::text,'In der Abenddämmerung goss die fröhliche Frau Orangensaft in hohe Gläser.'::text),
(339892,37766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У сутінках весела жінка ... апельсиновий сік у високі склянки.'::text,'налила'::text,'була налита'::text,'наливаючи'::text,'У сутінках весела жінка налила апельсиновий сік у високі склянки.'::text),
(339891,37766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al anochecer, la mujer alegre ... zumo de naranja en vasos altos.'::text,'sirvió'::text,'fue servida'::text,'sirviendo'::text,'Al anochecer, la mujer alegre sirvió zumo de naranja en vasos altos.'::text),
(339890,37766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au crépuscule, la femme joyeuse ... du jus d''orange dans de grands verres.'::text,'a versé'::text,'a été versée'::text,'versant'::text,'Au crépuscule, la femme joyeuse a versé du jus d''orange dans de grands verres.'::text),
(339893,37766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıkta neşeli kadın uzun bardaklara portakal suyu ...'::text,'doldurdu'::text,'dolduruldu'::text,'doldurarak'::text,'Alacakaranlıkta neşeli kadın uzun bardaklara portakal suyu doldurdu.'::text),
(339894,37766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szürkületkor a vidám nő ... narancslevet a magas poharakba.'::text,'töltött'::text,'töltve lett'::text,'töltve'::text,'Szürkületkor a vidám nő töltött narancslevet a magas poharakba.'::text),
(339897,37767,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verwandten lachen und klatschen, also ... sie sich auch fröhlich fühlen.'::text,'müssen'::text,'können nicht'::text,'sollten nicht'::text,'Die Verwandten lachen und klatschen, also müssen sie sich auch fröhlich fühlen.'::text),
(339901,37767,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родичі сміються й плескають, тож вони теж ... почуватися весело.'::text,'мають'::text,'не можуть'::text,'не повинні'::text,'Родичі сміються й плескають, тож вони теж мають почуватися весело.'::text),
(339900,37767,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los parientes se ríen y aplauden, así que ... sentirse alegres también.'::text,'deben de'::text,'no pueden'::text,'no deberían'::text,'Los parientes se ríen y aplauden, así que deben de sentirse alegres también.'::text),
(339899,37767,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les proches rient et applaudissent, donc ils ... se sentir joyeux aussi.'::text,'doivent'::text,'ne peuvent pas'::text,'ne devraient pas'::text,'Les proches rient et applaudissent, donc ils doivent se sentir joyeux aussi.'::text),
(339902,37767,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akrabalar gülüp alkışlıyor, demek ki onlar da neşeli ...'::text,'hissediyor olmalı'::text,'hissediyor olamaz'::text,'hissetmemeli'::text,'Akrabalar gülüp alkışlıyor, demek ki onlar da neşeli hissediyor olmalı.'::text),
(339903,37767,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rokonok nevetnek és tapsolnak, szóval ők is ... vidámnak érzik magukat.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kéne, hogy'::text,'A rokonok nevetnek és tapsolnak, szóval ők is biztosan vidámnak érzik magukat.'::text),
(339906,37768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Individuum, ... den Saft aus der Höhe gießt, zeigt eine auffallend fröhliche Stimmung.'::text,'das'::text,'welches'::text,'dessen'::text,'Das Individuum, das den Saft aus der Höhe gießt, zeigt eine auffallend fröhliche Stimmung.'::text),
(339910,37768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особа, ... наливає сік з висоти, демонструє помітно веселий настрій.'::text,'яка'::text,'котра'::text,'чия'::text,'Особа, яка наливає сік з висоти, демонструє помітно веселий настрій.'::text),
(339909,37768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El individuo ... sirve el zumo desde lo alto muestra un estado de ánimo notablemente alegre.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El individuo que sirve el zumo desde lo alto muestra un estado de ánimo notablemente alegre.'::text),
(339908,37768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''individu ... verse le jus de haut affiche une humeur remarquablement joyeuse.'::text,'qui'::text,'lequel'::text,'dont'::text,'L''individu qui verse le jus de haut affiche une humeur remarquablement joyeuse.'::text),
(339911,37768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meyve suyunu yüksekten döken ... birey belirgin biçimde neşeli bir ruh hali sergiliyor.'::text,''::text,NULL::text,NULL::text,'Meyve suyunu yüksekten döken birey belirgin biçimde neşeli bir ruh hali sergiliyor.'::text),
(339912,37768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyén, ... magasról tölti a gyümölcslevet, feltűnően vidám hangulatot mutat.'::text,'aki'::text,'amely'::text,'akinek'::text,'Az egyén, aki magasról tölti a gyümölcslevet, feltűnően vidám hangulatot mutat.'::text),
(370191,41133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, während du Tee aus dieser Höhe ..., hat niemand auch nur auf den Schnurrbart geschaut.'::text,'gossest'::text,'gossest'::text,'hast gegossen'::text,'Ehrlich, während du Tee aus dieser Höhe gossest, hat niemand auch nur auf den Schnurrbart geschaut.'::text),
(370195,41133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки ти ... чай з такої висоти, ніхто навіть не глянув на вуса.'::text,'наливав'::text,'налив'::text,'налив'::text,'Чесно, поки ти наливав чай з такої висоти, ніхто навіть не глянув на вуса.'::text),
(370194,41133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, mientras ... té desde esa altura, nadie miró siquiera el bigote.'::text,'servías'::text,'serviste'::text,'has servido'::text,'La verdad, mientras servías té desde esa altura, nadie miró siquiera el bigote.'::text),
(370193,41133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, pendant que tu ... le thé de si haut, personne n''a même regardé la moustache.'::text,'versais'::text,'as versé'::text,'as versé'::text,'Franchement, pendant que tu versais le thé de si haut, personne n''a même regardé la moustache.'::text),
(370196,41133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen o yükseklikten çay ..., kimse bıyığa bakmadı bile.'::text,'dökerken'::text,'döktüğünde'::text,'dökmüşken'::text,'Açıkçası, sen o yükseklikten çay dökerken, kimse bıyığa bakmadı bile.'::text),
(370197,41133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, amíg te ... a teát ilyen magasról, senki rá sem nézett a bajuszra.'::text,'töltötted'::text,'kitöltötted'::text,'kitöltötted'::text,'Őszintén, amíg te töltötted a teát ilyen magasról, senki rá sem nézett a bajuszra.'::text),
(370200,41134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leicht beeindruckend: Der Kellner mit dem Schnurrbart ... seit einer Stunde Tee von über seinem Kopf.'::text,'gießt'::text,'gießt'::text,'gießt'::text,'Leicht beeindruckend: Der Kellner mit dem Schnurrbart gießt seit einer Stunde Tee von über seinem Kopf.'::text),
(370204,41134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи вражає: офіціант з вусами ... чай з-над голови вже годину.'::text,'наливає'::text,'наливає'::text,'наливає'::text,'Трохи вражає: офіціант з вусами наливає чай з-над голови вже годину.'::text),
(370203,41134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ligeramente impresionante: el camarero del bigote ... té desde encima de su cabeza durante una hora.'::text,'ha estado sirviendo'::text,'está sirviendo'::text,'sirve'::text,'Ligeramente impresionante: el camarero del bigote ha estado sirviendo té desde encima de su cabeza durante una hora.'::text),
(370202,41134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Légèrement impressionnant : le serveur à moustache ... du thé au-dessus de sa tête depuis une heure.'::text,'verse'::text,'verse'::text,'verse'::text,'Légèrement impressionnant : le serveur à moustache verse du thé au-dessus de sa tête depuis une heure.'::text),
(370205,41134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafiften etkileyici: bıyıklı garson bir saattir başının üstünden çay ...'::text,'döküyor'::text,'döküyor'::text,'döker'::text,'Hafiften etkileyici: bıyıklı garson bir saattir başının üstünden çay döküyor.'::text),
(370206,41134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enyhén lenyűgöző: a bajuszos pincér egy órája ... a teát a feje fölül.'::text,'tölti'::text,'tölti'::text,'tölti'::text,'Enyhén lenyűgöző: a bajuszos pincér egy órája tölti a teát a feje fölül.'::text),
(370209,41135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, natürlich: Er ... den Tee von hoch oben, als ein Tropfen fast seinen Schnurrbart traf.'::text,'goss gerade'::text,'goss'::text,'hat gegossen'::text,'Super gemacht, natürlich: Er goss gerade den Tee von hoch oben, als ein Tropfen fast seinen Schnurrbart traf.'::text),
(370213,41135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, звісно: він ... чай з висоти, коли крапля мало не влучила йому у вуса.'::text,'лив'::text,'налив'::text,'налив'::text,'Чудова робота, звісно: він лив чай з висоти, коли крапля мало не влучила йому у вуса.'::text),
(370212,41135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran trabajo, obviamente: ... el té desde muy alto cuando una gota casi le dio en el bigote.'::text,'estaba sirviendo'::text,'sirvió'::text,'ha servido'::text,'Gran trabajo, obviamente: estaba sirviendo el té desde muy alto cuando una gota casi le dio en el bigote.'::text),
(370211,41135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, évidemment : il ... le thé de très haut quand une goutte a failli toucher sa moustache.'::text,'versait'::text,'a versé'::text,'a versé'::text,'Bravo, évidemment : il versait le thé de très haut quand une goutte a failli toucher sa moustache.'::text),
(370214,41135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, tabii ki: bir damla neredeyse bıyığına çarptığında çayı yukarıdan ...'::text,'döküyordu'::text,'döktü'::text,'döktü'::text,'Harika iş, tabii ki: bir damla neredeyse bıyığına çarptığında çayı yukarıdan döküyordu.'::text),
(370215,41135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, persze: épp ... a teát magasról, amikor egy csepp majdnem eltalálta a bajuszát.'::text,'töltötte'::text,'kitöltötte'::text,'kitöltötte'::text,'Szép munka, persze: épp töltötte a teát magasról, amikor egy csepp majdnem eltalálta a bajuszát.'::text),
(370218,41136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine große Sache: Er ... heute Abend zwölf Gläser Tee eingeschenkt, ohne einen Tropfen auf dem Schnurrbart.'::text,'hat'::text,'hat'::text,'schenkt'::text,'Keine große Sache: Er hat heute Abend zwölf Gläser Tee eingeschenkt, ohne einen Tropfen auf dem Schnurrbart.'::text),
(370222,41136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нічого особливого: він сьогодні ввечері ... дванадцять склянок чаю без жодної краплі на вусах.'::text,'налив'::text,'наливав'::text,'наливає'::text,'Нічого особливого: він сьогодні ввечері налив дванадцять склянок чаю без жодної краплі на вусах.'::text),
(370221,41136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nada del otro mundo: esta noche ... doce vasos de té sin una gota en el bigote.'::text,'ha servido'::text,'ha estado sirviendo'::text,'sirve'::text,'Nada del otro mundo: esta noche ha servido doce vasos de té sin una gota en el bigote.'::text),
(370220,41136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rien de spécial : il ... douze verres de thé ce soir sans une goutte sur sa moustache.'::text,'a servi'::text,'a servi'::text,'sert'::text,'Rien de spécial : il a servi douze verres de thé ce soir sans une goutte sur sa moustache.'::text),
(370223,41136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük olay değil: bu akşam bıyığına tek damla düşürmeden on iki bardak çay ...'::text,'doldurdu'::text,'dolduruyor'::text,'doldurur'::text,'Büyük olay değil: bu akşam bıyığına tek damla düşürmeden on iki bardak çay doldurdu.'::text),
(370224,41136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Semmi különös: ma este ... tizenkét pohár teát egyetlen csepp nélkül a bajuszán.'::text,'töltött ki'::text,'töltöget'::text,'tölt'::text,'Semmi különös: ma este töltött ki tizenkét pohár teát egyetlen csepp nélkül a bajuszán.'::text),
(370236,41138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er wieder Tee aus dieser Höhe gießen, und sein Schnurrbart ist nie sicher!'::text,'wird'::text,'wird'::text,'gießt'::text,'Morgen um diese Zeit wird er wieder Tee aus dieser Höhe gießen, und sein Schnurrbart ist nie sicher!'::text),
(370240,41138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він знову ... чай з тієї висоти, і його вуса ніколи не в безпеці!'::text,'литиме'::text,'наллє'::text,'ллє'::text,'Завтра в цей час він знову литиме чай з тієї висоти, і його вуса ніколи не в безпеці!'::text),
(370239,41138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... té desde esa altura otra vez, y su bigote nunca está a salvo!'::text,'estará sirviendo'::text,'servirá'::text,'sirve'::text,'¡Mañana a esta hora estará sirviendo té desde esa altura otra vez, y su bigote nunca está a salvo!'::text),
(370238,41138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... encore du thé de cette hauteur, et sa moustache n''est jamais en sécurité !'::text,'sera en train de verser'::text,'versera'::text,'verse'::text,'Demain à la même heure, il sera en train de verser encore du thé de cette hauteur, et sa moustache n''est jamais en sécurité !'::text),
(370241,41138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine o yükseklikten çay ..., ve bıyığı asla güvende değil!'::text,'döküyor olacak'::text,'dökecek'::text,'döküyor'::text,'Yarın bu saatlerde yine o yükseklikten çay döküyor olacak, ve bıyığı asla güvende değil!'::text),
(370242,41138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a teát abból a magasságból, és a bajusza sosincs biztonságban!'::text,'tölteni fogja'::text,'tölteni fogja'::text,'tölti'::text,'Holnap ilyenkor megint tölteni fogja a teát abból a magasságból, és a bajusza sosincs biztonságban!'::text),
(370245,41139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kellner mit dem Schnurrbart verspricht, dass er das nächste Glas aus noch größerer Höhe ...'::text,'einschenken wird'::text,'einschenken wird'::text,'einschenkt'::text,'Der Kellner mit dem Schnurrbart verspricht, dass er das nächste Glas aus noch größerer Höhe einschenken wird.'::text),
(370249,41139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіціант з вусами обіцяє, що наступну склянку ... з іще більшої висоти.'::text,'наллє'::text,'наливатиме'::text,'наливає'::text,'Офіціант з вусами обіцяє, що наступну склянку наллє з іще більшої висоти.'::text),
(370248,41139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camarero del bigote promete que ... el siguiente vaso desde aún más alto.'::text,'servirá'::text,'estará sirviendo'::text,'está sirviendo'::text,'El camarero del bigote promete que servirá el siguiente vaso desde aún más alto.'::text),
(370247,41139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le serveur à moustache promet qu''il ... le prochain verre d''encore plus haut.'::text,'versera'::text,'sera en train de verser'::text,'verse'::text,'Le serveur à moustache promet qu''il versera le prochain verre d''encore plus haut.'::text),
(370250,41139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bıyıklı garson bir sonraki bardağı daha da yukarıdan ... söz veriyor.'::text,'dolduracağına'::text,'dolduruyor olacağına'::text,'doldurduğuna'::text,'Bıyıklı garson bir sonraki bardağı daha da yukarıdan dolduracağına söz veriyor.'::text),
(370251,41139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bajuszos pincér megígéri, hogy a következő poharat még magasabbról ...'::text,'tölti ki'::text,'fogja tölteni'::text,'tölti épp'::text,'A bajuszos pincér megígéri, hogy a következő poharat még magasabbról tölti ki.'::text),
(370254,41140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Mann mit dem Schnurrbart die Kanne höher ..., wird der Teestrahl länger.'::text,'hebt'::text,'hob'::text,'heben wird'::text,'Wenn der Mann mit dem Schnurrbart die Kanne höher hebt, wird der Teestrahl länger.'::text),
(370258,41140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли чоловік з вусами ... чайник вище, струмінь чаю стає довшим.'::text,'піднімає'::text,'підняв'::text,'підніме'::text,'Коли чоловік з вусами піднімає чайник вище, струмінь чаю стає довшим.'::text),
(370257,41140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hombre del bigote ... la tetera más alto, el chorro de té se hace más largo.'::text,'levanta'::text,'levantó'::text,'levantará'::text,'Si el hombre del bigote levanta la tetera más alto, el chorro de té se hace más largo.'::text),
(370256,41140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''homme à moustache ... la théière plus haut, le filet de thé s''allonge.'::text,'lève'::text,'levait'::text,'lèvera'::text,'Si l''homme à moustache lève la théière plus haut, le filet de thé s''allonge.'::text),
(370259,41140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bıyıklı adam demliği daha yukarı ..., çay akışı uzuyor.'::text,'kaldırırsa'::text,'kaldırsaydı'::text,'kaldıracaksa'::text,'Bıyıklı adam demliği daha yukarı kaldırırsa, çay akışı uzuyor.'::text),
(370260,41140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a bajuszos férfi magasabbra ... a kannát, a teasugár hosszabb lesz.'::text,'emeli'::text,'emelte'::text,'fogja emelni'::text,'Ha a bajuszos férfi magasabbra emeli a kannát, a teasugár hosszabb lesz.'::text),
(370263,41141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er Tee verschüttet, ... der Kellner mit dem Schnurrbart ein neues Glas.'::text,'bringt'::text,'würde bringen'::text,'brachte'::text,'Wenn er Tee verschüttet, bringt der Kellner mit dem Schnurrbart ein neues Glas.'::text),
(370267,41141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він розіллє трохи чаю, офіціант з вусами ... нову склянку.'::text,'принесе'::text,'приніс би'::text,'приніс'::text,'Якщо він розіллє трохи чаю, офіціант з вусами принесе нову склянку.'::text),
(370266,41141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si derrama algo de té, el camarero del bigote ... un vaso nuevo.'::text,'traerá'::text,'traería'::text,'trajo'::text,'Si derrama algo de té, el camarero del bigote traerá un vaso nuevo.'::text),
(370265,41141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il renverse du thé, le serveur à moustache ... un nouveau verre.'::text,'apportera'::text,'apporterait'::text,'a apporté'::text,'S''il renverse du thé, le serveur à moustache apportera un nouveau verre.'::text),
(370268,41141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz çay dökerse, bıyıklı garson yeni bir bardak ...'::text,'getirecek'::text,'getirirdi'::text,'getirdi'::text,'Biraz çay dökerse, bıyıklı garson yeni bir bardak getirecek.'::text),
(370269,41141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kiönt egy kis teát, a bajuszos pincér ... egy új poharat.'::text,'hoz'::text,'hozna'::text,'hozott'::text,'Ha kiönt egy kis teát, a bajuszos pincér hoz egy új poharat.'::text),
(370272,41142,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich Tee so wie du ..., würde ich mir nur wegen des Styles einen Schnurrbart wachsen lassen.'::text,'gießen würde'::text,'gieße'::text,'gießen würde'::text,'Ehrlich, wenn ich Tee so wie du gießen würde, würde ich mir nur wegen des Styles einen Schnurrbart wachsen lassen.'::text),
(370276,41142,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я ... чай, як ти, я б відростив вуса тільки заради стилю.'::text,'наливав'::text,'наливаю'::text,'наливав би'::text,'Чесно, якби я наливав чай, як ти, я б відростив вуса тільки заради стилю.'::text),
(370275,41142,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si yo ... té como tú, me dejaría bigote solo por el estilo.'::text,'sirviera'::text,'sirvo'::text,'serviría'::text,'La verdad, si yo sirviera té como tú, me dejaría bigote solo por el estilo.'::text),
(370274,41142,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si je ... le thé comme toi, je me laisserais pousser la moustache juste pour le style.'::text,'versais'::text,'verse'::text,'verserais'::text,'Franchement, si je versais le thé comme toi, je me laisserais pousser la moustache juste pour le style.'::text),
(370277,41142,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin gibi çay ..., sırf tarz olsun diye bıyık bırakırdım.'::text,'döksem'::text,'dökersem'::text,'dökerdim'::text,'Açıkçası, senin gibi çay döksem, sırf tarz olsun diye bıyık bırakırdım.'::text),
(370278,41142,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha úgy ... a teát, mint te, csak a stílus kedvéért bajuszt növesztenék.'::text,'tölteném'::text,'töltöm'::text,'tölteném'::text,'Őszintén, ha úgy tölteném a teát, mint te, csak a stílus kedvéért bajuszt növesztenék.'::text),
(359544,39950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, anscheinend ... ihr das dunkelblaue Kopftuch, in dem sie backt, von ihrer Oma geschenkt.'::text,'wurde'::text,'wird'::text,'schenkte'::text,'Okay, also, anscheinend wurde ihr das dunkelblaue Kopftuch, in dem sie backt, von ihrer Oma geschenkt.'::text),
(359548,39950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, темно-синя хустка, в якій вона пече, ... їй від бабусі.'::text,'дісталася'::text,'дістається'::text,'подарувала'::text,'Отже, кажуть, темно-синя хустка, в якій вона пече, дісталася їй від бабусі.'::text),
(359547,39950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer el pañuelo azul marino con el que hornea le ... por su abuela.'::text,'fue regalado'::text,'es regalado'::text,'regaló'::text,'Vale, al parecer el pañuelo azul marino con el que hornea le fue regalado por su abuela.'::text),
(359546,39950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment le foulard bleu marine avec lequel elle cuisine lui ... par sa grand-mère.'::text,'a été offert'::text,'est offert'::text,'a offert'::text,'Bon alors, apparemment le foulard bleu marine avec lequel elle cuisine lui a été offert par sa grand-mère.'::text),
(359549,39950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, galiba pişirirken taktığı lacivert başörtüsü ona büyükannesi tarafından ...'::text,'verilmiş'::text,'veriliyor'::text,'verdi'::text,'Tamam, galiba pişirirken taktığı lacivert başörtüsü ona büyükannesi tarafından verilmiş.'::text),
(359550,39950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag a sötétkék fejkendőt, amiben süt, a nagymamájától ...'::text,'kapta'::text,'kapja'::text,'adta'::text,'Oké, szóval állítólag a sötétkék fejkendőt, amiben süt, a nagymamájától kapta.'::text),
(359553,39951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, sie ... das Kopftuch selbst, bevor sie die Kekse gebacken hat.'::text,'machte'::text,'wurde gemacht'::text,'machend'::text,'Hör zu, ich hab gehört, sie machte das Kopftuch selbst, bevor sie die Kekse gebacken hat.'::text),
(359557,39951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вона ... ту хустку сама, перш ніж спекла печиво.'::text,'зробила'::text,'була зроблена'::text,'роблячи'::text,'Слухай, я чула, що вона зробила ту хустку сама, перш ніж спекла печиво.'::text),
(359556,39951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, oí que ella ... ese pañuelo ella misma antes de hornear las galletas.'::text,'hizo'::text,'fue hecha'::text,'haciendo'::text,'Escucha, oí que ella hizo ese pañuelo ella misma antes de hornear las galletas.'::text),
(359555,39951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''elle ... ce foulard elle-même avant de faire les cookies.'::text,'a fait'::text,'a été faite'::text,'faisant'::text,'Écoute, j''ai entendu dire qu''elle a fait ce foulard elle-même avant de faire les cookies.'::text),
(359558,39951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki kurabiyeleri pişirmeden önce o başörtüsünü kendisi ...'::text,'yapmış'::text,'yapılmış'::text,'yaparak'::text,'Dinle, duydum ki kurabiyeleri pişirmeden önce o başörtüsünü kendisi yapmış.'::text),
(359559,39951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy ... azt a fejkendőt saját maga, mielőtt megsütötte a kekszet.'::text,'csinálta'::text,'meg lett csinálva'::text,'csinálva'::text,'Figyelj, azt hallottam, hogy csinálta azt a fejkendőt saját maga, mielőtt megsütötte a kekszet.'::text),
(359571,39953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Kopftuch dunkelblau ist, schiebt das Blech mit Keksen in den Ofen.'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Kopftuch dunkelblau ist, schiebt das Blech mit Keksen in den Ofen.'::text),
(359575,39953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... хустка темно-синя, засуває деко з печивом у духовку.'::text,'чия'::text,'яка'::text,'котра'::text,'Жінка, чия хустка темно-синя, засуває деко з печивом у духовку.'::text),
(359574,39953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... pañuelo es azul marino mete la bandeja de galletas en el horno.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La mujer cuyo pañuelo es azul marino mete la bandeja de galletas en el horno.'::text),
(359573,39953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... le foulard est bleu marine glisse la plaque de cookies dans le four.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La femme dont le foulard est bleu marine glisse la plaque de cookies dans le four.'::text),
(359576,39953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başörtüsü lacivert olan ... kadın kurabiye tepsisini fırına sürüyor.'::text,''::text,NULL::text,NULL::text,'Başörtüsü lacivert olan kadın kurabiye tepsisini fırına sürüyor.'::text),
(359577,39953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a nő, ... fejkendője sötétkék, betolja a kekszes tepsit a sütőbe.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Az a nő, akinek a fejkendője sötétkék, betolja a kekszes tepsit a sütőbe.'::text),
(359580,39954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau mit dem Kopftuch hat uns erzählt, sie ... den Teig am Abend davor gemacht.'::text,'habe'::text,'habe'::text,'mache'::text,'Die Frau mit dem Kopftuch hat uns erzählt, sie habe den Teig am Abend davor gemacht.'::text),
(359584,39954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в хустці розповіла нам, що ... тісто напередодні ввечері.'::text,'зробила'::text,'зробила'::text,'робить'::text,'Жінка в хустці розповіла нам, що зробила тісто напередодні ввечері.'::text),
(359583,39954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer del pañuelo nos dijo que ... la masa la noche anterior.'::text,'había hecho'::text,'ha hecho'::text,'hace'::text,'La mujer del pañuelo nos dijo que había hecho la masa la noche anterior.'::text),
(359582,39954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme au foulard nous a dit qu''elle ... la pâte la veille au soir.'::text,'avait fait'::text,'a fait'::text,'fait'::text,'La femme au foulard nous a dit qu''elle avait fait la pâte la veille au soir.'::text),
(359585,39954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başörtülü kadın bize hamuru bir önceki akşam ... söyledi.'::text,'yaptığını'::text,'yaptığını'::text,'yaptığını'::text,'Başörtülü kadın bize hamuru bir önceki akşam yaptığını söyledi.'::text),
(359586,39954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fejkendős nő azt mondta nekünk, hogy ... a tésztát előző este.'::text,'megcsinálta'::text,'megcsinálta'::text,'csinálja'::text,'A fejkendős nő azt mondta nekünk, hogy megcsinálta a tésztát előző este.'::text),
(359589,39955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau mit dem Kopftuch ... einen winzigen Ofen, aber jetzt hat sie diesen großen.'::text,'hatte früher'::text,'hatte früher'::text,'ist gewohnt, zu haben'::text,'Die Frau mit dem Kopftuch hatte früher einen winzigen Ofen, aber jetzt hat sie diesen großen.'::text),
(359593,39955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в хустці ... крихітну духовку, а тепер має оцю велику.'::text,'колись мала'::text,'мала'::text,'звикла мати'::text,'Жінка в хустці колись мала крихітну духовку, а тепер має оцю велику.'::text),
(359592,39955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer del pañuelo ... tener un horno diminuto, pero ahora tiene este tan grande.'::text,'solía'::text,'solía'::text,'está acostumbrada a'::text,'La mujer del pañuelo solía tener un horno diminuto, pero ahora tiene este tan grande.'::text),
(359591,39955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme au foulard ... un minuscule four, mais maintenant elle a ce grand-là.'::text,'avait autrefois'::text,'avait'::text,'a l''habitude d''avoir'::text,'La femme au foulard avait autrefois un minuscule four, mais maintenant elle a ce grand-là.'::text),
(359594,39955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başörtülü kadının eskiden minicik bir fırını ..., ama şimdi bu büyük fırını var.'::text,'vardı'::text,'olurdu'::text,'olmaya alışkın'::text,'Başörtülü kadının eskiden minicik bir fırını vardı, ama şimdi bu büyük fırını var.'::text),
(359595,39955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fejkendős nőnek régen apró sütője ..., de most itt ez a nagy.'::text,'volt'::text,'volt'::text,'szokott lenni'::text,'A fejkendős nőnek régen apró sütője volt, de most itt ez a nagy.'::text),
(359598,39956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi mit Kopftuch: Sie hat daran gedacht, den Ofen ..., bevor sie das Blech hob.'::text,'zu öffnen'::text,'geöffnet zu haben'::text,'öffnen'::text,'Ein echter Profi mit Kopftuch: Sie hat daran gedacht, den Ofen zu öffnen, bevor sie das Blech hob.'::text),
(359602,39956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжня профі в хустці: вона не забула ... духовку, перш ніж підняти деко.'::text,'відчинити'::text,'як відчиняла'::text,'відчинити'::text,'Справжня профі в хустці: вона не забула відчинити духовку, перш ніж підняти деко.'::text),
(359601,39956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda una profesional con pañuelo: se acordó de ... el horno antes de levantar la bandeja.'::text,'abrir'::text,'haber abierto'::text,'abrir'::text,'Toda una profesional con pañuelo: se acordó de abrir el horno antes de levantar la bandeja.'::text),
(359600,39956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une vraie pro en foulard : elle a pensé à ... le four avant de soulever la plaque.'::text,'ouvrir'::text,'avoir ouvert'::text,'ouvrir'::text,'Une vraie pro en foulard : elle a pensé à ouvrir le four avant de soulever la plaque.'::text),
(359603,39956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başörtülü gerçek bir profesyonel: tepsiyi kaldırmadan önce fırını ... unutmadı.'::text,'açmayı'::text,'açtığını'::text,'açmayı'::text,'Başörtülü gerçek bir profesyonel: tepsiyi kaldırmadan önce fırını açmayı unutmadı.'::text),
(359604,39956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi fejkendőben: nem felejtette el ... a sütőt, mielőtt felemelte a tepsit.'::text,'kinyitni'::text,'kinyitást'::text,'kinyitni'::text,'Igazi profi fejkendőben: nem felejtette el kinyitni a sütőt, mielőtt felemelte a tepsit.'::text),
(359607,39957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kekse in einem dunkelblauen Kopftuch zu backen ist eindeutig der härteste Job der Welt, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Kekse in einem dunkelblauen Kopftuch zu backen ist eindeutig der härteste Job der Welt, oder?'::text),
(359611,39957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пекти печиво в темно-синій хустці — це явно найважча робота у світі, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Пекти печиво в темно-синій хустці — це явно найважча робота у світі, так?'::text),
(359610,39957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hornear galletas con un pañuelo azul marino es claramente el trabajo más duro del mundo, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Hornear galletas con un pañuelo azul marino es claramente el trabajo más duro del mundo, ¿verdad?'::text),
(359609,39957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Faire des cookies avec un foulard bleu marine, c''est clairement le boulot le plus dur du monde, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Faire des cookies avec un foulard bleu marine, c''est clairement le boulot le plus dur du monde, n''est-ce pas ?'::text),
(359612,39957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lacivert başörtüsüyle kurabiye pişirmek açıkça dünyanın en zor işi, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Lacivert başörtüsüyle kurabiye pişirmek açıkça dünyanın en zor işi, değil mi?'::text),
(359613,39957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sötétkék fejkendőben kekszet sütni egyértelműen a világ legnehezebb munkája, ...?'::text,'nem?'::text,'nem?'::text,'nem?'::text,'Sötétkék fejkendőben kekszet sütni egyértelműen a világ legnehezebb munkája, nem?'::text),
(359616,39958,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ihr Kopftuch nicht am heißen Ofen verbrannt, und ... Tolle Leistung.'::text,'die Kekse auch nicht.'::text,'die Kekse auch nicht.'::text,'die Kekse auch.'::text,'Sie hat ihr Kopftuch nicht am heißen Ofen verbrannt, und die Kekse auch nicht. Tolle Leistung.'::text),
(359620,39958,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не підпалила свою хустку об гарячу духовку, і ... Чудова робота.'::text,'печиво теж ні.'::text,'печиво теж ні.'::text,'печиво теж.'::text,'Вона не підпалила свою хустку об гарячу духовку, і печиво теж ні. Чудова робота.'::text),
(359619,39958,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No se ha quemado el pañuelo con el horno caliente, y ... Buen trabajo.'::text,'las galletas tampoco.'::text,'las galletas tampoco.'::text,'las galletas también.'::text,'No se ha quemado el pañuelo con el horno caliente, y las galletas tampoco. Buen trabajo.'::text),
(359618,39958,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''a pas brûlé son foulard sur le four chaud, et ... Bravo.'::text,'les cookies non plus.'::text,'les cookies non plus.'::text,'les cookies aussi.'::text,'Elle n''a pas brûlé son foulard sur le four chaud, et les cookies non plus. Bravo.'::text),
(359621,39958,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başörtüsünü sıcak fırında yakmadı, ... Harika iş.'::text,'kurabiyeler de yanmadı.'::text,'kurabiyeler de yanmadı.'::text,'kurabiyeler de öyle.'::text,'Başörtüsünü sıcak fırında yakmadı, kurabiyeler de yanmadı. Harika iş.'::text),
(359622,39958,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem égette meg a fejkendőjét a forró sütőn, és ... Szép munka.'::text,'a keksz sem.'::text,'a keksz sem.'::text,'a keksz is.'::text,'Nem égette meg a fejkendőjét a forró sütőn, és a keksz sem. Szép munka.'::text),
(359625,39959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit Stunden Kekse gebacken, also roch ihr Kopftuch total nach Schokolade!'::text,'hatte'::text,'hat'::text,'backte'::text,'Sie hatte seit Stunden Kekse gebacken, also roch ihr Kopftuch total nach Schokolade!'::text),
(359629,39959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... печиво годинами, тож її хустка аж пахла шоколадом!'::text,'пекла'::text,'пече'::text,'пекла'::text,'Вона пекла печиво годинами, тож її хустка аж пахла шоколадом!'::text),
(359628,39959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... galletas durante horas, así que su pañuelo olía totalmente a chocolate!'::text,'Había estado horneando'::text,'Ha estado horneando'::text,'Estaba horneando'::text,'¡Había estado horneando galletas durante horas, así que su pañuelo olía totalmente a chocolate!'::text),
(359627,39959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des cookies depuis des heures, donc son foulard sentait carrément le chocolat !'::text,'faisait'::text,'fait'::text,'faisait'::text,'Elle faisait des cookies depuis des heures, donc son foulard sentait carrément le chocolat !'::text),
(359630,39959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saatlerdir kurabiye ..., bu yüzden başörtüsü resmen çikolata kokuyordu!'::text,'pişiriyordu'::text,'pişiriyor'::text,'pişiriyordu'::text,'Saatlerdir kurabiye pişiriyordu, bu yüzden başörtüsü resmen çikolata kokuyordu!'::text),
(359631,39959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órák óta ... a kekszet, így a fejkendője totál csokiszagú volt!'::text,'sütötte'::text,'süti'::text,'sütötte'::text,'Órák óta sütötte a kekszet, így a fejkendője totál csokiszagú volt!'::text),
(378858,42096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, wenn sie ohne Handschuh in den Ofen gegriffen hätte, ... sie sich die Hand verbrannt, echt.'::text,'hätte'::text,'wird'::text,'verbrannte'::text,'Nee, wenn sie ohne Handschuh in den Ofen gegriffen hätte, hätte sie sich die Hand verbrannt, echt.'::text),
(378862,42096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не-не, якби вона полізла в духовку без рукавиці, вона ... руку, реально.'::text,'обпекла б'::text,'обпече'::text,'обпекла'::text,'Не-не, якби вона полізла в духовку без рукавиці, вона обпекла б руку, реально.'::text),
(378861,42096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, si hubiera metido la mano en el horno sin guante, ... la mano, en serio.'::text,'se habría quemado'::text,'se quemará'::text,'se quemó'::text,'Qué va, si hubiera metido la mano en el horno sin guante, se habría quemado la mano, en serio.'::text),
(378860,42096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si elle avait plongé la main dans le four sans gant, elle ... la main, sérieux.'::text,'se serait brûlé'::text,'se brûlera'::text,'s''est brûlé'::text,'Nan, si elle avait plongé la main dans le four sans gant, elle se serait brûlé la main, sérieux.'::text),
(378863,42096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, fırına eldivensiz uzansaydı elini ..., cidden.'::text,'yakardı'::text,'yakacak'::text,'yaktı'::text,'Yok, fırına eldivensiz uzansaydı elini yakardı, cidden.'::text),
(378864,42096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha kesztyű nélkül nyúlt volna be a sütőbe, ... a kezét, komolyan.'::text,'megégette volna'::text,'meg fogja égetni'::text,'megégette'::text,'Á, ha kesztyű nélkül nyúlt volna be a sütőbe, megégette volna a kezét, komolyan.'::text),
(378867,42097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie nicht die Hand ausgestreckt hätte, um die Hitze zu prüfen, ... die Kekse jetzt roh.'::text,'wären'::text,'wären gewesen'::text,'werden sein'::text,'Wenn sie nicht die Hand ausgestreckt hätte, um die Hitze zu prüfen, wären die Kekse jetzt roh.'::text),
