(378870,42097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera estirado la mano para comprobar el calor, las galletas ... crudas ahora.'::text,'estarían'::text,'habrían estado'::text,'estarán'::text,'Si no hubiera estirado la mano para comprobar el calor, las galletas estarían crudas ahora.'::text),
