(378872,42097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcaklığı test etmek için elini uzatmasaydı, kurabiyeler şimdi çiğ ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Sıcaklığı test etmek için elini uzatmasaydı, kurabiyeler şimdi çiğ olurdu.'::text),
(378873,42097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem nyúlt volna oda, hogy ellenőrizze a hőséget, a keksz most nyers ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem nyúlt volna oda, hogy ellenőrizze a hőséget, a keksz most nyers lenne.'::text),
(378876,42098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ofen soll zehn Minuten lang heiß ..., bevor sie danach griff.'::text,'gewesen sein'::text,'sein'::text,'seiend'::text,'Der Ofen soll zehn Minuten lang heiß gewesen sein, bevor sie danach griff.'::text),
(378880,42098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що духовка ... гарячою десять хвилин, перш ніж вона до неї потяглася.'::text,'була'::text,'є'::text,'будучи'::text,'Вважається, що духовка була гарячою десять хвилин, перш ніж вона до неї потяглася.'::text),
(378879,42098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el horno ... caliente durante diez minutos antes de que ella se acercara a él.'::text,'había estado'::text,'está'::text,'estando'::text,'Se cree que el horno había estado caliente durante diez minutos antes de que ella se acercara a él.'::text),
(378878,42098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le four ... chaud pendant dix minutes avant qu''elle ne tende la main vers lui.'::text,'avait été'::text,'est'::text,'étant'::text,'On pense que le four avait été chaud pendant dix minutes avant qu''elle ne tende la main vers lui.'::text),
(378881,42098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırının, o ona uzanmadan önce on dakika boyunca sıcak ... sanılıyor.'::text,'olduğu'::text,'olduğu'::text,'olarak'::text,'Fırının, o ona uzanmadan önce on dakika boyunca sıcak olduğu sanılıyor.'::text),
(378882,42098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, a sütő tíz percig forró ..., mielőtt a nő felé nyúlt.'::text,'volt'::text,'van'::text,'lévén'::text,'Úgy tartják, a sütő tíz percig forró volt, mielőtt a nő felé nyúlt.'::text),
(378885,42099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestritt, mit bloßer Hand in den heißen Ofen ...'::text,'gegriffen zu haben'::text,'zu greifen'::text,'greifen'::text,'Sie bestritt, mit bloßer Hand in den heißen Ofen gegriffen zu haben.'::text),
(378889,42099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона заперечила, що ... в гарячу духовку голою рукою.'::text,'лізла'::text,'лізти'::text,'лізти'::text,'Вона заперечила, що лізла в гарячу духовку голою рукою.'::text),
(378888,42099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... en el horno caliente con la mano desnuda.'::text,'haber metido la mano'::text,'meter la mano'::text,'meter la mano'::text,'Negó haber metido la mano en el horno caliente con la mano desnuda.'::text),
(378887,42099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a nié ... dans le four chaud à mains nues.'::text,'avoir plongé la main'::text,'plonger la main'::text,'plonger la main'::text,'Elle a nié avoir plongé la main dans le four chaud à mains nues.'::text),
(378890,42099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcak fırına çıplak eliyle ... inkâr etti.'::text,'uzandığını'::text,'uzanmayı'::text,'uzanmak'::text,'Sıcak fırına çıplak eliyle uzandığını inkâr etti.'::text),
(378891,42099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy puszta kézzel ... a forró sütőbe.'::text,'belenyúlt'::text,'belenyúlni'::text,'belenyúl'::text,'Tagadta, hogy puszta kézzel belenyúlt a forró sütőbe.'::text),
(378894,42100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Plan, natürlich: Sie ... zu den Ofenhandschuhen greifen sollen, bevor sie dem Ofen zu nahe kam.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Toller Plan, natürlich: Sie hätte zu den Ofenhandschuhen greifen sollen, bevor sie dem Ofen zu nahe kam.'::text),
(378898,42100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий план, звісно: вона ... взяти прихватки, перш ніж підходити до тієї духовки.'::text,'мала'::text,'мусила'::text,'не могла'::text,'Чудовий план, звісно: вона мала взяти прихватки, перш ніж підходити до тієї духовки.'::text),
(378897,42100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran plan, obviamente: ella ... cogido los guantes de horno antes de acercarse a ese horno.'::text,'debería haber'::text,'debe de haber'::text,'no puede haber'::text,'Gran plan, obviamente: ella debería haber cogido los guantes de horno antes de acercarse a ese horno.'::text),
(378896,42100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super plan, évidemment : elle ... prendre des gants de cuisine avant de s''approcher de ce four.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Super plan, évidemment : elle aurait dû prendre des gants de cuisine avant de s''approcher de ce four.'::text),
(378899,42100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika plan, tabii ki: o fırına yaklaşmadan önce fırın eldivenlerine ...'::text,'uzanmalıydı'::text,'uzanmış olmalı'::text,'uzanmış olamaz'::text,'Harika plan, tabii ki: o fırına yaklaşmadan önce fırın eldivenlerine uzanmalıydı.'::text),
(378900,42100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek terv, persze: ... a sütőkesztyű után nyúlnia, mielőtt odament ahhoz a sütőhöz.'::text,'kellett volna'::text,'biztosan kellett'::text,'nem kellett'::text,'Remek terv, persze: kellett volna a sütőkesztyű után nyúlnia, mielőtt odament ahhoz a sütőhöz.'::text),
(378903,42101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie in meinem Leben ... jemanden so ruhig nach einem heißen Ofen greifen sehen. Makellos.'::text,'habe ich'::text,'ich habe'::text,'habe ich'::text,'Noch nie in meinem Leben habe ich jemanden so ruhig nach einem heißen Ofen greifen sehen. Makellos.'::text),
(378907,42101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи в житті ... нікого, хто б так спокійно тягнувся до гарячої духовки. Бездоганно.'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи в житті я не бачив нікого, хто б так спокійно тягнувся до гарячої духовки. Бездоганно.'::text),
(378906,42101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca en mi vida ... a nadie acercar la mano a un horno caliente con tanta calma. Impecable.'::text,'he visto'::text,'yo he visto'::text,'he visto'::text,'Nunca en mi vida he visto a nadie acercar la mano a un horno caliente con tanta calma. Impecable.'::text),
(378905,42101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais de ma vie ... quelqu''un tendre la main vers un four chaud aussi calmement. Impeccable.'::text,'n''ai-je vu'::text,'je n''ai vu'::text,'n''ai-je vu'::text,'Jamais de ma vie n''ai-je vu quelqu''un tendre la main vers un four chaud aussi calmement. Impeccable.'::text),
(378908,42101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayatımda hiç kimsenin sıcak bir fırına bu kadar sakin uzandığını ...: kusursuz.'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Hayatımda hiç kimsenin sıcak bir fırına bu kadar sakin uzandığını görmedim: kusursuz.'::text),
(378909,42101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha életemben ... még senkit ilyen nyugodtan egy forró sütő felé nyúlni. Hibátlan.'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha életemben nem láttam még senkit ilyen nyugodtan egy forró sütő felé nyúlni. Hibátlan.'::text),
(378912,42102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Sie hätte jemanden dazu bringen sollen, für sie in diesen glühenden Ofen zu ...!'::text,'greifen'::text,'greifen'::text,'greifen'::text,'Katastrophe! Sie hätte jemanden dazu bringen sollen, für sie in diesen glühenden Ofen zu greifen!'::text),
(378916,42102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Вона мала попросити когось ... в ту розпечену духовку замість неї!'::text,'залізти'::text,'залізти'::text,'залізання'::text,'Катастрофа! Вона мала попросити когось залізти в ту розпечену духовку замість неї!'::text),
(378915,42102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Debería haber conseguido que alguien ... en ese horno ardiente por ella!'::text,'metiera la mano'::text,'meter la mano'::text,'metiendo la mano'::text,'¡Desastre! ¡Debería haber conseguido que alguien metiera la mano en ese horno ardiente por ella!'::text),
(378914,42102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Elle aurait dû demander à quelqu''un de ... dans ce four brûlant à sa place !'::text,'plonger la main'::text,'plonger la main'::text,'plonger la main'::text,'Catastrophe ! Elle aurait dû demander à quelqu''un de plonger la main dans ce four brûlant à sa place !'::text),
(378917,42102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O yanan fırına kendi yerine birine elini ...!'::text,'uzattırmalıydı'::text,'uzattırmalıydı'::text,'uzattırmalıydı'::text,'Felaket! O yanan fırına kendi yerine birine elini uzattırmalıydı!'::text),
(378918,42102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Meg kellett volna kérnie valakit, hogy helyette ... abba az izzó sütőbe!'::text,'nyúljon be'::text,'benyúlni'::text,'benyúlás'::text,'Katasztrófa! Meg kellett volna kérnie valakit, hogy helyette nyúljon be abba az izzó sütőbe!'::text),
(378921,42103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie ... in diesen furchteinflößenden Ofen greifen, ohne die Hitze zu spüren!'::text,'könnte'::text,'kann'::text,'wird'::text,'Sie wünschte, sie könnte in diesen furchteinflößenden Ofen greifen, ohne die Hitze zu spüren!'::text),
(378925,42103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хотіла б, щоб ... залізти в ту жахливу духовку, не відчуваючи жару!'::text,'могла'::text,'може'::text,'зможе'::text,'Вона хотіла б, щоб могла залізти в ту жахливу духовку, не відчуваючи жару!'::text),
(378924,42103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ella ... meter la mano en ese horno aterrador sin sentir el calor!'::text,'pudiera'::text,'puede'::text,'podrá'::text,'¡Ojalá ella pudiera meter la mano en ese horno aterrador sin sentir el calor!'::text),
(378923,42103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement elle ... plonger la main dans ce four terrifiant sans sentir la chaleur !'::text,'pouvait'::text,'peut'::text,'pourra'::text,'Si seulement elle pouvait plonger la main dans ce four terrifiant sans sentir la chaleur !'::text),
(378926,42103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke o korkunç fırına sıcaklığı hissetmeden ...!'::text,'uzanabilse'::text,'uzanabiliyor'::text,'uzanabilecek'::text,'Keşke o korkunç fırına sıcaklığı hissetmeden uzanabilse!'::text),
(378927,42103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ... benyúlni abba a rémisztő sütőbe anélkül, hogy érezné a hőséget!'::text,'tudna'::text,'tud'::text,'tudni fog'::text,'Bárcsak tudna benyúlni abba a rémisztő sütőbe anélkül, hogy érezné a hőséget!'::text),
(378930,42104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hatte der Ofen, nach ... sie griff, schon 200 Grad.'::text,'dem'::text,'dessen'::text,'wo'::text,'Mädel, angeblich hatte der Ofen, nach dem sie griff, schon 200 Grad.'::text),
(378934,42104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, духовка, до ... вона потяглася, вже мала 200 градусів.'::text,'якої'::text,'чиєї'::text,'де'::text,'Подруго, кажуть, духовка, до якої вона потяглася, вже мала 200 градусів.'::text),
(378933,42104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el horno hacia ... estiró la mano ya estaba a 200 grados.'::text,'el que'::text,'cuyo'::text,'donde'::text,'Amiga, al parecer el horno hacia el que estiró la mano ya estaba a 200 grados.'::text),
(378932,42104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le four vers ... elle a tendu la main était déjà à 200 degrés.'::text,'lequel'::text,'dont'::text,'où'::text,'Meuf, apparemment le four vers lequel elle a tendu la main était déjà à 200 degrés.'::text),
(378935,42104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, galiba uzandığı ... fırın çoktan 200 dereceymiş.'::text,''::text,NULL::text,NULL::text,'Kızım, galiba uzandığı fırın çoktan 200 dereceymiş.'::text),
(378936,42104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a sütő, ... odanyúlt, már 200 fokos volt.'::text,'amelyhez'::text,'amelynek'::text,'ahol'::text,'Csajszi, állítólag a sütő, amelyhez odanyúlt, már 200 fokos volt.'::text),
(378939,42105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie streckte die Hand zum Ofen aus, ... die Hitze zu prüfen, bevor das Blech hineinkam.'::text,'um'::text,'im Falle'::text,'trotz'::text,'Sie streckte die Hand zum Ofen aus, um die Hitze zu prüfen, bevor das Blech hineinkam.'::text),
(378943,42105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона потяглася до духовки, ... перевірити жар, перш ніж поставити деко.'::text,'щоб'::text,'у разі'::text,'попри'::text,'Вона потяглася до духовки, щоб перевірити жар, перш ніж поставити деко.'::text),
(378942,42105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estiró la mano hacia el horno ... comprobar el calor antes de meter la bandeja.'::text,'para'::text,'en caso de'::text,'a pesar de'::text,'Estiró la mano hacia el horno para comprobar el calor antes de meter la bandeja.'::text),
(378941,42105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a tendu la main vers le four ... vérifier la chaleur avant d''enfourner la plaque.'::text,'afin de'::text,'en cas de'::text,'malgré'::text,'Elle a tendu la main vers le four afin de vérifier la chaleur avant d''enfourner la plaque.'::text),
(378944,42105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepsi girmeden önce sıcaklığı kontrol etmek ... fırına uzandı.'::text,'için'::text,'durumunda'::text,'rağmen'::text,'Tepsi girmeden önce sıcaklığı kontrol etmek için fırına uzandı.'::text),
(378945,42105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sütő felé nyúlt, ... ellenőrizze a hőséget, mielőtt a tepsi bekerült.'::text,'hogy'::text,'esetén'::text,'ellenére'::text,'A sütő felé nyúlt, hogy ellenőrizze a hőséget, mielőtt a tepsi bekerült.'::text),
(387210,43024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit dem Frühstück ... sie ihre Unterschrift unter ein Dokument nach dem anderen.'::text,'setzt'::text,'setzt'::text,'setzt'::text,'Seit dem Frühstück setzt sie ihre Unterschrift unter ein Dokument nach dem anderen.'::text),
(387214,43024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від сніданку вона ... свій підпис на одному документі за іншим.'::text,'ставить'::text,'ставить'::text,'ставить'::text,'Від сніданку вона ставить свій підпис на одному документі за іншим.'::text),
(387213,43024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde el desayuno, ... su firma en un documento tras otro.'::text,'ha estado poniendo'::text,'está poniendo'::text,'pone'::text,'Desde el desayuno, ha estado poniendo su firma en un documento tras otro.'::text),
(387212,43024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis le petit-déjeuner, elle ... sa signature sur un document après l''autre.'::text,'appose'::text,'appose'::text,'appose'::text,'Depuis le petit-déjeuner, elle appose sa signature sur un document après l''autre.'::text),
(387215,43024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahvaltıdan beri belgelere art arda imzasını ...'::text,'atıyor'::text,'atıyor'::text,'atar'::text,'Kahvaltıdan beri belgelere art arda imzasını atıyor.'::text),
(387216,43024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reggeli óta ... az aláírását egyik dokumentumra a másik után.'::text,'teszi'::text,'teszi'::text,'teszi'::text,'Reggeli óta teszi az aláírását egyik dokumentumra a másik után.'::text),
(387219,43025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Unterschrift, als die Menge draußen zu jubeln begann.'::text,'schrieb gerade'::text,'schrieb'::text,'hat geschrieben'::text,'Sie schrieb gerade ihre Unterschrift, als die Menge draußen zu jubeln begann.'::text),
(387223,43025,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свій підпис, коли натовп надворі почав радіти.'::text,'писала'::text,'написала'::text,'написала'::text,'Вона писала свій підпис, коли натовп надворі почав радіти.'::text),
(387222,43025,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su firma cuando la multitud de fuera empezó a aclamar.'::text,'Estaba escribiendo'::text,'Escribió'::text,'Ha escrito'::text,'Estaba escribiendo su firma cuando la multitud de fuera empezó a aclamar.'::text),
(387221,43025,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sa signature quand la foule dehors a commencé à acclamer.'::text,'écrivait'::text,'a écrit'::text,'a écrit'::text,'Elle écrivait sa signature quand la foule dehors a commencé à acclamer.'::text),
(387224,43025,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dışarıdaki kalabalık tezahürata başladığında o imzasını ...'::text,'atıyordu'::text,'attı'::text,'attı'::text,'Dışarıdaki kalabalık tezahürata başladığında o imzasını atıyordu.'::text),
(387225,43025,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az aláírását, amikor a kinti tömeg ujjongani kezdett.'::text,'írta'::text,'leírta'::text,'leírta'::text,'Épp írta az aláírását, amikor a kinti tömeg ujjongani kezdett.'::text),
(387228,43026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute ... sie ihre Unterschrift unter drei offizielle Dokumente gesetzt.'::text,'hat'::text,'hat'::text,'setzt'::text,'Heute hat sie ihre Unterschrift unter drei offizielle Dokumente gesetzt.'::text),
(387232,43026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вона ... свій підпис на трьох офіційних документах.'::text,'поставила'::text,'ставила'::text,'ставить'::text,'Сьогодні вона поставила свій підпис на трьох офіційних документах.'::text),
(387231,43026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... su firma en tres documentos oficiales.'::text,'ha puesto'::text,'ha estado poniendo'::text,'está poniendo'::text,'Hoy ha puesto su firma en tres documentos oficiales.'::text),
(387230,43026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aujourd''hui, elle ... sa signature sur trois documents officiels.'::text,'a apposé'::text,'a apposé'::text,'appose'::text,'Aujourd''hui, elle a apposé sa signature sur trois documents officiels.'::text),
(387233,43026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün üç resmi belgeye imzasını ...'::text,'attı'::text,'atıyor'::text,'atıyor'::text,'Bugün üç resmi belgeye imzasını attı.'::text),
(387234,43026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma három hivatalos dokumentumra ... az aláírását.'::text,'tette rá'::text,'tette'::text,'teszi épp'::text,'Ma három hivatalos dokumentumra tette rá az aláírását.'::text),
(387237,43027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als du auf den Balkon kamst, ... du deine Unterschrift schon unter den Deal gesetzt, ehrlich.'::text,'hattest'::text,'hast'::text,'setztest'::text,'Als du auf den Balkon kamst, hattest du deine Unterschrift schon unter den Deal gesetzt, ehrlich.'::text),
(387241,43027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти вийшла на балкон, ти вже ... свій підпис під угодою, чесно.'::text,'поставила'::text,'поставила'::text,'ставила'::text,'Коли ти вийшла на балкон, ти вже поставила свій підпис під угодою, чесно.'::text),
(387240,43027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegaste al balcón, ya ... tu firma en el trato, la verdad.'::text,'habías puesto'::text,'has puesto'::text,'pusiste'::text,'Cuando llegaste al balcón, ya habías puesto tu firma en el trato, la verdad.'::text),
(387239,43027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand tu es arrivée au balcon, tu ... ta signature sur l''accord, franchement.'::text,'avais déjà apposé'::text,'as apposé'::text,'as apposé'::text,'Quand tu es arrivée au balcon, tu avais déjà apposé ta signature sur l''accord, franchement.'::text),
(387242,43027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balkona vardığında, anlaşmaya imzanı çoktan ..., açıkçası.'::text,'atmıştın'::text,'attın'::text,'attın'::text,'Balkona vardığında, anlaşmaya imzanı çoktan atmıştın, açıkçası.'::text),
(387243,43027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire kiértél az erkélyre, már ... az aláírásodat az üzletre, őszintén.'::text,'rátetted'::text,'rátetted'::text,'rátetted'::text,'Mire kiértél az erkélyre, már rátetted az aláírásodat az üzletre, őszintén.'::text),
(387246,43028,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du noch mal so unterschreibst, ... deine Unterschrift jeden, ganz ehrlich.'::text,'beeindruckt'::text,'würde beeindrucken'::text,'beeindruckte'::text,'Wenn du noch mal so unterschreibst, beeindruckt deine Unterschrift jeden, ganz ehrlich.'::text),
(387250,43028,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти ще раз так підпишешся, твій підпис ... всіх, чесно.'::text,'вразить'::text,'вразив би'::text,'вразив'::text,'Якщо ти ще раз так підпишешся, твій підпис вразить всіх, чесно.'::text),
(387249,43028,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si vuelves a firmar así, tu firma ... a todo el mundo, no voy a mentir.'::text,'impresionará'::text,'impresionaría'::text,'impresionó'::text,'Si vuelves a firmar así, tu firma impresionará a todo el mundo, no voy a mentir.'::text),
(387248,43028,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu signes encore comme ça, ta signature ... tout le monde, sans mentir.'::text,'impressionnera'::text,'impressionnerait'::text,'a impressionné'::text,'Si tu signes encore comme ça, ta signature impressionnera tout le monde, sans mentir.'::text),
(387251,43028,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha böyle imza atarsan, imzan herkesi ..., yalan yok.'::text,'etkileyecek'::text,'etkilerdi'::text,'etkiledi'::text,'Bir daha böyle imza atarsan, imzan herkesi etkileyecek, yalan yok.'::text),
(387252,43028,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egyszer így írsz alá, az aláírásod mindenkit ..., nem hazudok.'::text,'lenyűgöz'::text,'lenyűgözne'::text,'lenyűgözött'::text,'Ha még egyszer így írsz alá, az aláírásod mindenkit lenyűgöz, nem hazudok.'::text),
(387255,43029,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So eine makellose Unterschrift: Wenn sie noch größer wäre, ... die Mappe eine zweite Seite.'::text,'bräuchte'::text,'wird brauchen'::text,'braucht'::text,'So eine makellose Unterschrift: Wenn sie noch größer wäre, bräuchte die Mappe eine zweite Seite.'::text),
(387259,43029,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Такий бездоганний підпис: якби він був ще більшим, папці ... друга сторінка.'::text,'знадобилася б'::text,'знадобиться'::text,'потрібна'::text,'Такий бездоганний підпис: якби він був ще більшим, папці знадобилася б друга сторінка.'::text),
(387258,43029,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué firma tan impecable: si fuera más grande, la carpeta ... una segunda página.'::text,'necesitaría'::text,'necesitará'::text,'necesita'::text,'Qué firma tan impecable: si fuera más grande, la carpeta necesitaría una segunda página.'::text),
(387257,43029,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une signature si parfaite : si elle était encore plus grande, le dossier ... d''une deuxième page.'::text,'aurait besoin'::text,'aura besoin'::text,'a besoin'::text,'Une signature si parfaite : si elle était encore plus grande, le dossier aurait besoin d''une deuxième page.'::text),
(387260,43029,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kusursuz bir imza: biraz daha büyük olsaydı, dosyanın ikinci bir sayfaya ihtiyacı ...'::text,'olurdu'::text,'olacak'::text,'var'::text,'Ne kusursuz bir imza: biraz daha büyük olsaydı, dosyanın ikinci bir sayfaya ihtiyacı olurdu.'::text),
(387261,43029,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda hibátlan aláírás: ha még nagyobb lenne, a mappának ... egy második oldal.'::text,'kellene'::text,'kell majd'::text,'kell'::text,'Micsoda hibátlan aláírás: ha még nagyobb lenne, a mappának kellene egy második oldal.'::text),
(387264,43030,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Unterschrift ... vor zwanzig Kameras geleistet, ein sehr privater Moment, offensichtlich.'::text,'wurde'::text,'wird'::text,'leistete'::text,'Ihre Unterschrift wurde vor zwanzig Kameras geleistet, ein sehr privater Moment, offensichtlich.'::text),
(387268,43030,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її підпис ... перед двадцятьма камерами, дуже приватний момент, звісно.'::text,'був поставлений'::text,'ставиться'::text,'поставила'::text,'Її підпис був поставлений перед двадцятьма камерами, дуже приватний момент, звісно.'::text),
(387267,43030,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su firma ... delante de veinte cámaras, un momento muy íntimo, obviamente.'::text,'fue escrita'::text,'es escrita'::text,'escribió'::text,'Su firma fue escrita delante de veinte cámaras, un momento muy íntimo, obviamente.'::text),
(387266,43030,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa signature ... devant vingt caméras, un moment très intime, évidemment.'::text,'a été apposée'::text,'est apposée'::text,'a apposé'::text,'Sa signature a été apposée devant vingt caméras, un moment très intime, évidemment.'::text),
(387269,43030,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmzası yirmi kameranın önünde ..., çok özel bir an, belli ki.'::text,'atıldı'::text,'atılıyor'::text,'attı'::text,'İmzası yirmi kameranın önünde atıldı, çok özel bir an, belli ki.'::text),
(387270,43030,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az aláírása húsz kamera előtt ..., nagyon privát pillanat, nyilván.'::text,'készült'::text,'készül'::text,'írta'::text,'Az aláírása húsz kamera előtt készült, nagyon privát pillanat, nyilván.'::text),
(387273,43031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Politikerin ... den Kameras mit einem stolzen Lächeln ihre frische Unterschrift.'::text,'zeigte'::text,'wurde gezeigt'::text,'zeigend'::text,'Die Politikerin zeigte den Kameras mit einem stolzen Lächeln ihre frische Unterschrift.'::text),
(387277,43031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Політикиня ... камерам свій свіжий підпис із гордою усмішкою.'::text,'показала'::text,'була показана'::text,'показуючи'::text,'Політикиня показала камерам свій свіжий підпис із гордою усмішкою.'::text),
(387276,43031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La política ... su firma recién hecha a las cámaras con una sonrisa orgullosa.'::text,'mostró'::text,'fue mostrada'::text,'mostrando'::text,'La política mostró su firma recién hecha a las cámaras con una sonrisa orgullosa.'::text),
(387275,43031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La politicienne ... sa signature toute fraîche aux caméras avec un sourire fier.'::text,'a montré'::text,'a été montrée'::text,'montrant'::text,'La politicienne a montré sa signature toute fraîche aux caméras avec un sourire fier.'::text),
(387278,43031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Politikacı taze imzasını gururlu bir gülümsemeyle kameralara ...'::text,'gösterdi'::text,'gösterildi'::text,'göstererek'::text,'Politikacı taze imzasını gururlu bir gülümsemeyle kameralara gösterdi.'::text),
(387279,43031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A politikus büszke mosollyal ... a friss aláírását a kameráknak.'::text,'mutatta meg'::text,'meg lett mutatva'::text,'mutatva'::text,'A politikus büszke mosollyal mutatta meg a friss aláírását a kameráknak.'::text),
(387282,43032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Unterschrift ... echt sein, sie hat sie buchstäblich vor der Kamera geleistet, ohne Witz.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Digga, die Unterschrift muss echt sein, sie hat sie buchstäblich vor der Kamera geleistet, ohne Witz.'::text),
(387286,43032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей підпис ... бути справжнім, вона буквально підписала на камеру, без жартів.'::text,'має'::text,'може'::text,'не може'::text,'Бро, цей підпис має бути справжнім, вона буквально підписала на камеру, без жартів.'::text),
(387285,43032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esa firma ... ser real, literalmente firmó delante de la cámara, en serio.'::text,'tiene que'::text,'podría'::text,'no puede'::text,'Bro, esa firma tiene que ser real, literalmente firmó delante de la cámara, en serio.'::text),
(387284,43032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cette signature ... être vraie, elle l''a littéralement signée devant la caméra, sans mentir.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Frère, cette signature doit être vraie, elle l''a littéralement signée devant la caméra, sans mentir.'::text),
(387287,43032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o imza gerçek ..., resmen kamera önünde attı, yalan yok.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Kanka, o imza gerçek olmalı, resmen kamera önünde attı, yalan yok.'::text),
(387288,43032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az az aláírás ... valódi, szó szerint kamera előtt írta alá, nem kamu.'::text,'biztosan'::text,'lehet, hogy'::text,'nem lehet'::text,'Tesó, az az aláírás biztosan valódi, szó szerint kamera előtt írta alá, nem kamu.'::text),
(387291,43033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vertrag, ... ihre Unterschrift trägt, ist 2 Millionen Euro wert.'::text,'der'::text,'wer'::text,'dessen'::text,'Der Vertrag, der ihre Unterschrift trägt, ist 2 Millionen Euro wert.'::text),
(387295,43033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Контракт, ... має її підпис, вартує 2 мільйони євро.'::text,'який'::text,'хто'::text,'чий'::text,'Контракт, який має її підпис, вартує 2 мільйони євро.'::text),
(387294,43033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El contrato ... lleva su firma vale 2 millones de euros.'::text,'que'::text,'quien'::text,'cuyo'::text,'El contrato que lleva su firma vale 2 millones de euros.'::text),
(387293,43033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le contrat ... porte sa signature vaut 2 millions d''euros.'::text,'qui'::text,'qui'::text,'dont'::text,'Le contrat qui porte sa signature vaut 2 millions d''euros.'::text),
(387296,43033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun imzasını taşıyan ... sözleşme 2 milyon euro değerinde.'::text,''::text,NULL::text,NULL::text,'Onun imzasını taşıyan sözleşme 2 milyon euro değerinde.'::text),
(387297,43033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerződés, ... az ő aláírását viseli, 2 millió eurót ér.'::text,'amely'::text,'aki'::text,'amelynek'::text,'A szerződés, amely az ő aláírását viseli, 2 millió eurót ér.'::text),
(329070,36564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... Angst vor Leitern, also ist das Wandbild eine echte Leistung.'::text,'hatte früher'::text,'hatte früher'::text,'war gewohnt, zu haben'::text,'Sie hatte früher Angst vor Leitern, also ist das Wandbild eine echte Leistung.'::text),
(329074,36564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... драбин, тож цей мурал — справжнє досягнення.'::text,'колись боялася'::text,'колись боялася'::text,'звикла боятися'::text,'Вона колись боялася драбин, тож цей мурал — справжнє досягнення.'::text),
(329073,36564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... tener miedo a las escaleras, así que el mural es todo un logro.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Ella solía tener miedo a las escaleras, así que el mural es todo un logro.'::text),
(329072,36564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... peur des échelles avant, donc la fresque est un vrai exploit.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Elle avait peur des échelles avant, donc la fresque est un vrai exploit.'::text),
(329075,36564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden merdivenlerden ..., bu yüzden duvar resmi gerçek bir başarı.'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Eskiden merdivenlerden korkardı, bu yüzden duvar resmi gerçek bir başarı.'::text),
(329076,36564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a létráktól, így a falfestmény igazi teljesítmény.'::text,'félt'::text,'félt'::text,'hozzá volt szokva, hogy féljen'::text,'Régen félt a létráktól, így a falfestmény igazi teljesítmény.'::text),
(329079,36565,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigerte sich absolut, ..., bevor die letzte Sonne fertig war. Was für eine Leistung!'::text,'runterzuklettern'::text,'runterklettern'::text,'runterklettern'::text,'Sie weigerte sich absolut, runterzuklettern, bevor die letzte Sonne fertig war. Was für eine Leistung!'::text),
(329083,36565,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона категорично відмовилася ... вниз, поки не було готове останнє сонце. Яке досягнення!'::text,'злізти'::text,'злізти'::text,'злізти'::text,'Вона категорично відмовилася злізти вниз, поки не було готове останнє сонце. Яке досягнення!'::text),
(329082,36565,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se negó rotundamente a ... antes de terminar el último sol. ¡Qué logro!'::text,'bajar'::text,'bajar'::text,'bajar'::text,'Se negó rotundamente a bajar antes de terminar el último sol. ¡Qué logro!'::text),
(329081,36565,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a catégoriquement refusé de ... avant que le dernier soleil soit fini. Quel exploit !'::text,'descendre'::text,'descendre'::text,'descendre'::text,'Elle a catégoriquement refusé de descendre avant que le dernier soleil soit fini. Quel exploit !'::text),
(329084,36565,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son güneş bitmeden aşağı ... kesinlikle reddetti. Ne başarı ama!'::text,'inmeyi'::text,'inmeyi'::text,'inmeyi'::text,'Son güneş bitmeden aşağı inmeyi kesinlikle reddetti. Ne başarı ama!'::text),
(329085,36565,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abszolút nem volt hajlandó ... az utolsó nap elkészülte előtt. Micsoda teljesítmény!'::text,'lemászni'::text,'lemászni'::text,'lemászni'::text,'Abszolút nem volt hajlandó lemászni az utolsó nap elkészülte előtt. Micsoda teljesítmény!'::text),
(329088,36566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ist das Wandbild ihre größte Leistung, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Mädel, angeblich ist das Wandbild ihre größte Leistung, oder?'::text),
(329092,36566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, мурал — її найбільше досягнення, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Подруго, кажуть, мурал — її найбільше досягнення, так?'::text),
(329091,36566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el mural es su mayor logro, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Amiga, al parecer el mural es su mayor logro, ¿verdad?'::text),
(329090,36566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la fresque est son plus grand exploit, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Meuf, apparemment la fresque est son plus grand exploit, n''est-ce pas ?'::text),
(329093,36566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, galiba duvar resmi onun en büyük başarısı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kızım, galiba duvar resmi onun en büyük başarısı, değil mi?'::text),
(329094,36566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a falfestmény a legnagyobb teljesítménye, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Csajszi, állítólag a falfestmény a legnagyobb teljesítménye, ugye?'::text),
(329097,36567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat gesagt, sie sei stolz auf die Leistung, und ihre ganze Straße ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Rate mal, sie hat gesagt, sie sei stolz auf die Leistung, und ihre ganze Straße auch.'::text),
(329101,36567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала, що пишається цим досягненням, і вся її вулиця ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Уяви, вона сказала, що пишається цим досягненням, і вся її вулиця теж.'::text),
(329100,36567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, dijo que estaba orgullosa del logro, y toda su calle ...'::text,'también'::text,'también'::text,'tampoco'::text,'Adivina qué, dijo que estaba orgullosa del logro, y toda su calle también.'::text),
(329099,36567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit qu''elle était fière de cet exploit, et toute sa rue ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Devine quoi, elle a dit qu''elle était fière de cet exploit, et toute sa rue aussi.'::text),
(329102,36567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et, bu başarıyla gurur duyduğunu söyledi, bütün sokağı da ...'::text,'öyleydi'::text,'öyleydi'::text,'değildi'::text,'Tahmin et, bu başarıyla gurur duyduğunu söyledi, bütün sokağı da öyleydi.'::text),
(329103,36567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, büszke a teljesítményére, és az egész utcája ...'::text,'is'::text,'is'::text,'sem'::text,'Képzeld, azt mondta, büszke a teljesítményére, és az egész utcája is.'::text),
(329115,36569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... die halbe Straße ein Foto von ihrer Leistung gepostet haben, Digga, ohne Witz.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis heute Abend wird die halbe Straße ein Foto von ihrer Leistung gepostet haben, Digga, ohne Witz.'::text),
(329119,36569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора пів вулиці ... фотку її досягнення, бро, без жартів.'::text,'вже запостить'::text,'запостить'::text,'поститиме'::text,'До вечора пів вулиці вже запостить фотку її досягнення, бро, без жартів.'::text),
(329118,36569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche media calle ... una foto de su logro, bro, en serio.'::text,'habrá subido'::text,'subirá'::text,'estará subiendo'::text,'Para esta noche media calle habrá subido una foto de su logro, bro, en serio.'::text),
(329117,36569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, la moitié de la rue ... une photo de son exploit, frère, sans mentir.'::text,'aura posté'::text,'postera'::text,'sera en train de poster'::text,'D''ici ce soir, la moitié de la rue aura posté une photo de son exploit, frère, sans mentir.'::text),
(329120,36569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar sokağın yarısı onun başarısının fotoğrafını ..., kanka, yalan yok.'::text,'paylaşmış olacak'::text,'paylaşacak'::text,'paylaşıyor olacak'::text,'Bu akşama kadar sokağın yarısı onun başarısının fotoğrafını paylaşmış olacak, kanka, yalan yok.'::text),
(329121,36569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére az utca fele ... egy képet a teljesítményéről, tesó, nem kamu.'::text,'már posztolt'::text,'posztolni fog'::text,'épp posztolni fog'::text,'Estére az utca fele már posztolt egy képet a teljesítményéről, tesó, nem kamu.'::text),
(329124,36570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ende des Jahres ... sie seit 10 Jahren Wandbilder, eine Leistung für ihren Jahresbericht.'::text,'malt'::text,'malt'::text,'wird malen'::text,'Ende des Jahres malt sie seit 10 Jahren Wandbilder, eine Leistung für ihren Jahresbericht.'::text),
(329128,36570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця року вона ... мурали вже 10 років, досягнення для її річного звіту.'::text,'малюватиме'::text,'малюватиме'::text,'намалює'::text,'До кінця року вона малюватиме мурали вже 10 років, досягнення для її річного звіту.'::text),
(329127,36570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A finales de año, ... murales durante 10 años, un logro para su informe anual.'::text,'habrá estado pintando'::text,'estará pintando'::text,'pintará'::text,'A finales de año, habrá estado pintando murales durante 10 años, un logro para su informe anual.'::text),
(329126,36570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de l''année, elle ... des fresques depuis 10 ans, un accomplissement pour son rapport annuel.'::text,'peindra'::text,'sera en train de peindre'::text,'peindra'::text,'D''ici la fin de l''année, elle peindra des fresques depuis 10 ans, un accomplissement pour son rapport annuel.'::text),
(329129,36570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıl sonuna kadar 10 yıldır duvar resmi ..., yıllık raporu için bir başarı.'::text,'yapıyor olacak'::text,'yapıyor olacak'::text,'yapacak'::text,'Yıl sonuna kadar 10 yıldır duvar resmi yapıyor olacak, yıllık raporu için bir başarı.'::text),
(329130,36570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az év végére 10 éve ... falfestményeket, ez teljesítmény az éves jelentésébe.'::text,'fest majd'::text,'fest majd'::text,'festeni fog'::text,'Az év végére 10 éve fest majd falfestményeket, ez teljesítmény az éves jelentésébe.'::text),
(329133,36571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie von der Leiter gefallen wäre, ... sie das Wandbild, ihre größte Leistung, nicht fertig gemacht.'::text,'hätte'::text,'wird'::text,'machte'::text,'Wenn sie von der Leiter gefallen wäre, hätte sie das Wandbild, ihre größte Leistung, nicht fertig gemacht.'::text),
(329137,36571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона впала з драбини, вона ... мурал, своє найбільше досягнення.'::text,'не закінчила б'::text,'не закінчить'::text,'не закінчила'::text,'Якби вона впала з драбини, вона не закінчила б мурал, своє найбільше досягнення.'::text),
(329136,36571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se hubiera caído de la escalera, ... el mural, su mayor logro.'::text,'no habría terminado'::text,'no terminará'::text,'no terminó'::text,'Si se hubiera caído de la escalera, no habría terminado el mural, su mayor logro.'::text),
(329135,36571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle était tombée de l''échelle, elle ... la fresque, son plus grand exploit.'::text,'n''aurait pas terminé'::text,'ne terminera pas'::text,'n''a pas terminé'::text,'Si elle était tombée de l''échelle, elle n''aurait pas terminé la fresque, son plus grand exploit.'::text),
(329138,36571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Merdivenden düşseydi, en büyük başarısı olan duvar resmini ...'::text,'bitiremezdi'::text,'bitiremeyecek'::text,'bitirmedi'::text,'Merdivenden düşseydi, en büyük başarısı olan duvar resmini bitiremezdi.'::text),
(329139,36571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha leesett volna a létráról, ... a falfestményt, a legnagyobb teljesítményét.'::text,'nem fejezte volna be'::text,'nem fejezi be'::text,'nem fejezte be'::text,'Ha leesett volna a létráról, nem fejezte volna be a falfestményt, a legnagyobb teljesítményét.'::text),
(329142,36572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte das Subjekt die letzten Striche aufgegeben, ... das Wandbild jetzt keine bemerkenswerte Leistung.'::text,'wäre'::text,'wäre gewesen'::text,'wird sein'::text,'Hätte das Subjekt die letzten Striche aufgegeben, wäre das Wandbild jetzt keine bemerkenswerte Leistung.'::text),
(329146,36572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби суб''єкт відмовився від останніх мазків, мурал зараз ... помітним досягненням.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби суб''єкт відмовився від останніх мазків, мурал зараз не був би помітним досягненням.'::text),
(329145,36572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el sujeto hubiera abandonado las últimas pinceladas, el mural ... un logro notable ahora.'::text,'no sería'::text,'no habría sido'::text,'no será'::text,'Si el sujeto hubiera abandonado las últimas pinceladas, el mural no sería un logro notable ahora.'::text),
(329144,36572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sujet avait abandonné les derniers coups de pinceau, la fresque ... un accomplissement notable maintenant.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Si le sujet avait abandonné les derniers coups de pinceau, la fresque ne serait pas un accomplissement notable maintenant.'::text),
(329147,36572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek son fırça darbelerinden vazgeçseydi, duvar resmi şimdi kayda değer bir başarı ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Denek son fırça darbelerinden vazgeçseydi, duvar resmi şimdi kayda değer bir başarı olmazdı.'::text),
(329148,36572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az alany feladta volna az utolsó ecsetvonásokat, a falfestmény most nem ... figyelemre méltó teljesítmény.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha az alany feladta volna az utolsó ecsetvonásokat, a falfestmény most nem lenne figyelemre méltó teljesítmény.'::text),
(329151,36573,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wandbild soll in nur drei Tagen ..., eine echte Leistung.'::text,'gemalt worden sein'::text,'gemalt werden'::text,'malen'::text,'Das Wandbild soll in nur drei Tagen gemalt worden sein, eine echte Leistung.'::text),
(329155,36573,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що мурал ... лише за три дні, справжнє досягнення.'::text,'був намальований'::text,'малюється'::text,'намалювати'::text,'Вважається, що мурал був намальований лише за три дні, справжнє досягнення.'::text),
(329154,36573,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el mural ... en solo tres días, todo un logro.'::text,'fue pintado'::text,'es pintado'::text,'pintar'::text,'Se cree que el mural fue pintado en solo tres días, todo un logro.'::text),
(329153,36573,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la fresque ... en seulement trois jours, un vrai exploit.'::text,'a été peinte'::text,'est peinte'::text,'peindre'::text,'On pense que la fresque a été peinte en seulement trois jours, un vrai exploit.'::text),
(329156,36573,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvar resminin sadece üç günde ... düşünülüyor, gerçek bir başarı.'::text,'yapıldığı'::text,'yapılacağı'::text,'yapmak'::text,'Duvar resminin sadece üç günde yapıldığı düşünülüyor, gerçek bir başarı.'::text),
(329157,36573,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy a falfestmény mindössze három nap alatt ..., igazi teljesítmény.'::text,'készült el'::text,'készül'::text,'festeni'::text,'Úgy tartják, hogy a falfestmény mindössze három nap alatt készült el, igazi teljesítmény.'::text),
(381999,42445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er mit dem Ring auf der Brücke ..., wurde der Abend leicht romantisch.'::text,'kniete'::text,'kniete'::text,'hat gekniet'::text,'Während er mit dem Ring auf der Brücke kniete, wurde der Abend leicht romantisch.'::text),
(382003,42445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... на мосту з каблучкою, вечір став трохи романтичним.'::text,'стояв на колінах'::text,'став на коліна'::text,'став на коліна'::text,'Поки він стояв на колінах на мосту з каблучкою, вечір став трохи романтичним.'::text),
(382002,42445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... en el puente con el anillo, la noche se puso ligeramente romántica.'::text,'estaba arrodillado'::text,'se arrodilló'::text,'se ha arrodillado'::text,'Mientras estaba arrodillado en el puente con el anillo, la noche se puso ligeramente romántica.'::text),
(382001,42445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... sur le pont avec la bague, la soirée est devenue légèrement romantique.'::text,'était à genoux'::text,'s''est agenouillé'::text,'s''est agenouillé'::text,'Pendant qu''il était à genoux sur le pont avec la bague, la soirée est devenue légèrement romantique.'::text),
(382004,42445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yüzükle köprüde diz ..., akşam hafiften romantikleşti.'::text,'çökmüşken'::text,'çöktüğünde'::text,'çökmüş'::text,'O yüzükle köprüde diz çökmüşken, akşam hafiften romantikleşti.'::text),
(382005,42445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg ... a hídon a gyűrűvel, az este kissé romantikus lett.'::text,'térdelt'::text,'letérdelt'::text,'letérdelt'::text,'Amíg térdelt a hídon a gyűrűvel, az este kissé romantikus lett.'::text),
(382008,42446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er ... diesen romantischen Antrag schon seit Monaten, ohne Witz.'::text,'plant'::text,'plant'::text,'plant'::text,'Digga, er plant diesen romantischen Antrag schon seit Monaten, ohne Witz.'::text),
(382012,42446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... цю романтичну пропозицію вже кілька місяців, без жартів.'::text,'планує'::text,'планує'::text,'планує'::text,'Бро, він планує цю романтичну пропозицію вже кілька місяців, без жартів.'::text),
(382011,42446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... esta propuesta romántica durante meses, en serio.'::text,'ha estado planeando'::text,'está planeando'::text,'planea'::text,'Bro, ha estado planeando esta propuesta romántica durante meses, en serio.'::text),
(382010,42446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... cette demande romantique depuis des mois, sans mentir.'::text,'prépare'::text,'prépare'::text,'prépare'::text,'Frère, il prépare cette demande romantique depuis des mois, sans mentir.'::text),
(382013,42446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, aylardır bu romantik evlilik teklifini ..., yalan yok.'::text,'planlıyor'::text,'planlıyor'::text,'planlar'::text,'Kanka, aylardır bu romantik evlilik teklifini planlıyor, yalan yok.'::text),
(382014,42446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, hónapok óta ... ezt a romantikus lánykérést, nem kamu.'::text,'tervezi'::text,'tervezi'::text,'tervezi'::text,'Tesó, hónapok óta tervezi ezt a romantikus lánykérést, nem kamu.'::text),
(382017,42447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er ... auf ein Knie und sie hat Ja gesagt, irgendwie romantisch, echt.'::text,'ging'::text,'ging gerade'::text,'ist gegangen'::text,'Digga, er ging auf ein Knie und sie hat Ja gesagt, irgendwie romantisch, echt.'::text),
(382021,42447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... на одне коліно, і вона сказала так, типу романтично, реально.'::text,'став'::text,'ставав'::text,'став'::text,'Бро, він став на одне коліно, і вона сказала так, типу романтично, реально.'::text),
(382020,42447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, se ... de rodillas y ella dijo que sí, medio romántico, en serio.'::text,'puso'::text,'estaba poniendo'::text,'ha puesto'::text,'Bro, se puso de rodillas y ella dijo que sí, medio romántico, en serio.'::text),
(382019,42447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... un genou à terre et elle a dit oui, un peu romantique, sérieux.'::text,'a mis'::text,'mettait'::text,'a mis'::text,'Frère, il a mis un genou à terre et elle a dit oui, un peu romantique, sérieux.'::text),
(382022,42447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tek dizinin üstüne ... ve kız evet dedi, biraz romantik, cidden.'::text,'çöktü'::text,'çöküyordu'::text,'çöktü'::text,'Kanka, tek dizinin üstüne çöktü ve kız evet dedi, biraz romantik, cidden.'::text),
(382023,42447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... fél térdre, és a lány igent mondott, eléggé romantikus, komolyan.'::text,'ereszkedett'::text,'épp ereszkedett'::text,'ereszkedett'::text,'Tesó, ereszkedett fél térdre, és a lány igent mondott, eléggé romantikus, komolyan.'::text),
(382026,42448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Quartal ... die Brücke 12 romantische Heiratsanträge erlebt, ein neues Ziel.'::text,'hat'::text,'hat'::text,'erlebt'::text,'In diesem Quartal hat die Brücke 12 romantische Heiratsanträge erlebt, ein neues Ziel.'::text),
(382030,42448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього кварталу на мосту ... 12 романтичних освідчень, нова ціль.'::text,'відбулося'::text,'відбувалося'::text,'відбувається'::text,'Цього кварталу на мосту відбулося 12 романтичних освідчень, нова ціль.'::text),
(382029,42448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este trimestre, el puente ... 12 pedidas románticas, un nuevo objetivo.'::text,'ha acogido'::text,'ha estado acogiendo'::text,'está acogiendo'::text,'Este trimestre, el puente ha acogido 12 pedidas románticas, un nuevo objetivo.'::text),
(382028,42448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce trimestre, le pont ... 12 demandes romantiques, un nouvel objectif.'::text,'a accueilli'::text,'a accueilli'::text,'accueille'::text,'Ce trimestre, le pont a accueilli 12 demandes romantiques, un nouvel objectif.'::text),
(382031,42448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu çeyrekte köprü 12 romantik evlilik teklifine ..., yeni bir hedef.'::text,'ev sahipliği yaptı'::text,'ev sahipliği yapıyor'::text,'ev sahipliği yapıyor'::text,'Bu çeyrekte köprü 12 romantik evlilik teklifine ev sahipliği yaptı, yeni bir hedef.'::text),
(382032,42448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a negyedévben a híd 12 romantikus lánykérésnek ... otthont, új cél.'::text,'adott'::text,'adott'::text,'ad'::text,'Ebben a negyedévben a híd 12 romantikus lánykérésnek adott otthont, új cél.'::text),
(382035,42449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie Ja sagte, ... er eine romantische Frage gestellt, also hatte sie eine Frage zu beantworten.'::text,'hatte'::text,'hat'::text,'stellt'::text,'Als sie Ja sagte, hatte er eine romantische Frage gestellt, also hatte sie eine Frage zu beantworten.'::text),
(382039,42449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона сказала так, він уже ... романтичне питання, тож їй треба було відповісти на питання.'::text,'поставив'::text,'поставив'::text,'ставить'::text,'Коли вона сказала так, він уже поставив романтичне питання, тож їй треба було відповісти на питання.'::text),
(382038,42449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando ella dijo que sí, él ya ... una pregunta romántica, así que tenía una pregunta que responder.'::text,'había hecho'::text,'ha hecho'::text,'hace'::text,'Cuando ella dijo que sí, él ya había hecho una pregunta romántica, así que tenía una pregunta que responder.'::text),
(382037,42449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a dit oui, il ... une question romantique, donc elle avait une question à laquelle répondre.'::text,'avait posé'::text,'a posé'::text,'pose'::text,'Quand elle a dit oui, il avait posé une question romantique, donc elle avait une question à laquelle répondre.'::text),
(382040,42449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O evet dediğinde, adam romantik bir soru çoktan ..., yani cevaplaması gereken bir soru vardı.'::text,'sormuştu'::text,'sordu'::text,'soruyor'::text,'O evet dediğinde, adam romantik bir soru çoktan sormuştu, yani cevaplaması gereken bir soru vardı.'::text),
(382041,42449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire igent mondott, a férfi már ... egy romantikus kérdést, szóval volt egy kérdés, amire válaszolnia kellett.'::text,'feltett'::text,'feltett'::text,'feltesz'::text,'Mire igent mondott, a férfi már feltett egy romantikus kérdést, szóval volt egy kérdés, amire válaszolnia kellett.'::text),
(382053,42451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich schwöre, dieser romantische Moment ... für immer in meiner Erinnerung!'::text,'bleibt'::text,'wird bleiben'::text,'bleibt gerade'::text,'Ich schwöre, dieser romantische Moment bleibt für immer in meiner Erinnerung!'::text),
(382057,42451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клянуся, ця романтична мить ... в моїй пам''яті назавжди!'::text,'залишиться'::text,'залишатиметься'::text,'залишається'::text,'Клянуся, ця романтична мить залишиться в моїй пам''яті назавжди!'::text),
(382056,42451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Te juro que este momento romántico ... para siempre en mi memoria!'::text,'se quedará'::text,'se estará quedando'::text,'se queda'::text,'¡Te juro que este momento romántico se quedará para siempre en mi memoria!'::text),
(382055,42451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je jure que ce moment romantique ... gravé dans ma mémoire pour toujours !'::text,'restera'::text,'restera'::text,'reste'::text,'Je jure que ce moment romantique restera gravé dans ma mémoire pour toujours !'::text),
(382058,42451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim, bu romantik an sonsuza dek hafızamda ...!'::text,'kalacak'::text,'kalıyor olacak'::text,'kalıyor'::text,'Yemin ederim, bu romantik an sonsuza dek hafızamda kalacak!'::text),
(382059,42451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esküszöm, ez a romantikus pillanat örökre ... az emlékezetemben!'::text,'megmarad'::text,'meg fog maradni'::text,'megmarad'::text,'Esküszöm, ez a romantikus pillanat örökre megmarad az emlékezetemben!'::text),
(382062,42452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... früher alles Romantische, und jetzt kniet er! Was für eine Katastrophe!'::text,'hasste'::text,'hasste'::text,'war gewohnt zu hassen'::text,'Er hasste früher alles Romantische, und jetzt kniet er! Was für eine Katastrophe!'::text),
(382066,42452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... все романтичне, а тепер стоїть на одному коліні! Яка катастрофа!'::text,'колись ненавидів'::text,'ненавидів'::text,'звик ненавидіти'::text,'Він колись ненавидів все романтичне, а тепер стоїть на одному коліні! Яка катастрофа!'::text),
(382065,42452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... odiar todo lo romántico, y ahora está de rodillas! ¡Qué desastre!'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'¡Él solía odiar todo lo romántico, y ahora está de rodillas! ¡Qué desastre!'::text),
(382064,42452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... tout ce qui est romantique avant, et maintenant il est à genoux ! Quelle catastrophe !'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'Il détestait tout ce qui est romantique avant, et maintenant il est à genoux ! Quelle catastrophe !'::text),
(382067,42452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden romantik olan her şeyden ..., şimdi ise tek dizinin üstünde! Ne felaket!'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Eskiden romantik olan her şeyden nefret ederdi, şimdi ise tek dizinin üstünde! Ne felaket!'::text),
(382068,42452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... mindent, ami romantikus, most meg fél térden áll! Micsoda katasztrófa!'::text,'utált'::text,'utált'::text,'hozzá volt szokva, hogy utáljon'::text,'Régen utált mindent, ami romantikus, most meg fél térden áll! Micsoda katasztrófa!'::text),
(382071,42453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschloss, die Frage auf einer romantischen Brücke bei Sonnenuntergang ...'::text,'zu stellen'::text,'stellen'::text,'stellen'::text,'Er beschloss, die Frage auf einer romantischen Brücke bei Sonnenuntergang zu stellen.'::text),
(382075,42453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішив ... це питання на романтичному мосту під час заходу сонця.'::text,'поставити'::text,'ставлення'::text,'поставити'::text,'Він вирішив поставити це питання на романтичному мосту під час заходу сонця.'::text),
(382074,42453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decidió ... la pregunta en un puente romántico al atardecer.'::text,'hacer'::text,'hacer'::text,'hacer'::text,'Decidió hacer la pregunta en un puente romántico al atardecer.'::text),
(382073,42453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a décidé de ... la question sur un pont romantique au coucher du soleil.'::text,'poser'::text,'poser'::text,'poser'::text,'Il a décidé de poser la question sur un pont romantique au coucher du soleil.'::text),
(382076,42453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soruyu gün batımında romantik bir köprüde ... karar verdi.'::text,'sormaya'::text,'sormaya'::text,'sormaya'::text,'Soruyu gün batımında romantik bir köprüde sormaya karar verdi.'::text),
(382077,42453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy döntött, hogy naplementekor egy romantikus hídon ... fel a kérdést.'::text,'teszi'::text,'teszi'::text,'teszi'::text,'Úgy döntött, hogy naplementekor egy romantikus hídon teszi fel a kérdést.'::text),
(382089,42455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine Stunde lang nach einem romantischen Ort gesucht, bevor er schließlich auf der Brücke kniete.'::text,'hatten'::text,'suchten'::text,'suchten gerade'::text,'Sie hatten eine Stunde lang nach einem romantischen Ort gesucht, bevor er schließlich auf der Brücke kniete.'::text),
(382093,42455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... романтичне місце цілу годину, перш ніж він нарешті став на коліно на мосту.'::text,'шукали'::text,'шукали'::text,'шукали'::text,'Вони шукали романтичне місце цілу годину, перш ніж він нарешті став на коліно на мосту.'::text),
(382092,42455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un lugar romántico durante una hora antes de que él por fin se arrodillara en el puente.'::text,'Habían estado buscando'::text,'Buscaron'::text,'Estaban buscando'::text,'Habían estado buscando un lugar romántico durante una hora antes de que él por fin se arrodillara en el puente.'::text),
(382091,42455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... un endroit romantique depuis une heure quand il s''est enfin agenouillé sur le pont.'::text,'cherchaient'::text,'ont cherché'::text,'cherchaient'::text,'Ils cherchaient un endroit romantique depuis une heure quand il s''est enfin agenouillé sur le pont.'::text),
(382094,42455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam sonunda köprüde diz çökmeden önce bir saat boyunca romantik bir yer ...'::text,'arıyorlardı'::text,'aradılar'::text,'arıyorlardı'::text,'Adam sonunda köprüde diz çökmeden önce bir saat boyunca romantik bir yer arıyorlardı.'::text),
(382095,42455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órán át ... egy romantikus helyet, mielőtt a férfi végül letérdelt a hídon.'::text,'keresgéltek'::text,'kerestek'::text,'keresgéltek'::text,'Egy órán át keresgéltek egy romantikus helyet, mielőtt a férfi végül letérdelt a hídon.'::text),
(363360,40374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Helfer ... seit 3 Jahren freundliche Gesten im Regen, deutlich über dem Ziel.'::text,'vollbringt'::text,'vollbringt'::text,'vollbringt'::text,'Dieser Helfer vollbringt seit 3 Jahren freundliche Gesten im Regen, deutlich über dem Ziel.'::text),
(363364,40374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей помічник ... добрі справи під дощем уже 3 роки, значно вище плану.'::text,'робить'::text,'робить'::text,'робить'::text,'Цей помічник робить добрі справи під дощем уже 3 роки, значно вище плану.'::text),
(363363,40374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este ayudante ... actos de amabilidad bajo la lluvia durante 3 años, muy por encima del objetivo.'::text,'ha estado haciendo'::text,'está haciendo'::text,'hace'::text,'Este ayudante ha estado haciendo actos de amabilidad bajo la lluvia durante 3 años, muy por encima del objetivo.'::text),
(363362,40374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet aidant ... des gestes de gentillesse sous la pluie depuis 3 ans, bien au-dessus de l''objectif.'::text,'fait'::text,'fait'::text,'fait'::text,'Cet aidant fait des gestes de gentillesse sous la pluie depuis 3 ans, bien au-dessus de l''objectif.'::text),
(363365,40374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yardımsever 3 yıldır yağmurda iyilik ..., hedefin çok üzerinde.'::text,'yapıyor'::text,'yapıyor'::text,'yapar'::text,'Bu yardımsever 3 yıldır yağmurda iyilik yapıyor, hedefin çok üzerinde.'::text),
(363366,40374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a segítő 3 éve ... kedves gesztusokat az esőben, jóval a cél felett.'::text,'tesz'::text,'tesz'::text,'tesz'::text,'Ez a segítő 3 éve tesz kedves gesztusokat az esőben, jóval a cél felett.'::text),
(363369,40375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während es ..., wurde der alte Mann nass, weil Regen Wasser ist, also brachte die Freundlichkeit einen Schirm.'::text,'regnete'::text,'regnete'::text,'hat geregnet'::text,'Während es regnete, wurde der alte Mann nass, weil Regen Wasser ist, also brachte die Freundlichkeit einen Schirm.'::text),
(363373,40375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ..., старий чоловік змок, бо дощ — це вода, тож доброта принесла парасольку.'::text,'йшов дощ'::text,'пішов дощ'::text,'пішов дощ'::text,'Поки йшов дощ, старий чоловік змок, бо дощ — це вода, тож доброта принесла парасольку.'::text),
(363372,40375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ..., el anciano se mojó porque la lluvia es agua, así que la amabilidad trajo un paraguas.'::text,'llovía'::text,'llovió'::text,'ha llovido'::text,'Mientras llovía, el anciano se mojó porque la lluvia es agua, así que la amabilidad trajo un paraguas.'::text),
(363371,40375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ..., le vieil homme s''est fait mouiller parce que la pluie, c''est de l''eau, alors la gentillesse a apporté un parapluie.'::text,'pleuvait'::text,'a plu'::text,'a plu'::text,'Pendant qu''il pleuvait, le vieil homme s''est fait mouiller parce que la pluie, c''est de l''eau, alors la gentillesse a apporté un parapluie.'::text),
(363374,40375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur ... yaşlı adam ıslandı, çünkü yağmur sudur, bu yüzden iyilik bir şemsiye getirdi.'::text,'yağarken'::text,'yağdığında'::text,'yağmışken'::text,'Yağmur yağarken yaşlı adam ıslandı, çünkü yağmur sudur, bu yüzden iyilik bir şemsiye getirdi.'::text),
(363375,40375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg ..., az idős férfi elázott, mert az eső víz, úgyhogy a kedvesség hozott egy esernyőt.'::text,'esett'::text,'esett'::text,'esett'::text,'Amíg esett, az idős férfi elázott, mert az eső víz, úgyhogy a kedvesség hozott egy esernyőt.'::text),
(363378,40376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, ... der Helfer diese Woche dreimal Fremden im Regen Freundlichkeit gezeigt.'::text,'hat'::text,'hat'::text,'zeigt'::text,'Wie beobachtet, hat der Helfer diese Woche dreimal Fremden im Regen Freundlichkeit gezeigt.'::text),
(363382,40376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як спостерігалося, помічник цього тижня тричі ... доброту незнайомцям під дощем.'::text,'виявив'::text,'виявляв'::text,'виявляє'::text,'Як спостерігалося, помічник цього тижня тричі виявив доброту незнайомцям під дощем.'::text),
(363381,40376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, el ayudante ... amabilidad a desconocidos bajo la lluvia tres veces esta semana.'::text,'ha mostrado'::text,'ha estado mostrando'::text,'muestra'::text,'Según lo observado, el ayudante ha mostrado amabilidad a desconocidos bajo la lluvia tres veces esta semana.'::text),
(363380,40376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme observé, l''aidant ... de la gentillesse envers des inconnus sous la pluie trois fois cette semaine.'::text,'a montré'::text,'a montré'::text,'montre'::text,'Comme observé, l''aidant a montré de la gentillesse envers des inconnus sous la pluie trois fois cette semaine.'::text),
(363383,40376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere yardımsever bu hafta yağmurda yabancılara üç kez iyilik ...'::text,'gösterdi'::text,'gösteriyor'::text,'gösterir'::text,'Gözlemlendiği üzere yardımsever bu hafta yağmurda yabancılara üç kez iyilik gösterdi.'::text),
(363384,40376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megfigyelések szerint a segítő ezen a héten háromszor ... kedvességet idegenek iránt az esőben.'::text,'mutatott'::text,'mutatott'::text,'mutat'::text,'Megfigyelések szerint a segítő ezen a héten háromszor mutatott kedvességet idegenek iránt az esőben.'::text),
(363387,40377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Freundlichkeit mit einem gelben Schirm ankam, ... der alte Mann schon völlig durchnässt!'::text,'war'::text,'ist'::text,'wird'::text,'Als die Freundlichkeit mit einem gelben Schirm ankam, war der alte Mann schon völlig durchnässt!'::text),
(363391,40377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли доброта прибула з жовтою парасолькою, старий уже повністю ...!'::text,'промок'::text,'промок'::text,'промокає'::text,'Коли доброта прибула з жовтою парасолькою, старий уже повністю промок!'::text),
(363390,40377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuando la amabilidad llegó con un paraguas amarillo, el anciano ya ... completamente empapado!'::text,'se había quedado'::text,'se ha quedado'::text,'se queda'::text,'¡Cuando la amabilidad llegó con un paraguas amarillo, el anciano ya se había quedado completamente empapado!'::text),
(363389,40377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la gentillesse est arrivée avec un parapluie jaune, le vieil homme ... complètement trempé !'::text,'était déjà'::text,'est'::text,'devient'::text,'Quand la gentillesse est arrivée avec un parapluie jaune, le vieil homme était déjà complètement trempé !'::text),
(363392,40377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İyilik sarı bir şemsiyeyle geldiğinde yaşlı adam çoktan sırılsıklam ...!'::text,'olmuştu'::text,'oldu'::text,'oluyor'::text,'İyilik sarı bir şemsiyeyle geldiğinde yaşlı adam çoktan sırılsıklam olmuştu!'::text),
(363393,40377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kedvesség megérkezett egy sárga esernyővel, az idős férfi már teljesen ...!'::text,'elázott'::text,'elázott'::text,'elázik'::text,'Mire a kedvesség megérkezett egy sárga esernyővel, az idős férfi már teljesen elázott!'::text),
(363396,40378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihm niemand Freundlichkeit zeigt, ... seine Baguettes von diesem Regen völlig ruiniert!'::text,'werden'::text,'würden'::text,'wurden'::text,'Wenn ihm niemand Freundlichkeit zeigt, werden seine Baguettes von diesem Regen völlig ruiniert!'::text),
(363400,40378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ніхто не виявить до нього доброти, його багети ... цілком зіпсовані цим дощем!'::text,'будуть'::text,'були б'::text,'були'::text,'Якщо ніхто не виявить до нього доброти, його багети будуть цілком зіпсовані цим дощем!'::text),
(363399,40378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si nadie le muestra amabilidad, sus baguettes ... completamente arruinadas por esta lluvia!'::text,'quedarán'::text,'quedarían'::text,'quedaron'::text,'¡Si nadie le muestra amabilidad, sus baguettes quedarán completamente arruinadas por esta lluvia!'::text),
(363398,40378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si personne ne lui montre de la gentillesse, ses baguettes ... complètement fichues par cette pluie !'::text,'seront'::text,'seraient'::text,'étaient'::text,'Si personne ne lui montre de la gentillesse, ses baguettes seront complètement fichues par cette pluie !'::text),
(363401,40378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse ona iyilik göstermezse, bagetleri bu yağmurda tamamen mahvolmuş ...!'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Kimse ona iyilik göstermezse, bagetleri bu yağmurda tamamen mahvolmuş olacak!'::text),
(363402,40378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha senki sem kedves vele, a bagettjei teljesen tönkre ... ettől az esőtől!'::text,'mennek'::text,'mennének'::text,'mentek'::text,'Ha senki sem kedves vele, a bagettjei teljesen tönkre mennek ettől az esőtől!'::text),
(363405,40379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es in dieser Stadt keine Freundlichkeit mehr gäbe, ... er für immer allein im Regen stehen!'::text,'würde'::text,'wird'::text,'steht'::text,'Wenn es in dieser Stadt keine Freundlichkeit mehr gäbe, würde er für immer allein im Regen stehen!'::text),
(363409,40379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в цьому місті не лишилося доброти, він ... сам під дощем назавжди!'::text,'стояв би'::text,'стоятиме'::text,'стоїть'::text,'Якби в цьому місті не лишилося доброти, він стояв би сам під дощем назавжди!'::text),
(363408,40379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no quedara amabilidad en esta ciudad, ... solo bajo la lluvia para siempre!'::text,'estaría'::text,'estará'::text,'está'::text,'¡Si no quedara amabilidad en esta ciudad, estaría solo bajo la lluvia para siempre!'::text),
(363407,40379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne restait plus de gentillesse dans cette ville, il ... seul sous la pluie pour toujours !'::text,'resterait'::text,'restera'::text,'reste'::text,'S''il ne restait plus de gentillesse dans cette ville, il resterait seul sous la pluie pour toujours !'::text),
(363410,40379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu şehirde hiç iyilik kalmasaydı, sonsuza dek yağmurda tek başına ...!'::text,'dururdu'::text,'duracak'::text,'duruyor'::text,'Bu şehirde hiç iyilik kalmasaydı, sonsuza dek yağmurda tek başına dururdu!'::text),
(363411,40379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem maradna kedvesség ebben a városban, örökre egyedül ... az esőben!'::text,'állna'::text,'fog állni'::text,'áll'::text,'Ha nem maradna kedvesség ebben a városban, örökre egyedül állna az esőben!'::text),
(363423,40381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann wusste, dass die Freundlichkeit des Fremden ihn den ganzen Heimweg trocken halten ...'::text,'würde'::text,'wird'::text,'hält'::text,'Der alte Mann wusste, dass die Freundlichkeit des Fremden ihn den ganzen Heimweg trocken halten würde.'::text),
(363427,40381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий знав, що доброта незнайомця ... його сухим усю дорогу додому.'::text,'збереже'::text,'збереже'::text,'зберігає'::text,'Старий знав, що доброта незнайомця збереже його сухим усю дорогу додому.'::text),
(363426,40381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anciano sabía que la amabilidad del desconocido lo ... seco todo el camino a casa.'::text,'mantendría'::text,'mantendrá'::text,'mantiene'::text,'El anciano sabía que la amabilidad del desconocido lo mantendría seco todo el camino a casa.'::text),
(363425,40381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme savait que la gentillesse de l''inconnu le ... au sec jusqu''à chez lui.'::text,'garderait'::text,'gardera'::text,'garde'::text,'Le vieil homme savait que la gentillesse de l''inconnu le garderait au sec jusqu''à chez lui.'::text),
(363428,40381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam, yabancının iyiliğinin onu eve kadar kuru ... biliyordu.'::text,'tutacağını'::text,'tutacağını'::text,'tuttuğunu'::text,'Yaşlı adam, yabancının iyiliğinin onu eve kadar kuru tutacağını biliyordu.'::text),
(363429,40381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idős férfi tudta, hogy az idegen kedvessége szárazon ... őt egészen hazáig.'::text,'fogja tartani'::text,'fogja tartani'::text,'tartja'::text,'Az idős férfi tudta, hogy az idegen kedvessége szárazon fogja tartani őt egészen hazáig.'::text),
(363432,40382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... die junge Person Freundlichkeit, indem sie den Schirm über den alten Mann hält.'::text,'zeigt'::text,'zeigt'::text,'hat gezeigt'::text,'In diesem Moment zeigt die junge Person Freundlichkeit, indem sie den Schirm über den alten Mann hält.'::text),
(363436,40382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз молода людина ... доброту, тримаючи парасольку над старим.'::text,'виявляє'::text,'виявляє'::text,'виявила'::text,'Зараз молода людина виявляє доброту, тримаючи парасольку над старим.'::text),
(363435,40382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, la persona joven ... amabilidad sosteniendo el paraguas sobre el anciano.'::text,'está mostrando'::text,'muestra'::text,'ha mostrado'::text,'En este momento, la persona joven está mostrando amabilidad sosteniendo el paraguas sobre el anciano.'::text),
(363434,40382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la jeune personne ... de la gentillesse en tenant le parapluie au-dessus du vieil homme.'::text,'montre'::text,'montre'::text,'a montré'::text,'En ce moment, la jeune personne montre de la gentillesse en tenant le parapluie au-dessus du vieil homme.'::text),
(363437,40382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda genç kişi şemsiyeyi yaşlı adamın üzerinde tutarak iyilik ...'::text,'gösteriyor'::text,'gösterir'::text,'gösterdi'::text,'Şu anda genç kişi şemsiyeyi yaşlı adamın üzerinde tutarak iyilik gösteriyor.'::text),
(363438,40382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban a fiatal ... a kedvességét azzal, hogy az esernyőt az idős férfi fölé tartja.'::text,'mutatja'::text,'mutatja'::text,'mutatta'::text,'Ebben a pillanatban a fiatal mutatja a kedvességét azzal, hogy az esernyőt az idős férfi fölé tartja.'::text),
(363441,40383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der alte Mann ... ewig im Regen gestanden, echt, bevor ihm jemand Freundlichkeit gezeigt hat.'::text,'hatte'::text,'hat'::text,'steht'::text,'Digga, der alte Mann hatte ewig im Regen gestanden, echt, bevor ihm jemand Freundlichkeit gezeigt hat.'::text),
(363445,40383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, старий ... під дощем цілу вічність, реально, поки хтось не виявив до нього доброту.'::text,'стояв'::text,'стоїть'::text,'стоїть'::text,'Бро, старий стояв під дощем цілу вічність, реально, поки хтось не виявив до нього доброту.'::text),
(363444,40383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el anciano ... bajo la lluvia una eternidad, en serio, antes de que alguien le mostrara amabilidad.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Bro, el anciano había estado bajo la lluvia una eternidad, en serio, antes de que alguien le mostrara amabilidad.'::text),
(363443,40383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le vieil homme ... sous la pluie pendant une éternité, sérieux, avant que quelqu''un lui montre de la gentillesse.'::text,'était resté'::text,'est resté'::text,'reste'::text,'Frère, le vieil homme était resté sous la pluie pendant une éternité, sérieux, avant que quelqu''un lui montre de la gentillesse.'::text),
(363446,40383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biri ona iyilik gösterene kadar yaşlı adam yağmurda asırlardır ..., cidden.'::text,'bekliyordu'::text,'bekliyor'::text,'bekliyor'::text,'Kanka, biri ona iyilik gösterene kadar yaşlı adam yağmurda asırlardır bekliyordu, cidden.'::text),
(363447,40383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az idős férfi egy örökkévalóságig ... az esőben, komolyan, mielőtt valaki kedvességet mutatott iránta.'::text,'állt'::text,'áll'::text,'áll'::text,'Tesó, az idős férfi egy örökkévalóságig állt az esőben, komolyan, mielőtt valaki kedvességet mutatott iránta.'::text),
(401214,44580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jemand einen schweren Wagen mit einem Seil ..., lehnt er sich immer zurück.'::text,'zieht'::text,'zog'::text,'ziehen wird'::text,'Wenn jemand einen schweren Wagen mit einem Seil zieht, lehnt er sich immer zurück.'::text),
(401218,44580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли хтось ... важкий віз мотузкою, він завжди відхиляється назад.'::text,'тягне'::text,'тягнув'::text,'тягтиме'::text,'Коли хтось тягне важкий віз мотузкою, він завжди відхиляється назад.'::text),
(401217,44580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si alguien ... un carro pesado con una cuerda, siempre se echa hacia atrás.'::text,'tira de'::text,'tiró de'::text,'tirará de'::text,'Si alguien tira de un carro pesado con una cuerda, siempre se echa hacia atrás.'::text),
(401216,44580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelqu''un ... une lourde charrette avec une corde, il se penche toujours en arrière.'::text,'tire'::text,'tirait'::text,'tirera'::text,'Si quelqu''un tire une lourde charrette avec une corde, il se penche toujours en arrière.'::text),
(401219,44580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri ağır bir arabayı iple ..., hep geriye yaslanır.'::text,'çekerse'::text,'çekseydi'::text,'çekecekse'::text,'Biri ağır bir arabayı iple çekerse, hep geriye yaslanır.'::text),
(401220,44580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valaki egy nehéz szekeret ... kötéllel, mindig hátradől.'::text,'húz'::text,'húzott'::text,'húzni fog'::text,'Ha valaki egy nehéz szekeret húz kötéllel, mindig hátradől.'::text),
(401223,44581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn er weiter so zieht, ... der Wagen über das ganze Feld, ohne Witz.'::text,'rollt'::text,'würde rollen'::text,'rollte'::text,'Yo, wenn er weiter so zieht, rollt der Wagen über das ganze Feld, ohne Witz.'::text),
(401227,44581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, якщо він і далі так тягтиме, віз ... через усе поле, без жартів.'::text,'прокотиться'::text,'прокотився б'::text,'прокотився'::text,'Йоу, якщо він і далі так тягтиме, віз прокотиться через усе поле, без жартів.'::text),
(401226,44581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si sigue tirando así, el carro ... por todo el campo, en serio.'::text,'rodará'::text,'rodaría'::text,'rodó'::text,'Yo, si sigue tirando así, el carro rodará por todo el campo, en serio.'::text),
(401225,44581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, s''il continue de tirer comme ça, la charrette ... à travers tout le champ, sans mentir.'::text,'roulera'::text,'roulerait'::text,'a roulé'::text,'Yo, s''il continue de tirer comme ça, la charrette roulera à travers tout le champ, sans mentir.'::text),
(401228,44581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, böyle çekmeye devam ederse araba bütün tarlayı boydan boya ..., yalan yok.'::text,'geçecek'::text,'geçerdi'::text,'geçti'::text,'Hey, böyle çekmeye devam ederse araba bütün tarlayı boydan boya geçecek, yalan yok.'::text),
(401229,44581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ha így húzza tovább, a szekér ... az egész mezőn, nem kamu.'::text,'végig fog gurulni'::text,'végiggurulna'::text,'végiggurult'::text,'Figyu, ha így húzza tovább, a szekér végig fog gurulni az egész mezőn, nem kamu.'::text),
(401232,44582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn der Wagen noch schwerer wäre, ... er ihn nicht bewegen, echt.'::text,'würde'::text,'wird'::text,'bewegte'::text,'Digga, wenn der Wagen noch schwerer wäre, würde er ihn nicht bewegen, echt.'::text),
(401236,44582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби віз був ще важчим, він ... його, реально.'::text,'не зрушив би'::text,'не зрушить'::text,'не зрушив'::text,'Бро, якби віз був ще важчим, він не зрушив би його, реально.'::text),
(401235,44582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si el carro pesara más, no lo ..., en serio.'::text,'movería'::text,'moverá'::text,'movió'::text,'Bro, si el carro pesara más, no lo movería, en serio.'::text),
(401234,44582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si la charrette était encore plus lourde, il ne la ... pas, sérieux.'::text,'bougerait'::text,'bougera'::text,'bougeait'::text,'Frère, si la charrette était encore plus lourde, il ne la bougerait pas, sérieux.'::text),
(401237,44582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, araba biraz daha ağır olsaydı, onu ..., cidden.'::text,'kıpırdatamazdı'::text,'kıpırdatamayacak'::text,'kıpırdatamadı'::text,'Kanka, araba biraz daha ağır olsaydı, onu kıpırdatamazdı, cidden.'::text),
(401238,44582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha a szekér még nehezebb lenne, ..., komolyan.'::text,'nem mozdítaná meg'::text,'nem mozdítja meg'::text,'nem mozdította meg'::text,'Tesó, ha a szekér még nehezebb lenne, nem mozdítaná meg, komolyan.'::text),
(401241,44583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bauernwagen ... von einem einzigen Jungen 40 Meter über das Feld gezogen, eine starke Leistung.'::text,'wurde'::text,'wird'::text,'zog'::text,'Der Bauernwagen wurde von einem einzigen Jungen 40 Meter über das Feld gezogen, eine starke Leistung.'::text),
(401245,44583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сільськогосподарський віз ... одним хлопцем на 40 метрів через поле, сильний результат.'::text,'був протягнутий'::text,'тягнеться'::text,'тягнув'::text,'Сільськогосподарський віз був протягнутий одним хлопцем на 40 метрів через поле, сильний результат.'::text),
(401244,44583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El carro agrícola ... 40 metros por el campo por un solo chico, un gran rendimiento.'::text,'fue arrastrado'::text,'es arrastrado'::text,'arrastró'::text,'El carro agrícola fue arrastrado 40 metros por el campo por un solo chico, un gran rendimiento.'::text),
(401243,44583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La charrette agricole ... sur 40 mètres à travers le champ par un seul garçon, une solide performance.'::text,'a été tirée'::text,'est tirée'::text,'a tiré'::text,'La charrette agricole a été tirée sur 40 mètres à travers le champ par un seul garçon, une solide performance.'::text),
(401246,44583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarım arabası tek bir çocuk tarafından tarla boyunca 40 metre ..., güçlü bir performans.'::text,'çekildi'::text,'çekiliyor'::text,'çekti'::text,'Tarım arabası tek bir çocuk tarafından tarla boyunca 40 metre çekildi, güçlü bir performans.'::text),
(401247,44583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mezőgazdasági szekeret egyetlen fiú ... 40 méteren át a mezőn, erős teljesítmény.'::text,'húzta'::text,'húzza'::text,'húzta'::text,'A mezőgazdasági szekeret egyetlen fiú húzta 40 méteren át a mezőn, erős teljesítmény.'::text),
(401250,44584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wagen ... von dem Jungen gezogen, weil der Wagen nicht laufen kann.'::text,'wurde'::text,'zog'::text,'ziehend'::text,'Der Wagen wurde von dem Jungen gezogen, weil der Wagen nicht laufen kann.'::text),
(401254,44584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Віз ... хлопцем, бо віз не вміє ходити.'::text,'був тягнутий'::text,'тягнув'::text,'тягнучи'::text,'Віз був тягнутий хлопцем, бо віз не вміє ходити.'::text),
(401253,44584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El carro ... por el chico porque el carro no puede andar.'::text,'fue arrastrado'::text,'arrastró'::text,'arrastrando'::text,'El carro fue arrastrado por el chico porque el carro no puede andar.'::text),
(401252,44584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La charrette ... par le garçon parce que la charrette ne peut pas marcher.'::text,'a été tirée'::text,'a tiré'::text,'tirant'::text,'La charrette a été tirée par le garçon parce que la charrette ne peut pas marcher.'::text),
(401255,44584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba yürüyemediği için çocuk tarafından ...'::text,'çekildi'::text,'çekti'::text,'çekerek'::text,'Araba yürüyemediği için çocuk tarafından çekildi.'::text),
(401256,44584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szekeret a fiú ..., mert a szekér nem tud járni.'::text,'húzta'::text,'húzta'::text,'húzva'::text,'A szekeret a fiú húzta, mert a szekér nem tud járni.'::text),
(401259,44585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wagen ... voller Heu sein, aber ich kann nicht hineinsehen.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Der Wagen könnte voller Heu sein, aber ich kann nicht hineinsehen.'::text),
(401263,44585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Віз ... бути повним сіна, але я не бачу, що всередині.'::text,'може'::text,'мусить'::text,'не може'::text,'Віз може бути повним сіна, але я не бачу, що всередині.'::text),
(401262,44585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El carro ... estar lleno de heno, pero no veo lo que hay dentro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'El carro podría estar lleno de heno, pero no veo lo que hay dentro.'::text),
(401261,44585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La charrette ... être pleine de foin, mais je ne vois pas l''intérieur.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'La charrette pourrait être pleine de foin, mais je ne vois pas l''intérieur.'::text),
(401264,44585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba samanla dolu ..., ama içini göremiyorum.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Araba samanla dolu olabilir, ama içini göremiyorum.'::text),
(401265,44585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szekér ... tele van szénával, de nem látok bele.'::text,'lehet, hogy'::text,'biztosan'::text,'nem lehet'::text,'A szekér lehet, hogy tele van szénával, de nem látok bele.'::text),
(401268,44586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Seil, ... er zieht, ist an einen grünen Wagen gebunden.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Seil, das er zieht, ist an einen grünen Wagen gebunden.'::text),
(401272,44586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мотузка, ... він тягне, прив''язана до зеленого воза.'::text,'яку'::text,'хто'::text,'чия'::text,'Мотузка, яку він тягне, прив''язана до зеленого воза.'::text),
(401271,44586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cuerda de ... tira está atada a un carro verde.'::text,'la que'::text,'quien'::text,'cuya'::text,'La cuerda de la que tira está atada a un carro verde.'::text),
(401270,44586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La corde ... il tire est attachée à une charrette verte.'::text,'sur laquelle'::text,'qui'::text,'dont'::text,'La corde sur laquelle il tire est attachée à une charrette verte.'::text),
(401273,44586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çektiği ... ip yeşil bir arabaya bağlı.'::text,''::text,NULL::text,NULL::text,'Çektiği ip yeşil bir arabaya bağlı.'::text),
(401274,44586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kötél, ... húz, egy zöld szekérhez van kötve.'::text,'amit'::text,'aki'::text,'amelynek'::text,'A kötél, amit húz, egy zöld szekérhez van kötve.'::text),
(401277,44587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... den Wagen allein bis zur Scheune ziehen.'::text,'würde'::text,'werde'::text,'ziehe'::text,'Er sagte, er würde den Wagen allein bis zur Scheune ziehen.'::text),
(401281,44587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... віз до стодоли сам.'::text,'дотягне'::text,'дотягне'::text,'тягне'::text,'Він сказав, що дотягне віз до стодоли сам.'::text),
(401280,44587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... el carro hasta el granero él solo.'::text,'arrastraría'::text,'arrastrará'::text,'arrastra'::text,'Dijo que arrastraría el carro hasta el granero él solo.'::text),
(401279,44587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... la charrette jusqu''à la grange tout seul.'::text,'tirerait'::text,'tirera'::text,'tire'::text,'Il a dit qu''il tirerait la charrette jusqu''à la grange tout seul.'::text),
(401282,44587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabayı ahıra kendi başına ... söyledi.'::text,'çekeceğini'::text,'çekeceğini'::text,'çektiğini'::text,'Arabayı ahıra kendi başına çekeceğini söyledi.'::text),
(401283,44587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy egyedül ... a szekeret a pajtáig.'::text,'el fogja húzni'::text,'el fogja húzni'::text,'húzza'::text,'Azt mondta, hogy egyedül el fogja húzni a szekeret a pajtáig.'::text),
(401286,44588,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Wagen ... früher einen Traktor, der ihn zog, und jetzt hat er nur ihn! Katastrophe!'::text,'hatte'::text,'hatte'::text,'war gewohnt'::text,'Dieser Wagen hatte früher einen Traktor, der ihn zog, und jetzt hat er nur ihn! Katastrophe!'::text),
(401290,44588,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей віз ... трактор, який його тягнув, а тепер має лише його! Катастрофа!'::text,'колись мав'::text,'мав'::text,'звик мати'::text,'Цей віз колись мав трактор, який його тягнув, а тепер має лише його! Катастрофа!'::text),
(401289,44588,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este carro ... tener un tractor que tiraba de él, y ahora solo lo tiene a él! ¡Desastre!'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'¡Este carro solía tener un tractor que tiraba de él, y ahora solo lo tiene a él! ¡Desastre!'::text),
(401288,44588,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette charrette ... un tracteur pour la tirer, et maintenant elle n''a que lui ! Catastrophe !'::text,'avait autrefois'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Cette charrette avait autrefois un tracteur pour la tirer, et maintenant elle n''a que lui ! Catastrophe !'::text),
(401291,44588,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu arabanın eskiden onu çeken bir traktörü ..., şimdi ise sadece o var! Felaket!'::text,'vardı'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu arabanın eskiden onu çeken bir traktörü vardı, şimdi ise sadece o var! Felaket!'::text),
(401292,44588,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek a szekérnek régen traktor ... a húzásához, most meg csak ő van neki! Katasztrófa!'::text,'volt'::text,'volt'::text,'szokott lenni'::text,'Ennek a szekérnek régen traktor volt a húzásához, most meg csak ő van neki! Katasztrófa!'::text),
(401295,44589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weigert sich absolut, das Wagenseil ..., selbst wenn es ewig dauert!'::text,'loszulassen'::text,'loslassen'::text,'loslassen'::text,'Er weigert sich absolut, das Wagenseil loszulassen, selbst wenn es ewig dauert!'::text),
(401299,44589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він категорично відмовляється ... мотузку воза, навіть якщо це триватиме вічність!'::text,'відпустити'::text,'відпускання'::text,'відпустити'::text,'Він категорично відмовляється відпустити мотузку воза, навіть якщо це триватиме вічність!'::text),
(401298,44589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niega rotundamente a ... la cuerda del carro, aunque tarde una eternidad!'::text,'soltar'::text,'soltar'::text,'soltar'::text,'¡Se niega rotundamente a soltar la cuerda del carro, aunque tarde una eternidad!'::text),
(401297,44589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il refuse catégoriquement de ... la corde de la charrette, même si ça prend une éternité !'::text,'lâcher'::text,'lâcher'::text,'lâcher'::text,'Il refuse catégoriquement de lâcher la corde de la charrette, même si ça prend une éternité !'::text),
(401300,44589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonsuza kadar sürse bile arabanın ipini ... kesinlikle reddediyor!'::text,'bırakmayı'::text,'bırakmayı'::text,'bırakmayı'::text,'Sonsuza kadar sürse bile arabanın ipini bırakmayı kesinlikle reddediyor!'::text),
(401301,44589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abszolút nem hajlandó ... a szekér kötelét, még ha örökké tart is!'::text,'elengedni'::text,'elengedni'::text,'elengedni'::text,'Abszolút nem hajlandó elengedni a szekér kötelét, még ha örökké tart is!'::text),
(347754,38640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, einen Gummistiefel ..., und die Enttäuschung hat ihn zerstört!'::text,'gefangen zu haben'::text,'zu fangen'::text,'fing'::text,'Er gab zu, einen Gummistiefel gefangen zu haben, und die Enttäuschung hat ihn zerstört!'::text),
(347758,38640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він визнав, що ... гумовий чобіт, і розчарування його знищило!'::text,'впіймав'::text,'впіймати'::text,'впіймав'::text,'Він визнав, що впіймав гумовий чобіт, і розчарування його знищило!'::text),
(347757,38640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Admitió ... una bota de goma, y la decepción lo destrozó!'::text,'haber pescado'::text,'pescar'::text,'pescó'::text,'¡Admitió haber pescado una bota de goma, y la decepción lo destrozó!'::text),
(347756,38640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a admis ... une botte en caoutchouc, et la déception l''a anéanti !'::text,'avoir attrapé'::text,'attraper'::text,'a attrapé'::text,'Il a admis avoir attrapé une botte en caoutchouc, et la déception l''a anéanti !'::text),
(347759,38640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir lastik çizme ... itiraf etti ve hayal kırıklığı onu mahvetti!'::text,'yakaladığını'::text,'yakalamayı'::text,'yakaladı'::text,'Bir lastik çizme yakaladığını itiraf etti ve hayal kırıklığı onu mahvetti!'::text),
(347760,38640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy egy gumicsizmát ..., és a csalódás tönkretette!'::text,'fogott ki'::text,'kifogni'::text,'kifogta'::text,'Beismerte, hogy egy gumicsizmát fogott ki, és a csalódás tönkretette!'::text),
(347763,38641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, es ... ein riesiger Fisch gewesen sein, und dann kam die Enttäuschung.'::text,'muss'::text,'sollte'::text,'muss nicht'::text,'Hör zu, er hat mir erzählt, es muss ein riesiger Fisch gewesen sein, und dann kam die Enttäuschung.'::text),
(347767,38641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він мені сказав, що це ... величезна риба, а потім накрило розчарування.'::text,'точно була'::text,'мала бути'::text,'не мусила бути'::text,'Слухай, він мені сказав, що це точно була величезна риба, а потім накрило розчарування.'::text),
(347766,38641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que ... sido un pez enorme, y luego llegó la decepción.'::text,'tenía que haber'::text,'debería haber'::text,'no tenía por qué haber'::text,'Escucha, me dijo que tenía que haber sido un pez enorme, y luego llegó la decepción.'::text),
(347765,38641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que ça ... être un énorme poisson, et puis la déception est tombée.'::text,'devait'::text,'aurait dû'::text,'n''avait pas besoin d'''::text,'Écoute, il m''a dit que ça devait être un énorme poisson, et puis la déception est tombée.'::text),
(347768,38641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki bu kocaman bir balık ..., sonra hayal kırıklığı geldi.'::text,'olmuş olmalı'::text,'olmalıydı'::text,'olmasa da olurdu'::text,'Dinle, bana dedi ki bu kocaman bir balık olmuş olmalı, sonra hayal kırıklığı geldi.'::text),
(347769,38641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy ez ... egy óriási hal volt, aztán jött a csalódás.'::text,'biztosan'::text,'kellett volna, hogy'::text,'nem kellett, hogy'::text,'Figyelj, azt mondta, hogy ez biztosan egy óriási hal volt, aztán jött a csalódás.'::text),
(347772,38642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... solche Enttäuschung auf zwei Gesichtern gleichzeitig auf einem Angelsteg gesehen.'::text,'habe ich'::text,'ich habe'::text,'sah ich'::text,'Selten habe ich solche Enttäuschung auf zwei Gesichtern gleichzeitig auf einem Angelsteg gesehen.'::text),
(347776,38642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... таке розчарування на двох обличчях одночасно на рибальському помості.'::text,'я бачив'::text,'я бачив'::text,'я бачив'::text,'Рідко я бачив таке розчарування на двох обличчях одночасно на рибальському помості.'::text),
(347775,38642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... tanta decepción en dos caras a la vez en un muelle de pesca.'::text,'he visto'::text,'yo he visto'::text,'vi'::text,'Pocas veces he visto tanta decepción en dos caras a la vez en un muelle de pesca.'::text),
(347774,38642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... une telle déception sur deux visages à la fois sur un ponton de pêche.'::text,'ai-je vu'::text,'j''ai vu'::text,'je vis'::text,'Rarement ai-je vu une telle déception sur deux visages à la fois sur un ponton de pêche.'::text),
(347777,38642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir balıkçı iskelesinde iki yüzde aynı anda böyle bir hayal kırıklığını nadiren ...'::text,'gördüm'::text,'gördüm'::text,'gördüm'::text,'Bir balıkçı iskelesinde iki yüzde aynı anda böyle bir hayal kırıklığını nadiren gördüm.'::text),
(347778,38642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ekkora csalódást egyszerre két arcon egy horgászstégen.'::text,'láttam'::text,'láttam'::text,'láttam'::text,'Ritkán láttam ekkora csalódást egyszerre két arcon egy horgászstégen.'::text),
(347790,38644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, die Schnur ... einen Fisch hochgezogen; der Stiefel war eine echte Enttäuschung.'::text,'hätte'::text,'hat'::text,'würde'::text,'Er wünschte, die Schnur hätte einen Fisch hochgezogen; der Stiefel war eine echte Enttäuschung.'::text),
(347794,38644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб волосінь ... рибу; чобіт був справжнім розчаруванням.'::text,'витягла'::text,'витягла'::text,'витягла'::text,'Він хотів би, щоб волосінь витягла рибу; чобіт був справжнім розчаруванням.'::text),
(347793,38644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía que el sedal ... un pez; la bota fue una auténtica decepción.'::text,'hubiera sacado'::text,'sacara'::text,'sacaría'::text,'Él desearía que el sedal hubiera sacado un pez; la bota fue una auténtica decepción.'::text),
(347792,38644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement la ligne ... un poisson ; la botte a été une vraie déception.'::text,'avait remonté'::text,'remontait'::text,'remonterait'::text,'Si seulement la ligne avait remonté un poisson ; la botte a été une vraie déception.'::text),
(347795,38644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke olta bir balık ...; çizme tam bir hayal kırıklığıydı.'::text,'çıkarsaydı'::text,'çıkarsa'::text,'çıkaracak olsaydı'::text,'Keşke olta bir balık çıkarsaydı; çizme tam bir hayal kırıklığıydı.'::text),
(347796,38644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak halat ... fel a zsinór; a csizma igazi csalódás volt.'::text,'hozott volna'::text,'hozna'::text,'hozna majd'::text,'Bárcsak halat hozott volna fel a zsinór; a csizma igazi csalódás volt.'::text),
(347799,38645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Angler, ... Enttäuschung leicht zu sehen ist, starrt auf den nassen Stiefel.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Angler, dessen Enttäuschung leicht zu sehen ist, starrt auf den nassen Stiefel.'::text),
(347803,38645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рибалка, ... розчарування легко помітити, дивиться на мокрий чобіт.'::text,'чиє'::text,'який'::text,'котрий'::text,'Рибалка, чиє розчарування легко помітити, дивиться на мокрий чобіт.'::text),
(347802,38645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pescador, ... decepción es fácil de ver, mira fijamente la bota mojada.'::text,'cuya'::text,'que'::text,'el cual'::text,'El pescador, cuya decepción es fácil de ver, mira fijamente la bota mojada.'::text),
(347801,38645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pêcheur, ... la déception se voit facilement, fixe la botte mouillée.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le pêcheur, dont la déception se voit facilement, fixe la botte mouillée.'::text),
(347804,38645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayal kırıklığı kolayca görülen ... balıkçı ıslak çizmeye bakıyor.'::text,''::text,NULL::text,NULL::text,'Hayal kırıklığı kolayca görülen balıkçı ıslak çizmeye bakıyor.'::text),
(347805,38645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A horgász, ... csalódása könnyen látható, a vizes csizmát bámulja.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A horgász, akinek a csalódása könnyen látható, a vizes csizmát bámulja.'::text),
(347808,38646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach so einem langen Kampf mit der Rute war der Stiefel ... Enttäuschung.'::text,'eine große'::text,'die große'::text,'große'::text,'Nach so einem langen Kampf mit der Rute war der Stiefel eine große Enttäuschung.'::text),
(347812,38646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після такої довгої боротьби з вудкою чобіт став ... розчаруванням.'::text,'великим'::text,'великим'::text,'великим'::text,'Після такої довгої боротьби з вудкою чобіт став великим розчаруванням.'::text),
(347811,38646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de una lucha tan larga con la caña, la bota fue ... decepción.'::text,'una gran'::text,'la gran'::text,'gran'::text,'Después de una lucha tan larga con la caña, la bota fue una gran decepción.'::text),
(347810,38646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après un si long combat avec la canne, la botte a été ... déception.'::text,'une grosse'::text,'la grosse'::text,'grosse'::text,'Après un si long combat avec la canne, la botte a été une grosse déception.'::text),
(347813,38646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oltayla bu kadar uzun bir mücadeleden sonra çizme ... hayal kırıklığıydı.'::text,'büyük bir'::text,'büyük'::text,'büyük'::text,'Oltayla bu kadar uzun bir mücadeleden sonra çizme büyük bir hayal kırıklığıydı.'::text),
(347814,38646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bottal vívott ilyen hosszú küzdelem után a csizma ... csalódás volt.'::text,'egy nagy'::text,'a nagy'::text,'nagy'::text,'A bottal vívott ilyen hosszú küzdelem után a csizma egy nagy csalódás volt.'::text),
(347817,38647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rute bog sich stark; ... war der Fang eine Enttäuschung.'::text,'trotzdem'::text,'außerdem'::text,'deshalb'::text,'Die Rute bog sich stark; trotzdem war der Fang eine Enttäuschung.'::text),
(347821,38647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вудка сильно зігнулася; ..., улов виявився розчаруванням.'::text,'проте'::text,'до того ж'::text,'тому'::text,'Вудка сильно зігнулася; проте, улов виявився розчаруванням.'::text),
(347820,38647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caña se dobló mucho; ..., la captura fue una decepción.'::text,'sin embargo'::text,'además'::text,'por lo tanto'::text,'La caña se dobló mucho; sin embargo, la captura fue una decepción.'::text),
(347819,38647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La canne s''est fortement pliée ; ..., la prise a été une déception.'::text,'néanmoins'::text,'de plus'::text,'par conséquent'::text,'La canne s''est fortement pliée ; néanmoins, la prise a été une déception.'::text),
(347822,38647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olta iyice büküldü; ..., av bir hayal kırıklığıydı.'::text,'yine de'::text,'üstelik'::text,'bu yüzden'::text,'Olta iyice büküldü; yine de, av bir hayal kırıklığıydı.'::text),
(347823,38647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bot erősen meghajlott; ... a fogás csalódás volt.'::text,'mégis'::text,'ráadásul'::text,'ezért'::text,'A bot erősen meghajlott; mégis a fogás csalódás volt.'::text),
(347826,38648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt nahm an, dass die gebogene Rute einen großen Fisch zum Vorschein bringen ...; die Enttäuschung war beträchtlich.'::text,'würde'::text,'wird'::text,'bringt'::text,'Das Subjekt nahm an, dass die gebogene Rute einen großen Fisch zum Vorschein bringen würde; die Enttäuschung war beträchtlich.'::text),
(347830,38648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт припускав, що зігнута вудка ... велику рибу; розчарування було значним.'::text,'виявить'::text,'виявить'::text,'виявляє'::text,'Суб''єкт припускав, що зігнута вудка виявить велику рибу; розчарування було значним.'::text),
(347829,38648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto supuso que la caña doblada ... un pez grande; la decepción fue considerable.'::text,'revelaría'::text,'revelará'::text,'revela'::text,'El sujeto supuso que la caña doblada revelaría un pez grande; la decepción fue considerable.'::text),
(347828,38648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet supposait que la canne pliée ... un gros poisson ; la déception a été considérable.'::text,'révélerait'::text,'révélera'::text,'révèle'::text,'Le sujet supposait que la canne pliée révélerait un gros poisson ; la déception a été considérable.'::text),
(347831,38648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek, bükülen oltanın büyük bir balık ... varsaydı; hayal kırıklığı kayda değerdi.'::text,'çıkaracağını'::text,'çıkaracağını'::text,'çıkardığını'::text,'Denek, bükülen oltanın büyük bir balık çıkaracağını varsaydı; hayal kırıklığı kayda değerdi.'::text),
(347832,38648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany feltételezte, hogy a meghajlott bot egy nagy halat ... elő; a csalódás jelentős volt.'::text,'fog hozni'::text,'fog hozni'::text,'hoz'::text,'Az alany feltételezte, hogy a meghajlott bot egy nagy halat fog hozni elő; a csalódás jelentős volt.'::text),
(347835,38649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er auf den Stiefel, und die Enttäuschung ist absolut niederschmetternd!'::text,'starrt'::text,'starrt'::text,'hat gestarrt'::text,'Gerade starrt er auf den Stiefel, und die Enttäuschung ist absolut niederschmetternd!'::text),
(347839,38649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз він ... на чобіт, і розчарування абсолютно нищівне!'::text,'витріщається'::text,'витріщається'::text,'витріщався'::text,'Просто зараз він витріщається на чобіт, і розчарування абсолютно нищівне!'::text),
(347838,38649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo ... la bota, y la decepción es absolutamente demoledora!'::text,'está mirando fijamente'::text,'mira fijamente'::text,'ha mirado fijamente'::text,'¡Ahora mismo está mirando fijamente la bota, y la decepción es absolutamente demoledora!'::text),
(347837,38649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... la botte, et la déception est absolument écrasante !'::text,'fixe'::text,'fixe'::text,'a fixé'::text,'En ce moment, il fixe la botte, et la déception est absolument écrasante !'::text),
(347840,38649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda çizmeye ... ve hayal kırıklığı resmen yıkıcı!'::text,'bakıyor'::text,'bakar'::text,'baktı'::text,'Şu anda çizmeye bakıyor ve hayal kırıklığı resmen yıkıcı!'::text),
(347841,38649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a csizmát, és a csalódás teljesen lesújtó!'::text,'bámulja'::text,'bámulja'::text,'bámulta'::text,'Épp most bámulja a csizmát, és a csalódás teljesen lesújtó!'::text),
(347844,38650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon zehn Minuten mit der Rute gekämpft, als der Stiefel die totale Enttäuschung brachte!'::text,'hatte'::text,'hat'::text,'kämpft'::text,'Er hatte schon zehn Minuten mit der Rute gekämpft, als der Stiefel die totale Enttäuschung brachte!'::text),
(347848,38650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже десять хвилин ... з вудкою, коли чобіт приніс повне розчарування!'::text,'боровся'::text,'бореться'::text,'бореться'::text,'Він уже десять хвилин боровся з вудкою, коли чобіт приніс повне розчарування!'::text),
(347847,38650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... con la caña durante diez minutos cuando la bota trajo una decepción total!'::text,'Había estado luchando'::text,'Ha estado luchando'::text,'Lucha'::text,'¡Había estado luchando con la caña durante diez minutos cuando la bota trajo una decepción total!'::text),
(347846,38650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... avec la canne depuis dix minutes quand la botte a apporté la déception totale !'::text,'se battait'::text,'se bat'::text,'se bat'::text,'Il se battait avec la canne depuis dix minutes quand la botte a apporté la déception totale !'::text),
(347849,38650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çizme tam bir hayal kırıklığı getirdiğinde on dakikadır oltayla ...!'::text,'boğuşuyordu'::text,'boğuşuyor'::text,'boğuşur'::text,'Çizme tam bir hayal kırıklığı getirdiğinde on dakikadır oltayla boğuşuyordu!'::text),
(347850,38650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz perce ... a bottal, amikor a csizma teljes csalódást hozott!'::text,'küzdött'::text,'küzd'::text,'küzd'::text,'Tíz perce küzdött a bottal, amikor a csizma teljes csalódást hozott!'::text),
(360939,40105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... das Team die rote Flagge vor dem flachen Horizont hissen.'::text,'wird'::text,'wird'::text,'hisst'::text,'Morgen um diese Zeit wird das Team die rote Flagge vor dem flachen Horizont hissen.'::text),
(360943,40105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час команда ... червоний прапор на тлі рівного горизонту.'::text,'підніматиме'::text,'підніме'::text,'піднімає'::text,'Завтра в цей час команда підніматиме червоний прапор на тлі рівного горизонту.'::text),
(360942,40105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el equipo ... la bandera roja frente al horizonte llano.'::text,'estará izando'::text,'izará'::text,'iza'::text,'Mañana a esta hora, el equipo estará izando la bandera roja frente al horizonte llano.'::text),
(360941,40105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, l''équipe ... le drapeau rouge devant l''horizon plat.'::text,'sera en train de hisser'::text,'hissera'::text,'hisse'::text,'Demain à la même heure, l''équipe sera en train de hisser le drapeau rouge devant l''horizon plat.'::text),
(360944,40105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde ekip düz ufkun önünde kırmızı bayrağı ...'::text,'göndere çekiyor olacak'::text,'göndere çekecek'::text,'göndere çekiyor'::text,'Yarın bu saatlerde ekip düz ufkun önünde kırmızı bayrağı göndere çekiyor olacak.'::text),
(360945,40105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a csapat ... a vörös zászlót a sík horizont előtt.'::text,'épp vonja fel'::text,'fel fogja vonni'::text,'felvonja'::text,'Holnap ilyenkor a csapat épp vonja fel a vörös zászlót a sík horizont előtt.'::text),
(360948,40106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team verspricht, dass es die Flagge ..., bevor die Sonne unter den Horizont sinkt.'::text,'einholen wird'::text,'einholen wird'::text,'einholt'::text,'Das Team verspricht, dass es die Flagge einholen wird, bevor die Sonne unter den Horizont sinkt.'::text),
(360952,40106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда обіцяє, що ... прапор, перш ніж сонце сяде за горизонт.'::text,'зніме'::text,'зніматиме'::text,'знімає'::text,'Команда обіцяє, що зніме прапор, перш ніж сонце сяде за горизонт.'::text),
(360951,40106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo promete que ... la bandera antes de que el sol se hunda en el horizonte.'::text,'bajará'::text,'estará bajando'::text,'está bajando'::text,'El equipo promete que bajará la bandera antes de que el sol se hunda en el horizonte.'::text),
(360950,40106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe promet qu''elle ... le drapeau avant que le soleil ne passe sous l''horizon.'::text,'descendra'::text,'sera en train de descendre'::text,'descend'::text,'L''équipe promet qu''elle descendra le drapeau avant que le soleil ne passe sous l''horizon.'::text),
(360953,40106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip, güneş ufkun altına inmeden bayrağı ... söz veriyor.'::text,'indireceğine'::text,'indiriyor olacağına'::text,'indirdiğine'::text,'Ekip, güneş ufkun altına inmeden bayrağı indireceğine söz veriyor.'::text),
(360954,40106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat megígéri, hogy ... a zászlót, mielőtt a nap a horizont alá bukik.'::text,'leveszi'::text,'le fogja venni'::text,'épp leveszi'::text,'A csapat megígéri, hogy leveszi a zászlót, mielőtt a nap a horizont alá bukik.'::text),
(360957,40107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die rote Flagge ... den Mast hochgezogen, während sich der Schnee bis zum Horizont erstreckte.'::text,'wurde'::text,'zog'::text,'wird'::text,'Die rote Flagge wurde den Mast hochgezogen, während sich der Schnee bis zum Horizont erstreckte.'::text),
(360961,40107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний прапор ... на щоглу, поки сніг тягнувся до самого горизонту.'::text,'був піднятий'::text,'підняв'::text,'піднімається'::text,'Червоний прапор був піднятий на щоглу, поки сніг тягнувся до самого горизонту.'::text),
(360960,40107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bandera roja ... por el mástil mientras la nieve se extendía hasta el horizonte.'::text,'fue izada'::text,'izó'::text,'es izada'::text,'La bandera roja fue izada por el mástil mientras la nieve se extendía hasta el horizonte.'::text),
(360959,40107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le drapeau rouge ... le long du mât pendant que la neige s''étendait jusqu''à l''horizon.'::text,'a été hissé'::text,'a hissé'::text,'est hissé'::text,'Le drapeau rouge a été hissé le long du mât pendant que la neige s''étendait jusqu''à l''horizon.'::text),
(360962,40107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kar ufka kadar uzanırken kırmızı bayrak direğe ...'::text,'çekildi'::text,'çekti'::text,'çekiliyor'::text,'Kar ufka kadar uzanırken kırmızı bayrak direğe çekildi.'::text),
(360963,40107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vörös zászlót ... az árbocra, miközben a hó a horizontig nyúlt.'::text,'felhúzták'::text,'felhúzta'::text,'felhúzzák'::text,'A vörös zászlót felhúzták az árbocra, miközben a hó a horizontig nyúlt.'::text),
(360966,40108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drei durchgefrorene Menschen ... die rote Flagge vor einem Horizont aus endlosem, schrecklichem Eis hoch!'::text,'zogen'::text,'wurden gezogen'::text,'ziehend'::text,'Drei durchgefrorene Menschen zogen die rote Flagge vor einem Horizont aus endlosem, schrecklichem Eis hoch!'::text),
(360970,40108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Троє змерзлих людей ... червоний прапор угору на тлі горизонту нескінченної, жахливої криги!'::text,'підняли'::text,'були підняті'::text,'піднімаючи'::text,'Троє змерзлих людей підняли червоний прапор угору на тлі горизонту нескінченної, жахливої криги!'::text),
(360969,40108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Tres personas congeladas ... la bandera roja contra un horizonte de hielo infinito y aterrador!'::text,'izaron'::text,'fueron izadas'::text,'izando'::text,'¡Tres personas congeladas izaron la bandera roja contra un horizonte de hielo infinito y aterrador!'::text),
(360968,40108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trois personnes gelées ... le drapeau rouge face à un horizon de glace infinie et terrifiante !'::text,'ont hissé'::text,'ont été hissées'::text,'hissant'::text,'Trois personnes gelées ont hissé le drapeau rouge face à un horizon de glace infinie et terrifiante !'::text),
(360971,40108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Donmuş üç kişi, sonsuz ve korkunç buzdan bir ufkun önünde kırmızı bayrağı ...!'::text,'göndere çekti'::text,'göndere çekildi'::text,'göndere çekerek'::text,'Donmuş üç kişi, sonsuz ve korkunç buzdan bir ufkun önünde kırmızı bayrağı göndere çekti!'::text),
(360972,40108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három átfagyott ember ... a vörös zászlót a végtelen, rémisztő jég horizontja előtt!'::text,'felhúzta'::text,'fel lett húzva'::text,'felhúzva'::text,'Három átfagyott ember felhúzta a vörös zászlót a végtelen, rémisztő jég horizontja előtt!'::text),
(360975,40109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, die Hütte am Horizont ... ihre Basis sein, aber keiner weiß es genau.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Hör zu, ich hab gehört, die Hütte am Horizont könnte ihre Basis sein, aber keiner weiß es genau.'::text),
(360979,40109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що хатинка на горизонті ... бути їхньою базою, але ніхто точно не знає.'::text,'може'::text,'мусить'::text,'не може'::text,'Слухай, я чула, що хатинка на горизонті може бути їхньою базою, але ніхто точно не знає.'::text),
(360978,40109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, he oído que la cabaña del horizonte ... ser su base, pero nadie lo sabe seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Escucha, he oído que la cabaña del horizonte podría ser su base, pero nadie lo sabe seguro.'::text),
(360977,40109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que la cabane à l''horizon ... être leur base, mais personne n''en est sûr.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Écoute, j''ai entendu dire que la cabane à l''horizon pourrait être leur base, mais personne n''en est sûr.'::text),
(360980,40109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki ufuktaki kulübe onların üssü ..., ama kimse kesin bilmiyor.'::text,'olabilirmiş'::text,'olmalıymış'::text,'olamazmış'::text,'Dinle, duydum ki ufuktaki kulübe onların üssü olabilirmiş, ama kimse kesin bilmiyor.'::text),
(360981,40109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a horizonton lévő kunyhó ... a bázisuk, de senki sem tudja biztosan.'::text,'lehet'::text,'biztosan'::text,'nem lehet'::text,'Figyelj, azt hallottam, hogy a horizonton lévő kunyhó lehet a bázisuk, de senki sem tudja biztosan.'::text),
(360984,40110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, die Hütte, ... du am Horizont sehen kannst, ist da, wo sie schlafen.'::text,'die'::text,'wer'::text,'deren'::text,'Bestie, er hat mir erzählt, die Hütte, die du am Horizont sehen kannst, ist da, wo sie schlafen.'::text),
(360988,40110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, він мені сказав, що хатинка, ... ти бачиш на горизонті, — це місце, де вони сплять.'::text,'яку'::text,'хто'::text,'чия'::text,'Бесті, він мені сказав, що хатинка, яку ти бачиш на горизонті, — це місце, де вони сплять.'::text),
(360987,40110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, me dijo que la cabaña ... puedes ver en el horizonte es donde duermen.'::text,'que'::text,'quien'::text,'cuya'::text,'Bestie, me dijo que la cabaña que puedes ver en el horizonte es donde duermen.'::text),
(360986,40110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, il m''a dit que la cabane ... tu vois à l''horizon, c''est là où ils dorment.'::text,'que'::text,'qui'::text,'dont'::text,'Ma bestie, il m''a dit que la cabane que tu vois à l''horizon, c''est là où ils dorment.'::text),
(360989,40110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana dedi ki ufukta görebildiğin ... kulübe onların uyuduğu yermiş.'::text,''::text,NULL::text,NULL::text,'Kanka, bana dedi ki ufukta görebildiğin kulübe onların uyuduğu yermiş.'::text),
(360990,40110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt mondta, hogy a kunyhó, ... a horizonton látsz, az a hely, ahol alszanak.'::text,'amit'::text,'aki'::text,'amelynek'::text,'Bestie, azt mondta, hogy a kunyhó, amit a horizonton látsz, az a hely, ahol alszanak.'::text),
(360993,40111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er meinte, sie ... die Flagge dreimal hochgezogen, bevor der Horizont dunkel wurde.'::text,'hätten'::text,'haben'::text,'ziehen'::text,'Rate mal, er meinte, sie hätten die Flagge dreimal hochgezogen, bevor der Horizont dunkel wurde.'::text),
(360997,40111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він сказав, що вони ... той прапор тричі, поки горизонт не потемнів.'::text,'піднімали'::text,'піднімали'::text,'піднімають'::text,'Уяви, він сказав, що вони піднімали той прапор тричі, поки горизонт не потемнів.'::text),
(360996,40111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, dijo que ... esa bandera tres veces antes de que el horizonte se oscureciera.'::text,'habían izado'::text,'han izado'::text,'izan'::text,'Adivina qué, dijo que habían izado esa bandera tres veces antes de que el horizonte se oscureciera.'::text),
(360995,40111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il a dit qu''ils ... ce drapeau trois fois avant que l''horizon ne s''assombrisse.'::text,'avaient hissé'::text,'ont hissé'::text,'hissent'::text,'Devine quoi, il a dit qu''ils avaient hissé ce drapeau trois fois avant que l''horizon ne s''assombrisse.'::text),
(360998,40111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et, ufuk kararmadan önce o bayrağı üç kez ... söyledi.'::text,'çektiklerini'::text,'çektiklerini'::text,'çektiklerini'::text,'Tahmin et, ufuk kararmadan önce o bayrağı üç kez çektiklerini söyledi.'::text),
(360999,40111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy háromszor ... fel azt a zászlót, mielőtt a horizont elsötétült.'::text,'húzták'::text,'húzták'::text,'húzzák'::text,'Képzeld, azt mondta, hogy háromszor húzták fel azt a zászlót, mielőtt a horizont elsötétült.'::text),
(361002,40112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht gelogen, du ... früher Schnee, und jetzt hisst du Flaggen vor einem endlosen Horizont.'::text,'hasstest'::text,'hasstest'::text,'warst gewohnt zu hassen'::text,'Nicht gelogen, du hasstest früher Schnee, und jetzt hisst du Flaggen vor einem endlosen Horizont.'::text),
(361006,40112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... сніг, а тепер піднімаєш прапори перед нескінченним горизонтом.'::text,'колись ненавидів'::text,'ненавидів'::text,'звик ненавидіти'::text,'Не буду брехати, ти колись ненавидів сніг, а тепер піднімаєш прапори перед нескінченним горизонтом.'::text),
(361005,40112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú ... odiar la nieve, y ahora izas banderas frente a un horizonte infinito.'::text,'solías'::text,'solías'::text,'estabas acostumbrado a'::text,'No voy a mentir, tú solías odiar la nieve, y ahora izas banderas frente a un horizonte infinito.'::text),
(361004,40112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... la neige avant, et maintenant tu hisses des drapeaux devant un horizon infini.'::text,'détestais'::text,'détestais'::text,'avais l''habitude de détester'::text,'Sans mentir, tu détestais la neige avant, et maintenant tu hisses des drapeaux devant un horizon infini.'::text),
(361007,40112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, eskiden kardan ..., şimdi ise sonsuz bir ufkun önünde bayrak dikiyorsun.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Yalan yok, eskiden kardan nefret ederdin, şimdi ise sonsuz bir ufkun önünde bayrak dikiyorsun.'::text),
(361008,40112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, régen ... a havat, most meg zászlókat vonsz fel egy végtelen horizont előtt.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva, hogy utáld'::text,'Nem hazudok, régen utáltad a havat, most meg zászlókat vonsz fel egy végtelen horizont előtt.'::text),
(361029,40115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Leistung: Der Horizont ... wochenlang völlig leer gewesen, bevor sie die Flagge hissten.'::text,'war'::text,'ist'::text,'wurde'::text,'Tolle Leistung: Der Horizont war wochenlang völlig leer gewesen, bevor sie die Flagge hissten.'::text),
(361033,40115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота: горизонт ... цілком порожнім тижнями, поки вони не підняли той прапор.'::text,'був'::text,'є'::text,'ставав'::text,'Чудова робота: горизонт був цілком порожнім тижнями, поки вони не підняли той прапор.'::text),
(361032,40115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo: el horizonte ... completamente vacío durante semanas antes de que izaran esa bandera.'::text,'había estado'::text,'ha estado'::text,'estaba siendo'::text,'Buen trabajo: el horizonte había estado completamente vacío durante semanas antes de que izaran esa bandera.'::text),
(361031,40115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo : l''horizon ... complètement vide pendant des semaines avant qu''ils ne hissent ce drapeau.'::text,'avait été'::text,'a été'::text,'était en train d''être'::text,'Bravo : l''horizon avait été complètement vide pendant des semaines avant qu''ils ne hissent ce drapeau.'::text),
(361034,40115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş: o bayrağı dikmeden önce ufuk haftalarca tamamen ...'::text,'boştu'::text,'boş'::text,'boş oluyordu'::text,'Harika iş: o bayrağı dikmeden önce ufuk haftalarca tamamen boştu.'::text),
(361035,40115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka: a horizont hetekig teljesen üres ..., mielőtt felvonták azt a zászlót.'::text,'volt'::text,'van'::text,'lett'::text,'Szép munka: a horizont hetekig teljesen üres volt, mielőtt felvonták azt a zászlót.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
